import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum ItemStatus {
  LOST = 'LOST',
  FOUND = 'FOUND',
  REUNITED = 'REUNITED'
}

export enum Category {
  DOCUMENTS = 'Documentos',
  ELECTRONICS = 'Eletrónicos',
  PETS = 'Animais',
  WALLETS = 'Carteiras/Bolsas',
  KEYS = 'Chaves',
  OTHERS = 'Outros'
}

export interface User {
  id: string;
  name: string;
  phone: string;
  email: string;
}

export interface Item {
  id: string;
  title: string;
  description: string;
  category: Category;
  status: ItemStatus;
  location: string;
  province: string;
  reward?: number;
  date: string;
  imageUrl?: string;
  userId: string;
  createdAt: string;
}

export interface MatchResult {
  similarity: number;
  reasoning: string;
  isMatch: boolean;
}

import { GoogleGenAI, Type } from "@google/genai";
import { Item, MatchResult } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeItemMatch = async (lostItem: Item, foundItem: Item): Promise<MatchResult> => {
  const prompt = `
    Analise se estes dois itens podem ser o mesmo. 
    Item Perdido: Titulo: ${lostItem.title}, Descrição: ${lostItem.description}, Categoria: ${lostItem.category}, Província: ${lostItem.province}.
    Item Achado: Titulo: ${foundItem.title}, Descrição: ${foundItem.description}, Categoria: ${foundItem.category}, Província: ${foundItem.province}.

    Responda em formato JSON com:
    - similarity: um número de 0 a 100 indicando a probabilidade de ser o mesmo objeto.
    - reasoning: uma breve explicação em português do porquê.
    - isMatch: boolean, true se similarity > 70.
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            similarity: { type: Type.NUMBER },
            reasoning: { type: Type.STRING },
            isMatch: { type: Type.BOOLEAN }
          },
          required: ["similarity", "reasoning", "isMatch"]
        }
      }
    });

    const result = JSON.parse(response.text || "{}");
    return result as MatchResult;
  } catch (error) {
    console.error("Erro na análise de IA:", error);
    return { similarity: 0, reasoning: "Erro ao processar análise.", isMatch: false };
  }
};

export const generateAITags = async (description: string): Promise<string[]> => {
  const prompt = `Gere 5 tags (palavras-chave) curtas em português para esta descrição de objeto: "${description}". Responda apenas um array de strings em JSON.`;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: { type: Type.STRING }
        }
      }
    });
    return JSON.parse(response.text || "[]");
  } catch (error) {
    return [];
  }
};

