export default ItemCard;

import React, { useState } from 'react';
import { Item, ItemStatus } from '../types';
import { analyzeItemMatch } from '../services/geminiService';

interface ItemDetailsProps {
  item: Item;
  allContextItems: Item[];
  onBack: () => void;
}

const ItemDetails: React.FC<ItemDetailsProps> = ({ item, allContextItems, onBack }) => {
  const [analyzing, setAnalyzing] = useState(false);
  const [matchResult, setMatchResult] = useState<{item: Item, result: any} | null>(null);

  const handleCheckMatch = async () => {
    setAnalyzing(true);
    // Find potential candidates (opposite status, same category)
    const candidates = allContextItems.filter(i => 
      i.id !== item.id && 
      i.status !== item.status && 
      i.category === item.category
    );

    if (candidates.length === 0) {
      alert("Nenhum item similar encontrado no sistema ainda.");
      setAnalyzing(false);
      return;
    }

    // Just check the first one for demonstration
    const topCandidate = candidates[0];
    const res = await analyzeItemMatch(
      item.status === ItemStatus.LOST ? item : topCandidate,
      item.status === ItemStatus.FOUND ? item : topCandidate
    );

    setMatchResult({ item: topCandidate, result: res });
    setAnalyzing(false);
  };

  return (
    <div className="p-4 bg-white min-h-full">
      <button onClick={onBack} className="flex items-center text-emerald-600 mb-4 gap-2">
        <i className="fa-solid fa-arrow-left"></i> Voltar
      </button>

      <img 
        src={item.imageUrl} 
        alt={item.title} 
        className="w-full h-64 object-cover rounded-2xl shadow-lg mb-6"
      />

      <div className="space-y-4">
        <div>
          <span className={`inline-block px-3 py-1 rounded-full text-xs font-bold mb-2 ${
            item.status === ItemStatus.LOST ? 'bg-red-100 text-red-600' : 'bg-emerald-100 text-emerald-600'
          }`}>
            {item.status === ItemStatus.LOST ? 'PERDIDO' : 'ACHADO'}
          </span>
          <h2 className="text-2xl font-bold text-gray-900">{item.title}</h2>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div className="bg-gray-50 p-3 rounded-xl">
            <div className="text-gray-400 text-xs mb-1">Localização</div>
            <div className="text-sm font-semibold">{item.location}</div>
          </div>
          <div className="bg-gray-50 p-3 rounded-xl">
            <div className="text-gray-400 text-xs mb-1">Data</div>
            <div className="text-sm font-semibold">{new Date(item.date).toLocaleDateString('pt-MZ')}</div>
          </div>
        </div>

        {item.reward && (
          <div className="bg-yellow-50 border border-yellow-200 p-4 rounded-xl flex justify-between items-center">
            <span className="text-yellow-800 font-medium">Recompensa Oferecida:</span>
            <span className="text-xl font-bold text-yellow-700">{item.reward} MT</span>
          </div>
        )}

        <div>
          <h3 className="font-bold text-gray-700 mb-2">Descrição</h3>
          <p className="text-gray-600 leading-relaxed">{item.description}</p>
        </div>

        <div className="pt-4 flex flex-col gap-3">
          <button 
            onClick={handleCheckMatch}
            disabled={analyzing}
            className="w-full bg-indigo-600 text-white py-4 rounded-xl font-bold shadow-lg flex items-center justify-center gap-2 hover:bg-indigo-700 transition-colors disabled:opacity-50"
          >
            {analyzing ? (
              <><i className="fa-solid fa-circle-notch animate-spin"></i> Analisando por IA...</>
            ) : (
              <><i className="fa-solid fa-wand-magic-sparkles"></i> Procurar Correspondência com IA</>
            )}
          </button>

          <button className="w-full bg-emerald-600 text-white py-4 rounded-xl font-bold shadow-lg flex items-center justify-center gap-2">
            <i className="fa-solid fa-comment"></i> Entrar em Contacto
          </button>
        </div>

        {matchResult && (
          <div className="mt-8 p-6 bg-indigo-50 border-2 border-indigo-200 rounded-2xl animate-in fade-in slide-in-from-bottom-4 duration-500">
            <h4 className="font-bold text-indigo-900 mb-4 flex items-center gap-2">
              <i className="fa-solid fa-robot"></i> Resultado da IA
            </h4>
            <div className="flex gap-4 mb-4">
               <img src={matchResult.item.imageUrl} className="w-20 h-20 rounded-lg object-cover shadow-sm" />
               <div className="flex-1">
                 <div className="text-xs text-indigo-500 font-bold">POSSÍVEL MATCH ({matchResult.result.similarity}%)</div>
                 <div className="font-semibold text-gray-800">{matchResult.item.title}</div>
               </div>
            </div>
            <p className="text-sm text-indigo-800 italic bg-white p-3 rounded-lg">
              "{matchResult.result.reasoning}"
            </p>
            {matchResult.result.isMatch && (
              <div className="mt-4 bg-emerald-500 text-white p-2 rounded text-center text-xs font-bold">
                ALTA PROBABILIDADE DE ENCONTRO!
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default ItemDetails;

import React, { useState, useEffect, useMemo } from 'react';
import Layout from './components/Layout';
import ItemCard from './components/ItemCard';
import ItemDetails from './components/ItemDetails';
import { Item, ItemStatus, Category } from './types';
import { INITIAL_ITEMS, MOZAMBIQUE_PROVINCES } from './constants';
import { generateAITags } from './services/geminiService';

const App: React.FC = () => {
