  const [selectedItem, setSelectedItem] = useState<Item | null>(null);
  const [filter, setFilter] = useState<{status: ItemStatus | 'ALL', category: Category | 'ALL'}>({
    status: 'ALL',
    category: 'ALL'
  });
  const [searchQuery, setSearchQuery] = useState('');

  // Form states for new item
  const [newItem, setNewItem] = useState<Partial<Item>>({
    status: ItemStatus.LOST,
    category: Category.DOCUMENTS,
    province: 'Maputo Cidade',
    date: new Date().toISOString().split('T')[0]
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  const filteredItems = useMemo(() => {
    return items.filter(item => {
      const statusMatch = filter.status === 'ALL' || item.status === filter.status;
      const categoryMatch = filter.category === 'ALL' || item.category === filter.category;
      const searchMatch = item.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
                          item.description.toLowerCase().includes(searchQuery.toLowerCase());
      return statusMatch && categoryMatch && searchMatch;
    }).sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  }, [items, filter, searchQuery]);

  const handlePostSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

