          <input 
            className="w-full bg-gray-50 border border-gray-200 rounded-xl p-3"
            placeholder="Ex: Próximo à Praça da Independência"
            value={newItem.location || ''}
            onChange={e => setNewItem({...newItem, location: e.target.value})}
          />
