        {newItem.status === ItemStatus.LOST && (
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-1">Recompensa (MT) - Opcional</label>
            <input 
              type="number"
              className="w-full bg-gray-50 border border-gray-200 rounded-xl p-3"
              placeholder="Ex: 500"
              value={newItem.reward || ''}
              onChange={e => setNewItem({...newItem, reward: Number(e.target.value)})}
            />
          </div>
        )}

        <button 
          disabled={isSubmitting}
          className="w-full bg-emerald-600 text-white py-4 rounded-xl font-bold shadow-lg hover:bg-emerald-700 disabled:opacity-50 mt-4"
        >
          {isSubmitting ? 'A publicar...' : 'Publicar Agora'}
        </button>
      </form>
    </div>
  );

  const renderProfile = () => (
    <div className="p-6 text-center">
      <div className="w-24 h-24 bg-emerald-100 rounded-full mx-auto mb-4 flex items-center justify-center text-emerald-600 text-3xl font-bold">
        U
      </div>
      <h2 className="text-xl font-bold">Utilizador Convidado</h2>
      <p className="text-gray-500 text-sm mb-8">Inicie sessão para gerir os seus itens</p>

      <div className="space-y-3">
        <button className="w-full bg-white border border-gray-200 p-4 rounded-xl flex items-center gap-3">
          <i className="fa-solid fa-list-check text-emerald-600"></i>
          <span className="font-semibold">Meus Registos</span>
          <i className="fa-solid fa-chevron-right ml-auto text-gray-300"></i>
        </button>
        <button className="w-full bg-white border border-gray-200 p-4 rounded-xl flex items-center gap-3">
          <i className="fa-solid fa-heart text-red-500"></i>
          <span className="font-semibold">Itens Guardados</span>
          <i className="fa-solid fa-chevron-right ml-auto text-gray-300"></i>
        </button>
        <button className="w-full bg-white border border-gray-200 p-4 rounded-xl flex items-center gap-3">
          <i className="fa-solid fa-shield-halved text-blue-500"></i>
          <span className="font-semibold">Segurança e Privacidade</span>
          <i className="fa-solid fa-chevron-right ml-auto text-gray-300"></i>
        </button>
      </div>

      <button className="mt-12 text-red-500 font-bold flex items-center gap-2 mx-auto">
        <i className="fa-solid fa-right-from-bracket"></i> Terminar Sessão
      </button>
    </div>
  );

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      {selectedItem ? (
        <ItemDetails 
          item={selectedItem} 
          allContextItems={items}
          onBack={() => setSelectedItem(null)} 
        />
      ) : (
        <>
          {activeTab === 'feed' && renderFeed()}
          {activeTab === 'post' && renderPostForm()}
          {activeTab === 'profile' && renderProfile()}
        </>
      )}
    </Layout>
  );
};

