          <img src={item.imageUrl} className="w-full h-full object-cover" alt="" />
        </div>
        <div className="flex-1 overflow-hidden">
          <div className="font-black text-xs uppercase truncate">{item.title}</div>
          <div className="text-[10px] text-gray-400 font-bold uppercase">Chat de Resgate</div>
        </div>
        <button className="text-[#d21034] text-lg p-2">
          <i className="fa-solid fa-flag"></i>
        </button>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.length === 0 && (
          <div className="text-center py-10 opacity-30 grayscale">
            <i className="fa-solid fa-comments text-4xl mb-2"></i>
            <p className="text-[10px] font-black uppercase">Inicie a conversa com segurança.</p>
          </div>
        )}
        {messages.map((msg) => {
          const isMe = msg.senderId === 'currentUser';
          return (
            <div key={msg.id} className={`flex ${isMe ? 'justify-end' : 'justify-start'}`}>
              <div className={`max-w-[80%] p-3 rounded-2xl shadow-sm text-sm font-medium ${
