          )}
          {activeTab === 'profile' && (
            <div className="p-6 text-center">
              <div className="w-28 h-28 bg-gradient-to-tr from-[#009739] to-[#fce100] rounded-full mx-auto mb-6 p-1">
                <div className="bg-white rounded-full w-full h-full flex items-center justify-center text-[#d21034] text-4xl font-black">
                  <img src="https://api.dicebear.com/7.x/avataaars/svg?seed=Moz" alt="Profile" />
                </div>
              </div>
              <h2 className="text-2xl font-black text-gray-900 uppercase">Utilizador Moz</h2>
              <p className="text-gray-400 font-bold text-xs mb-8 uppercase tracking-widest">Maputo, Moçambique</p>
              <div className="space-y-3">
                <button className="w-full bg-white border-2 border-gray-50 p-4 rounded-2xl flex items-center gap-4 hover:border-[#fce100] transition-colors group">
                  <div className="bg-emerald-100 text-[#009739] p-3 rounded-xl group-hover:bg-[#009739] group-hover:text-white transition-colors"><i className="fa-solid fa-briefcase"></i></div>
