import React, { useState } from 'react';
import { Item, ItemStatus } from '../types';
import { analyzeItemMatch } from '../services/geminiService';

interface ItemDetailsProps {
  item: Item;
  allContextItems: Item[];
  onBack: () => void;
  onStartChat: (item: Item) => void;
}

const ItemDetails: React.FC<ItemDetailsProps> = ({ item, allContextItems, onBack, onStartChat }) => {
  const [analyzing, setAnalyzing] = useState(false);
  const [matchResult, setMatchResult] = useState<{item: Item, result: any} | null>(null);
  const [currentImgIndex, setCurrentImgIndex] = useState(0);

  const images = item.imageUrls && item.imageUrls.length > 0 
    ? item.imageUrls 
    : [item.imageUrl || 'https://picsum.photos/seed/placeholder/400/300'];

  const nextImage = () => {
    setCurrentImgIndex((prev) => (prev + 1) % images.length);
  };

  const prevImage = () => {
    setCurrentImgIndex((prev) => (prev - 1 + images.length) % images.length);
  };

  const handleCheckMatch = async () => {
    setAnalyzing(true);
    const candidates = allContextItems.filter(i => 
      i.id !== item.id && 
      i.status !== item.status && 
      i.category === item.category
    );

    if (candidates.length === 0) {
      alert("Nenhum item similar encontrado no sistema ainda.");
      setAnalyzing(false);
      return;
    }

    const topCandidate = candidates[0];
    const res = await analyzeItemMatch(
      item.status === ItemStatus.LOST ? item : topCandidate,
      item.status === ItemStatus.FOUND ? item : topCandidate
    );

    setMatchResult({ item: topCandidate, result: res });
    setAnalyzing(false);
  };

  return (
    <div className="p-4 bg-white min-h-full pb-10">
      <button 
        onClick={onBack} 
        className="flex items-center text-[#009739] mb-4 gap-2 font-black uppercase text-xs hover:translate-x-[-4px] transition-transform"
      >
        <i className="fa-solid fa-arrow-left"></i> Voltar à Explorar
      </button>

      {/* Image Carousel */}
      <div className="relative group mb-6 overflow-hidden rounded-3xl shadow-2xl bg-gray-100 aspect-video">
        <div 
          className="flex transition-transform duration-500 ease-out h-full"
          style={{ transform: `translateX(-${currentImgIndex * 100}%)` }}
        >
          {images.map((img, idx) => (
            <img 
              key={idx}
              src={img} 
              alt={`${item.title} - ${idx + 1}`} 
              className="w-full h-full object-cover flex-shrink-0"
            />
          ))}
        </div>

        {images.length > 1 && (
          <>
            <button 
              onClick={prevImage}
              className="absolute left-4 top-1/2 -translate-y-1/2 bg-white/80 hover:bg-white text-black p-3 rounded-full shadow-lg opacity-0 group-hover:opacity-100 transition-opacity"
            >
              <i className="fa-solid fa-chevron-left"></i>
            </button>
            <button 
              onClick={nextImage}
              className="absolute right-4 top-1/2 -translate-y-1/2 bg-white/80 hover:bg-white text-black p-3 rounded-full shadow-lg opacity-0 group-hover:opacity-100 transition-opacity"
            >
              <i className="fa-solid fa-chevron-right"></i>
            </button>

            {/* Dots Indicator */}
            <div className="absolute bottom-4 left-1/2 -translate-x-1/2 flex gap-2">
              {images.map((_, idx) => (
                <button
                  key={idx}
                  onClick={() => setCurrentImgIndex(idx)}
                  className={`h-2 rounded-full transition-all ${
                    idx === currentImgIndex 
                      ? 'w-6 bg-[#fce100]' 
                      : 'w-2 bg-white/50'
                  }`}
                />
              ))}
            </div>
          </>
        )}

        <div className={`absolute top-4 right-4 px-4 py-1.5 rounded-full text-[10px] font-black uppercase shadow-lg ${
          item.status === ItemStatus.LOST ? 'bg-[#d21034] text-white' : 'bg-[#009739] text-white'
        }`}>
          {item.status === ItemStatus.LOST ? 'Perdido' : 'Achado'}
        </div>
      </div>

      <div className="space-y-6">
        <div>
          <div className="text-[10px] text-[#009739] font-black uppercase tracking-[0.2em] mb-1">{item.category}</div>
          <h2 className="text-3xl font-black text-gray-900 leading-tight uppercase tracking-tight">{item.title}</h2>
        </div>

        <div className="grid grid-cols-2 gap-3">
          <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100">
            <div className="text-gray-400 text-[10px] font-black uppercase mb-1">Localização</div>
            <div className="text-sm font-bold flex items-center gap-2 uppercase truncate">
              <i className="fa-solid fa-location-dot text-[#d21034]"></i>
              {item.location}
            </div>
            <div className="text-[10px] text-gray-500 font-black mt-1 uppercase">{item.province}</div>
          </div>
          <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100">
            <div className="text-gray-400 text-[10px] font-black uppercase mb-1">Data Registo</div>
            <div className="text-sm font-bold flex items-center gap-2">
              <i className="fa-solid fa-calendar text-[#009739]"></i>
              {new Date(item.date).toLocaleDateString('pt-MZ')}
            </div>
          </div>
        </div>

        {item.reward && (
          <div className="bg-gradient-to-r from-[#fce100] to-yellow-500 p-5 rounded-2xl flex justify-between items-center shadow-lg border-2 border-white">
            <div className="flex items-center gap-3">
              <i className="fa-solid fa-coins text-2xl text-yellow-900 opacity-50"></i>
              <span className="text-yellow-900 font-black uppercase text-[10px]">Recompensa</span>
            </div>
            <span className="text-2xl font-black text-black">{item.reward} MT</span>
          </div>
        )}

        <div>
          <h3 className="font-black text-gray-400 uppercase text-[10px] mb-3 tracking-widest flex items-center gap-2">
            <span className="w-8 h-1 bg-[#d21034] rounded-full"></span>
            Descrição
          </h3>
          <p className="text-gray-700 leading-relaxed font-bold bg-gray-50 p-4 rounded-2xl border border-dashed border-gray-200 text-sm">{item.description}</p>
        </div>

        <div className="pt-4 flex flex-col gap-3">
          <button 
            onClick={handleCheckMatch}
            disabled={analyzing}
            className="w-full bg-black text-[#fce100] py-5 rounded-2xl font-black shadow-xl flex items-center justify-center gap-3 hover:bg-gray-900 transition-all active:scale-95 disabled:opacity-50 uppercase tracking-widest text-xs"
          >
            {analyzing ? (
              <><i className="fa-solid fa-circle-notch animate-spin"></i> IA Analisando...</>
            ) : (
              <><i className="fa-solid fa-wand-magic-sparkles"></i> Verificar Correspondência</>
            )}
          </button>

          <button 
            onClick={() => onStartChat(item)}
            className="w-full bg-[#009739] text-white py-5 rounded-2xl font-black shadow-xl flex items-center justify-center gap-3 hover:bg-[#007b2e] transition-all active:scale-95 uppercase tracking-widest text-xs"
          >
            <i className="fa-solid fa-comment-dots"></i> Iniciar Chat de Resgate
          </button>
        </div>

        {matchResult && (
          <div className="mt-8 p-6 bg-indigo-50 border-4 border-white rounded-[2rem] shadow-2xl animate-in fade-in slide-in-from-bottom-4 duration-500 ring-1 ring-indigo-100">
            <div className="flex items-center justify-between mb-4">
               <h4 className="font-black text-indigo-900 text-[10px] flex items-center gap-2 uppercase tracking-widest">
                <i className="fa-solid fa-robot text-indigo-500"></i> Relatório IA
              </h4>
              <span className={`px-2 py-1 rounded text-[9px] font-black uppercase ${matchResult.result.isMatch ? 'bg-[#009739] text-white' : 'bg-amber-500 text-white'}`}>
                {matchResult.result.similarity}% de Match
              </span>
            </div>

            <div className="flex gap-4 mb-4 bg-white/50 p-3 rounded-2xl items-center">
               <img src={matchResult.item.imageUrl} className="w-14 h-14 rounded-xl object-cover shadow-sm ring-2 ring-white" alt="" />
               <div className="flex-1 min-w-0">
                 <div className="text-[9px] text-indigo-500 font-black uppercase mb-0.5">Potencial Encontro</div>
                 <div className="font-black text-gray-800 text-[11px] truncate uppercase">{matchResult.item.title}</div>
                 <div className="text-[9px] text-gray-400 font-bold uppercase">{matchResult.item.province}</div>
               </div>
            </div>

            <p className="text-[11px] text-indigo-800 font-bold leading-relaxed bg-white/80 p-3 rounded-xl border border-indigo-100 italic">
              "{matchResult.result.reasoning}"
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

