                  </select>
                  <select className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 text-sm font-bold shadow-sm" value={newItem.province} onChange={e => setNewItem({...newItem, province: e.target.value})}>
