                <div className="bg-white rounded-full w-full h-full flex items-center justify-center text-[#d21034] text-4xl font-black">
                  <img src="https://api.dicebear.com/7.x/avataaars/svg?seed=Moz" alt="Profile" />
                </div>
              </div>
              <h2 className="text-2xl font-black text-gray-900 uppercase">Utilizador Moz</h2>
              <p className="text-gray-400 font-bold text-xs mb-8 uppercase tracking-widest">Maputo, Moçambique</p>
              <div className="space-y-3">
                <button className="w-full bg-white border-2 border-gray-50 p-4 rounded-2xl flex items-center gap-4 hover:border-[#fce100] transition-colors group">
                  <div className="bg-emerald-100 text-[#009739] p-3 rounded-xl group-hover:bg-[#009739] group-hover:text-white transition-colors"><i className="fa-solid fa-briefcase"></i></div>
                  <span className="font-black text-gray-700 uppercase text-xs">Meus Registos</span>
                </button>
                <button className="w-full bg-white border-2 border-gray-50 p-4 rounded-2xl flex items-center gap-4 hover:border-[#fce100] transition-colors group">
                  <div className="bg-red-100 text-[#d21034] p-3 rounded-xl group-hover:bg-[#d21034] group-hover:text-white transition-colors"><i className="fa-solid fa-comments"></i></div>
                  <span className="font-black text-gray-700 uppercase text-xs">Mensagens</span>
                </button>
              </div>
            </div>
          )}
        </>
      )}
    </Layout>
  );
};

export default App;

import React, { useEffect, useRef } from 'react';
// Fix: Import Leaflet library and its CSS to resolve 'Cannot find name L'
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import { Item, ItemStatus } from '../types';

interface MapViewProps {
  items: Item[];
  onViewDetails: (item: Item) => void;
}

const MapView: React.FC<MapViewProps> = ({ items, onViewDetails }) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<any>(null);
  const markersRef = useRef<any[]>([]);

  useEffect(() => {
    if (!mapContainerRef.current || mapRef.current) return;

    // Maputo coordinates as default
    const map = L.map(mapContainerRef.current).setView([-25.9692, 32.5732], 13);

    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'
    }).addTo(map);

    mapRef.current = map;

    // Get user location if possible
    if ("geolocation" in navigator) {
      navigator.geolocation.getCurrentPosition((position) => {
        map.setView([position.coords.latitude, position.coords.longitude], 14);
      });
    }

    return () => {
      if (mapRef.current) {
        mapRef.current.remove();
        mapRef.current = null;
      }
    };
  }, []);

  useEffect(() => {
    if (!mapRef.current) return;

    // Clear old markers
    markersRef.current.forEach(marker => marker.remove());
    markersRef.current = [];

    items.forEach(item => {
      if (item.latitude && item.longitude) {
        const isLost = item.status === ItemStatus.LOST;
        const color = isLost ? '#d21034' : '#009739';

        const markerIcon = L.divIcon({
          className: 'custom-div-icon',
          html: `
            <div style="
              background-color: ${color};
              width: 30px;
              height: 30px;
              border-radius: 50% 50% 50% 0;
              transform: rotate(-45deg);
              display: flex;
              align-items: center;
              justify-content: center;
              border: 2px solid white;
              box-shadow: 0 4px 6px rgba(0,0,0,0.3);
            ">
              <i class="${isLost ? 'fa-solid fa-search' : 'fa-solid fa-hand-holding-heart'}" style="
                color: white;
                transform: rotate(45deg);
                font-size: 12px;
              "></i>
            </div>
          `,
          iconSize: [30, 30],
          iconAnchor: [15, 30]
        });

        const marker = L.marker([item.latitude, item.longitude], { icon: markerIcon })
          .addTo(mapRef.current);

        const popupContent = document.createElement('div');
        popupContent.className = 'p-0 overflow-hidden rounded-2xl';
        popupContent.innerHTML = `
          <div class="w-full">
            <img src="${item.imageUrl}" class="w-full h-24 object-cover" />
            <div class="p-3">
              <div class="text-[8px] font-black uppercase text-gray-400 mb-1">${item.category}</div>
              <h4 class="font-black text-xs uppercase leading-tight line-clamp-1 mb-1">${item.title}</h4>
              <div class="flex items-center justify-between mt-2">
                <span class="text-[8px] font-black uppercase px-2 py-0.5 rounded-full ${isLost ? 'bg-red-100 text-red-600' : 'bg-green-100 text-green-600'}">
                  ${isLost ? 'Perdido' : 'Achado'}
                </span>
                <button id="view-btn-${item.id}" class="text-[8px] font-black uppercase text-indigo-600 underline">Detalhes</button>
              </div>
            </div>
          </div>
        `;

        marker.bindPopup(popupContent);

        // Listen for detail view click inside popup
        marker.on('popupopen', () => {
          document.getElementById(`view-btn-${item.id}`)?.addEventListener('click', () => {
            onViewDetails(item);
          });
        });

        markersRef.current.push(marker);
      }
    });
  }, [items, onViewDetails]);

  return (
    <div className="w-full h-full relative">
      <div ref={mapContainerRef} className="w-full h-full z-0" />
      <div className="absolute bottom-4 left-4 z-10 space-y-2 pointer-events-none">
          <div className="bg-white/90 backdrop-blur p-2 rounded-xl shadow-lg border border-gray-100 flex items-center gap-2 pointer-events-auto">
              <div className="w-3 h-3 rounded-full bg-[#d21034]"></div>
              <span className="text-[9px] font-black uppercase tracking-widest">Perdidos</span>
          </div>
          <div className="bg-white/90 backdrop-blur p-2 rounded-xl shadow-lg border border-gray-100 flex items-center gap-2 pointer-events-auto">
              <div className="w-3 h-3 rounded-full bg-[#009739]"></div>
              <span className="text-[9px] font-black uppercase tracking-widest">Achados</span>
          </div>
      </div>
    </div>
  );
};

export default MapView;

import React, { useState, useEffect, useRef } from 'react';
import { Item, Message } from '../types';

interface ChatViewProps {
  item: Item;
  messages: Message[];
  onSendMessage: (text: string) => void;
  onBack: () => void;
  notificationCount: number;
}

const ChatView: React.FC<ChatViewProps> = ({ item, messages, onSendMessage, onBack, notificationCount }) => {
  const [inputText, setInputText] = useState('');
  const scrollRef = useRef<HTMLDivElement>(null);
  const [isTyping, setIsTyping] = useState(false);

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });

    // Simulate a brief "live" effect when messages update
    if (messages.length > 0) {
      setIsTyping(true);
      const timer = setTimeout(() => setIsTyping(false), 2000);
      return () => clearTimeout(timer);
    }
  }, [messages]);

  const handleSend = (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputText.trim()) return;
    onSendMessage(inputText);
    setInputText('');
  };

  return (
    <div className="flex flex-col h-full bg-[#f9f9f9]">
      {/* Chat Header */}
      <div className="bg-white p-4 border-b flex items-center gap-3 sticky top-0 z-20 shadow-sm">
        <button onClick={onBack} className="text-[#009739] p-2 relative active:scale-90 transition-transform">
          <i className="fa-solid fa-arrow-left"></i>
          {notificationCount > 0 && (
            <span className="absolute top-0 right-0 bg-[#d21034] text-white text-[7px] font-black w-3.5 h-3.5 flex items-center justify-center rounded-full border border-white shadow-sm animate-bounce">
              {notificationCount}
            </span>
          )}
        </button>

        <div className="w-10 h-10 rounded-full overflow-hidden border-2 border-gray-100 shadow-sm">
          <img src={item.imageUrl} className="w-full h-full object-cover" alt="" />
        </div>

        <div className="flex-1 overflow-hidden">
          <div className="font-black text-xs uppercase truncate text-gray-900">{item.title}</div>
          <div className="flex items-center gap-1.5">
            <div className={`w-1.5 h-1.5 rounded-full ${isTyping ? 'bg-[#009739] animate-pulse' : 'bg-gray-300'}`}></div>
            <div className="text-[9px] text-gray-400 font-black uppercase tracking-wider">
              {isTyping ? 'Recebendo...' : 'Chat de Resgate'}
            </div>
          </div>
        </div>

        <div className="flex items-center gap-1">
          <button className="text-gray-300 hover:text-[#d21034] text-sm p-2 transition-colors">
            <i className="fa-solid fa-flag"></i>
          </button>
        </div>
      </div>

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4 no-scrollbar">
        {messages.length === 0 && (
          <div className="text-center py-16 px-10">
            <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mx-auto mb-4 shadow-sm text-[#009739]">
               <i className="fa-solid fa-shield-halved text-2xl"></i>
            </div>
            <h3 className="text-[10px] font-black uppercase text-gray-400 mb-1">Conversa Segura</h3>
            <p className="text-[11px] text-gray-500 font-bold leading-relaxed">
              Inicie a conversa para combinar a entrega do item. Lembre-se de marcar encontros apenas em locais públicos e seguros.
            </p>
          </div>
        )}

        {messages.map((msg, index) => {
          const isMe = msg.senderId === 'currentUser';
          const showTime = index === messages.length - 1 || 
            new Date(messages[index + 1].timestamp).getTime() - new Date(msg.timestamp).getTime() > 300000;

          return (
            <div key={msg.id} className={`flex flex-col ${isMe ? 'items-end' : 'items-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}>
              <div className={`max-w-[85%] p-3.5 rounded-2xl shadow-sm text-[13px] font-bold leading-snug ${
                isMe 
                  ? 'bg-black text-[#fce100] rounded-tr-none' 
                  : 'bg-white text-gray-800 rounded-tl-none border border-gray-100'
              }`}>
                {msg.text}
              </div>
              {showTime && (
                <div className="text-[8px] mt-1 px-1 opacity-40 font-black uppercase tracking-tighter">
                  {new Date(msg.timestamp).toLocaleTimeString('pt-MZ', { hour: '2-digit', minute: '2-digit' })}
                </div>
              )}
            </div>
          );
        })}
        <div ref={scrollRef} />
      </div>

      {/* Input */}
      <div className="p-4 bg-white border-t border-gray-100 shadow-[0_-4px_10px_rgba(0,0,0,0.02)]">
        <form onSubmit={handleSend} className="flex gap-2 items-center">
          <div className="flex-1 relative">
            <input 
              type="text"
              placeholder="Escreva sua mensagem..."
              className="w-full bg-gray-50 border-2 border-transparent focus:border-[#009739] rounded-2xl px-5 py-3.5 text-sm font-bold outline-none transition-all placeholder:text-gray-300"
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
            />
          </div>
          <button 
            type="submit"
            disabled={!inputText.trim()}
            className="bg-[#009739] text-white w-12 h-12 rounded-2xl flex items-center justify-center shadow-lg active:scale-95 transition-all disabled:opacity-30 disabled:grayscale"
          >
            <i className="fa-solid fa-paper-plane text-lg"></i>
          </button>
        </form>
        <div className="mt-2 text-center">
           <span className="text-[8px] font-black text-gray-300 uppercase tracking-[0.2em]">Dica: Nunca envie dinheiro adiantado</span>
        </div>
      </div>
    </div>
  );
};

export default ChatView;

import React, { useState, useMemo, useEffect } from 'react';
import Layout from './components/Layout';
import ItemCard from './components/ItemCard';
import ItemDetails from './components/ItemDetails';
import ChatView from './components/ChatView';
import MapView from './components/MapView';
import NotificationDrawer from './components/NotificationDrawer';
import { Item, ItemStatus, Category, Message, Notification } from './types';
import { INITIAL_ITEMS, MOZAMBIQUE_PROVINCES } from './constants';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'feed' | 'post' | 'profile'>('feed');
  const [viewMode, setViewMode] = useState<'list' | 'map'>('list');
  const [items, setItems] = useState<Item[]>(INITIAL_ITEMS);
  const [selectedItem, setSelectedItem] = useState<Item | null>(null);
  const [activeChat, setActiveChat] = useState<Item | null>(null);
  const [showFilters, setShowFilters] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);

  // Estado de Mensagens e Notificações
  const [messages, setMessages] = useState<Message[]>([]);
  const [notifications, setNotifications] = useState<Notification[]>([]);

  const [filters, setFilters] = useState({
    status: 'ALL' as ItemStatus | 'ALL',
    category: 'ALL' as Category | 'ALL',
    province: 'ALL' as string | 'ALL',
    date: '' as string,
    searchQuery: ''
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [newItem, setNewItem] = useState<Partial<Item>>({
    status: ItemStatus.LOST,
    category: Category.DOCUMENTS,
    province: 'Maputo Cidade',
    date: new Date().toISOString().split('T')[0]
  });

  const activeFiltersCount = useMemo(() => {
    let count = 0;
    if (filters.status !== 'ALL') count++;
    if (filters.category !== 'ALL') count++;
    if (filters.province !== 'ALL') count++;
    if (filters.date !== '') count++;
    return count;
  }, [filters]);

  const unreadNotificationsCount = useMemo(() => {
    return notifications.filter(n => !n.isRead).length;
  }, [notifications]);

  const filteredItems = useMemo(() => {
    return items.filter(item => {
      const statusMatch = filters.status === 'ALL' || item.status === filters.status;
      const categoryMatch = filters.category === 'ALL' || item.category === filters.category;
      const provinceMatch = filters.province === 'ALL' || item.province === filters.province;
      const dateMatch = !filters.date || item.date === filters.date;
      const searchMatch = !filters.searchQuery || 
                          item.title.toLowerCase().includes(filters.searchQuery.toLowerCase()) || 
                          item.description.toLowerCase().includes(filters.searchQuery.toLowerCase());

      return statusMatch && categoryMatch && provinceMatch && dateMatch && searchMatch;
    }).sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  }, [items, filters]);

  const handlePostSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    const id = Math.random().toString(36).substr(2, 9);

    // Default Maputo coordinates for new posts
    const lat = -25.9692 + (Math.random() - 0.5) * 0.05;
    const lng = 32.5732 + (Math.random() - 0.5) * 0.05;

    const item: Item = {
      id,
      title: newItem.title || 'Sem Título',
      description: newItem.description || '',
      category: newItem.category as Category,
      status: newItem.status as ItemStatus,
      location: newItem.location || 'N/A',
      province: newItem.province || 'Maputo Cidade',
      date: newItem.date || new Date().toISOString(),
      reward: newItem.reward,
      imageUrl: `https://picsum.photos/seed/${id}/400/300`,
      imageUrls: [`https://picsum.photos/seed/${id}/400/300`, `https://picsum.photos/seed/${id}b/400/300`],
      userId: 'currentUser',
      createdAt: new Date().toISOString(),
      latitude: lat,
      longitude: lng
    };

    setItems(prev => [item, ...prev]);

    // Lógica de Notificação para Itens Similares (Simulada)
    const matches = items.filter(existing => 
      existing.status !== item.status && 
      existing.category === item.category &&
      existing.province === item.province
    );

    if (matches.length > 0) {
      const matchNotif: Notification = {
        id: Math.random().toString(36).substr(2, 5),
        type: 'MATCH',
        title: 'Possível Correspondência Encontrada!',
        description: `Detectamos que o seu item "${item.title}" pode ser o mesmo que "${matches[0].title}" reportado recentemente.`,
        itemId: matches[0].id,
        timestamp: new Date().toISOString(),
        isRead: false
      };
      setTimeout(() => {
        setNotifications(prev => [matchNotif, ...prev]);
      }, 1500);
    }

    setIsSubmitting(false);
    setActiveTab('feed');
    setNewItem({
      status: ItemStatus.LOST,
      category: Category.DOCUMENTS,
      province: 'Maputo Cidade',
      date: new Date().toISOString().split('T')[0]
    });
  };

  const handleSendMessage = (text: string) => {
    if (!activeChat) return;
    const msg: Message = {
      id: Math.random().toString(36).substr(2, 9),
      itemId: activeChat.id,
      senderId: 'currentUser',
      receiverId: activeChat.userId,
      text,
      timestamp: new Date().toISOString()
    };
    setMessages(prev => [...prev, msg]);

    setTimeout(() => {
      const reply: Message = {
        id: Math.random().toString(36).substr(2, 9),
        itemId: activeChat.id,
        senderId: activeChat.userId,
        receiverId: 'currentUser',
        text: `Olá! Recebi sua mensagem sobre o "${activeChat.title}". Podemos conversar sobre os detalhes?`,
        timestamp: new Date().toISOString()
      };
      setMessages(prev => [...prev, reply]);

      // Notificação de Mensagem (apenas se for relevante para mostrar no cabeçalho ou badge)
      setNotifications(prev => [{
        id: Math.random().toString(36).substr(2, 5),
        type: 'MESSAGE',
        title: 'Nova Mensagem de Resgate',
        description: `Você recebeu uma nova mensagem sobre "${activeChat.title}".`,
        itemId: activeChat.id,
        timestamp: new Date().toISOString(),
        isRead: false
      }, ...prev]);
    }, 2000);
  };

  const handleNotificationClick = (notif: Notification) => {
    const item = items.find(i => i.id === notif.itemId);
    if (item) {
      setSelectedItem(item);
      setNotifications(prev => prev.map(n => n.id === notif.id ? { ...n, isRead: true } : n));
      setShowNotifications(false);
    }
  };

  const resetFilters = () => {
    setFilters({
      status: 'ALL',
      category: 'ALL',
      province: 'ALL',
      date: '',
      searchQuery: ''
    });
  };

  const renderFeed = () => (
    <div className="h-full flex flex-col">
      <div className="p-4 space-y-4 bg-white border-b shadow-sm z-10">
        <div className="flex items-center justify-between">
          <h2 className="text-xl font-black text-gray-900 border-l-4 border-[#d21034] pl-3 uppercase">
            Radar Moçambique
          </h2>
          <div className="flex bg-gray-100 p-1 rounded-xl">
            <button 
              onClick={() => setViewMode('list')}
              className={`p-2 px-4 rounded-lg text-[10px] font-black uppercase transition-all ${viewMode === 'list' ? 'bg-white shadow-sm text-[#009739]' : 'text-gray-400'}`}
            >
              <i className="fa-solid fa-list mr-2"></i> Lista
            </button>
            <button 
              onClick={() => setViewMode('map')}
              className={`p-2 px-4 rounded-lg text-[10px] font-black uppercase transition-all ${viewMode === 'map' ? 'bg-white shadow-sm text-[#009739]' : 'text-gray-400'}`}
            >
              <i className="fa-solid fa-map-location-dot mr-2"></i> Mapa
            </button>
          </div>
        </div>

        <div className="flex gap-2">
          <div className="relative flex-1">
            <i className="fa-solid fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"></i>
            <input 
              type="text" 
              placeholder="Ex: BI, Chaves, Cão..." 
              className="w-full bg-gray-50 border-2 border-transparent focus:border-[#009739] rounded-xl py-3 pl-10 pr-4 outline-none transition-all text-sm"
              value={filters.searchQuery}
              onChange={(e) => setFilters({ ...filters, searchQuery: e.target.value })}
            />
          </div>
          <button 
            onClick={() => setShowFilters(!showFilters)}
            className={`px-4 rounded-xl border-2 transition-all flex items-center gap-2 ${showFilters || activeFiltersCount > 0 ? 'bg-[#fce100] border-[#fce100] text-black' : 'bg-white border-gray-100 text-gray-400'}`}
          >
            <i className="fa-solid fa-sliders"></i>
            {activeFiltersCount > 0 && <span className="bg-black text-white text-[10px] rounded-full w-4 h-4 flex items-center justify-center font-bold">{activeFiltersCount}</span>}
          </button>
        </div>

        {showFilters && (
          <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100 grid grid-cols-2 gap-3 animate-in fade-in slide-in-from-top-2 duration-300">
            <div className="col-span-2">
              <label className="text-[10px] font-black text-gray-400 uppercase mb-1 block">Estado</label>
              <div className="flex gap-2">
                {['ALL', ItemStatus.LOST, ItemStatus.FOUND].map((s) => (
                  <button
                    key={s}
                    onClick={() => setFilters({...filters, status: s as any})}
                    className={`flex-1 py-2 rounded-lg text-xs font-bold border-2 transition-all ${filters.status === s ? 'bg-black border-black text-white' : 'bg-white border-gray-200 text-gray-400'}`}
                  >
                    {s === 'ALL' ? 'Todos' : s === ItemStatus.LOST ? 'Perdido' : 'Achado'}
                  </button>
                ))}
              </div>
            </div>
            <div>
              <label className="text-[10px] font-black text-gray-400 uppercase mb-1 block">Província</label>
              <select className="w-full bg-white border-2 border-gray-200 rounded-lg p-2 text-xs font-semibold outline-none" value={filters.province} onChange={e => setFilters({...filters, province: e.target.value})}>
                <option value="ALL">Todas</option>
                {MOZAMBIQUE_PROVINCES.map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>
            <div>
              <label className="text-[10px] font-black text-gray-400 uppercase mb-1 block">Data</label>
              <input type="date" className="w-full bg-white border-2 border-gray-200 rounded-lg p-2 text-xs font-semibold outline-none" value={filters.date} onChange={e => setFilters({...filters, date: e.target.value})} />
            </div>
            <div className="col-span-2">
              <label className="text-[10px] font-black text-gray-400 uppercase mb-1 block">Categoria</label>
              <select className="w-full bg-white border-2 border-gray-200 rounded-lg p-2 text-xs font-semibold outline-none" value={filters.category} onChange={e => setFilters({...filters, category: e.target.value as Category | 'ALL'})}>
                <option value="ALL">Todas as Categorias</option>
                {Object.values(Category).map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>
          </div>
        )}
      </div>

      <div className="flex-1 overflow-hidden">
        {viewMode === 'list' ? (
          <div className="p-4 grid grid-cols-2 gap-4 overflow-y-auto h-full pb-24">
            {filteredItems.map(item => (
              <ItemCard key={item.id} item={item} onViewDetails={setSelectedItem} />
            ))}
            {filteredItems.length === 0 && (
              <div className="col-span-2 text-center py-20">
                <p className="text-gray-400 font-bold">Nenhum item encontrado.</p>
              </div>
            )}
          </div>
        ) : (
          <div className="w-full h-full pb-20">
             <MapView items={filteredItems} onViewDetails={setSelectedItem} />
          </div>
        )}
      </div>
    </div>
  );

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={setActiveTab} 
      notificationCount={unreadNotificationsCount}
      onToggleNotifications={() => setShowNotifications(!showNotifications)}
    >
      {showNotifications && (
        <NotificationDrawer 
          notifications={notifications} 
          onClose={() => setShowNotifications(false)}
          onNotificationClick={handleNotificationClick}
          onClear={() => setNotifications([])}
        />
      )}

      {activeChat ? (
        <ChatView 
          item={activeChat} 
          messages={messages.filter(m => m.itemId === activeChat.id)}
          onSendMessage={handleSendMessage}
          onBack={() => setActiveChat(null)}
          notificationCount={unreadNotificationsCount}
        />
      ) : selectedItem ? (
        <ItemDetails 
          item={selectedItem} 
          allContextItems={items}
          onBack={() => setSelectedItem(null)} 
          onStartChat={(item) => setActiveChat(item)}
          onViewItem={(item) => setSelectedItem(item)}
        />
      ) : (
        <>
          {activeTab === 'feed' && renderFeed()}
          {activeTab === 'post' && (
            <div className="p-6 pb-24 overflow-y-auto h-full">
              <h2 className="text-2xl font-black mb-6 text-gray-900 border-l-8 border-[#fce100] pl-4 uppercase">Novo Registo</h2>
              <form onSubmit={handlePostSubmit} className="space-y-5">
                <div>
                  <label className="block text-xs font-black text-gray-500 uppercase mb-2">Estado</label>
                  <div className="grid grid-cols-2 gap-3">
                    <button type="button" onClick={() => setNewItem({...newItem, status: ItemStatus.LOST})} className={`p-4 rounded-2xl border-2 font-black transition-all ${newItem.status === ItemStatus.LOST ? 'border-[#d21034] bg-[#d21034] text-white shadow-lg' : 'border-gray-100 bg-gray-50 text-gray-400'}`}>PERDI</button>
                    <button type="button" onClick={() => setNewItem({...newItem, status: ItemStatus.FOUND})} className={`p-4 rounded-2xl border-2 font-black transition-all ${newItem.status === ItemStatus.FOUND ? 'border-[#009739] bg-[#009739] text-white shadow-lg' : 'border-gray-100 bg-gray-50 text-gray-400'}`}>ACHEI</button>
                  </div>
                </div>
                <div className="bg-gray-50 p-6 rounded-3xl space-y-4 border border-gray-100">
                  <input required className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 outline-none font-semibold shadow-sm" placeholder="Título do Item..." value={newItem.title || ''} onChange={e => setNewItem({...newItem, title: e.target.value})} />
                  <select className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 text-sm font-bold shadow-sm" value={newItem.category} onChange={e => setNewItem({...newItem, category: e.target.value as Category})}>
                    {Object.values(Category).map(cat => <option key={cat} value={cat}>{cat}</option>)}
                  </select>
