import React, { useState, useMemo, useEffect } from 'react';
import Layout from './components/Layout';
import ItemCard from './components/ItemCard';
import ItemDetails from './components/ItemDetails';
import ChatView from './components/ChatView';
import MapView from './components/MapView';
import NotificationDrawer from './components/NotificationDrawer';
import { Item, ItemStatus, Category, Message, Notification } from './types';
import { INITIAL_ITEMS, MOZAMBIQUE_PROVINCES } from './constants';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'feed' | 'post' | 'profile'>('feed');
  const [viewMode, setViewMode] = useState<'list' | 'map'>('list');
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Inicialização de estado a partir do localStorage para suporte offline
  const [items, setItems] = useState<Item[]>(() => {
    const saved = localStorage.getItem('achei_items');
    return saved ? JSON.parse(saved) : INITIAL_ITEMS;
  });

  const [messages, setMessages] = useState<Message[]>(() => {
    const saved = localStorage.getItem('achei_messages');
    return saved ? JSON.parse(saved) : [];
  });

  const [notifications, setNotifications] = useState<Notification[]>(() => {
    const saved = localStorage.getItem('achei_notifications');
    return saved ? JSON.parse(saved) : [];
  });

  const [selectedItem, setSelectedItem] = useState<Item | null>(null);
  const [activeChat, setActiveChat] = useState<Item | null>(null);
  const [showFilters, setShowFilters] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);

  const [filters, setFilters] = useState({
    status: 'ALL' as ItemStatus | 'ALL',
    category: 'ALL' as Category | 'ALL',
    province: 'ALL' as string | 'ALL',
    date: '' as string,
    searchQuery: ''
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [newItem, setNewItem] = useState<Partial<Item>>({
    status: ItemStatus.LOST,
    category: Category.DOCUMENTS,
    province: 'Maputo Cidade',
    date: new Date().toISOString().split('T')[0]
  });

  // Monitorar status de rede
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Persistir dados sempre que mudarem
  useEffect(() => {
    localStorage.setItem('achei_items', JSON.stringify(items));
  }, [items]);

  useEffect(() => {
    localStorage.setItem('achei_messages', JSON.stringify(messages));
  }, [messages]);

  useEffect(() => {
    localStorage.setItem('achei_notifications', JSON.stringify(notifications));
  }, [notifications]);

  const activeFiltersCount = useMemo(() => {
    let count = 0;
    if (filters.status !== 'ALL') count++;
    if (filters.category !== 'ALL') count++;
    if (filters.province !== 'ALL') count++;
    if (filters.date !== '') count++;
    return count;
  }, [filters]);

  const unreadNotificationsCount = useMemo(() => {
    return notifications.filter(n => !n.isRead).length;
  }, [notifications]);

  const filteredItems = useMemo(() => {
    return items.filter(item => {
      const statusMatch = filters.status === 'ALL' || item.status === filters.status;
      const categoryMatch = filters.category === 'ALL' || item.category === filters.category;
      const provinceMatch = filters.province === 'ALL' || item.province === filters.province;
      const dateMatch = !filters.date || item.date === filters.date;
      const searchMatch = !filters.searchQuery || 
                          item.title.toLowerCase().includes(filters.searchQuery.toLowerCase()) || 
                          item.description.toLowerCase().includes(filters.searchQuery.toLowerCase());

      return statusMatch && categoryMatch && provinceMatch && dateMatch && searchMatch;
    }).sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  }, [items, filters]);

  const handlePostSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);

    const id = Math.random().toString(36).substr(2, 9);
    // Simulação de coordenadas perto de Maputo
    const lat = -25.9692 + (Math.random() - 0.5) * 0.05;
    const lng = 32.5732 + (Math.random() - 0.5) * 0.05;

    const item: Item = {
      id,
      title: newItem.title || 'Sem Título',
      description: newItem.description || '',
      category: newItem.category as Category,
      status: newItem.status as ItemStatus,
      location: newItem.location || 'N/A',
      province: newItem.province || 'Maputo Cidade',
      date: newItem.date || new Date().toISOString(),
      reward: newItem.reward,
      imageUrl: `https://picsum.photos/seed/${id}/400/300`,
      imageUrls: [`https://picsum.photos/seed/${id}/400/300`],
      userId: 'currentUser',
      createdAt: new Date().toISOString(),
      latitude: lat,
      longitude: lng
    };

    setItems(prev => [item, ...prev]);

    // Lógica de Match (apenas se online para simular IA)
    if (isOnline) {
      const matches = items.filter(existing => 
        existing.status !== item.status && 
        existing.category === item.category &&
        existing.province === item.province
      );

      if (matches.length > 0) {
        const matchNotif: Notification = {
          id: Math.random().toString(36).substr(2, 5),
          type: 'MATCH',
          title: 'Possível Correspondência!',
          description: `Detectamos que o seu item "${item.title}" pode ser o mesmo que "${matches[0].title}".`,
          itemId: matches[0].id,
          timestamp: new Date().toISOString(),
          isRead: false
        };
        setTimeout(() => {
          setNotifications(prev => [matchNotif, ...prev]);
        }, 3000);
      }
    }

    setIsSubmitting(false);
    setActiveTab('feed');
    setNewItem({
      status: ItemStatus.LOST,
      category: Category.DOCUMENTS,
      province: 'Maputo Cidade',
      date: new Date().toISOString().split('T')[0]
    });
  };

  const handleSendMessage = (text: string) => {
    if (!activeChat) return;
    const msg: Message = {
      id: Math.random().toString(36).substr(2, 9),
      itemId: activeChat.id,
      senderId: 'currentUser',
      receiverId: activeChat.userId,
      text,
      timestamp: new Date().toISOString()
    };
    setMessages(prev => [...prev, msg]);

    if (isOnline) {
      setTimeout(() => {
        const reply: Message = {
          id: Math.random().toString(36).substr(2, 9),
          itemId: activeChat.id,
          senderId: activeChat.userId,
          receiverId: 'currentUser',
          text: `Olá! Sou o dono do item "${activeChat.title}". Como podemos marcar a entrega?`,
          timestamp: new Date().toISOString()
        };
        setMessages(prev => [...prev, reply]);

        setNotifications(prev => [{
          id: Math.random().toString(36).substr(2, 5),
          type: 'MESSAGE',
          title: 'Nova Mensagem',
          description: `Resposta sobre "${activeChat.title}".`,
          itemId: activeChat.id,
          timestamp: new Date().toISOString(),
          isRead: false
        }, ...prev]);
      }, 2000);
    }
  };

  const handleNotificationClick = (notif: Notification) => {
    const item = items.find(i => i.id === notif.itemId);
    if (item) {
      setSelectedItem(item);
      setNotifications(prev => prev.map(n => n.id === notif.id ? { ...n, isRead: true } : n));
      setShowNotifications(false);
    }
  };

  const renderFeed = () => (
    <div className="h-full flex flex-col">
      <div className="p-4 space-y-4 bg-white border-b shadow-sm z-10">
        <div className="flex items-center justify-between">
          <h2 className="text-xl font-black text-gray-900 border-l-4 border-[#d21034] pl-3 uppercase">
            Radar Moçambique
          </h2>
          <div className="flex bg-gray-100 p-1 rounded-xl">
            <button 
              onClick={() => setViewMode('list')}
              className={`p-2 px-4 rounded-lg text-[10px] font-black uppercase transition-all ${viewMode === 'list' ? 'bg-white shadow-sm text-[#009739]' : 'text-gray-400'}`}
            >
              <i className="fa-solid fa-list mr-2"></i> Lista
            </button>
            <button 
              onClick={() => setViewMode('map')}
              className={`p-2 px-4 rounded-lg text-[10px] font-black uppercase transition-all ${viewMode === 'map' ? 'bg-white shadow-sm text-[#009739]' : 'text-gray-400'}`}
            >
              <i className="fa-solid fa-map-location-dot mr-2"></i> Mapa
            </button>
          </div>
        </div>

        <div className="flex gap-2">
          <div className="relative flex-1">
            <i className="fa-solid fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"></i>
            <input 
              type="text" 
              placeholder="Ex: BI, Chaves, Cão..." 
              className="w-full bg-gray-50 border-2 border-transparent focus:border-[#009739] rounded-xl py-3 pl-10 pr-4 outline-none transition-all text-sm"
              value={filters.searchQuery}
              onChange={(e) => setFilters({ ...filters, searchQuery: e.target.value })}
            />
          </div>
          <button 
            onClick={() => setShowFilters(!showFilters)}
            className={`px-4 rounded-xl border-2 transition-all flex items-center gap-2 ${showFilters || activeFiltersCount > 0 ? 'bg-[#fce100] border-[#fce100] text-black' : 'bg-white border-gray-100 text-gray-400'}`}
          >
            <i className="fa-solid fa-sliders"></i>
            {activeFiltersCount > 0 && <span className="bg-black text-white text-[10px] rounded-full w-4 h-4 flex items-center justify-center font-bold">{activeFiltersCount}</span>}
          </button>
        </div>

        {showFilters && (
          <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100 grid grid-cols-2 gap-3 animate-in fade-in slide-in-from-top-2 duration-300">
            <div className="col-span-2">
              <label className="text-[10px] font-black text-gray-400 uppercase mb-1 block">Estado</label>
              <div className="flex gap-2">
                {['ALL', ItemStatus.LOST, ItemStatus.FOUND].map((s) => (
                  <button
                    key={s}
                    onClick={() => setFilters({...filters, status: s as any})}
                    className={`flex-1 py-2 rounded-lg text-xs font-bold border-2 transition-all ${filters.status === s ? 'bg-black border-black text-white' : 'bg-white border-gray-200 text-gray-400'}`}
                  >
                    {s === 'ALL' ? 'Todos' : s === ItemStatus.LOST ? 'Perdido' : 'Achado'}
                  </button>
                ))}
              </div>
            </div>
            <div>
              <label className="text-[10px] font-black text-gray-400 uppercase mb-1 block">Província</label>
              <select className="w-full bg-white border-2 border-gray-200 rounded-lg p-2 text-xs font-semibold outline-none" value={filters.province} onChange={e => setFilters({...filters, province: e.target.value})}>
                <option value="ALL">Todas</option>
                {MOZAMBIQUE_PROVINCES.map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>
            <div>
              <label className="text-[10px] font-black text-gray-400 uppercase mb-1 block">Data</label>
              <input type="date" className="w-full bg-white border-2 border-gray-200 rounded-lg p-2 text-xs font-semibold outline-none" value={filters.date} onChange={e => setFilters({...filters, date: e.target.value})} />
            </div>
            <div className="col-span-2">
              <label className="text-[10px] font-black text-gray-400 uppercase mb-1 block">Categoria</label>
              <select className="w-full bg-white border-2 border-gray-200 rounded-lg p-2 text-xs font-semibold outline-none" value={filters.category} onChange={e => setFilters({...filters, category: e.target.value as Category | 'ALL'})}>
                <option value="ALL">Todas as Categorias</option>
                {Object.values(Category).map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>
          </div>
        )}
      </div>

      <div className="flex-1 overflow-hidden">
        {viewMode === 'list' ? (
          <div className="p-4 grid grid-cols-2 gap-4 overflow-y-auto h-full pb-24 no-scrollbar">
            {filteredItems.map(item => (
              <ItemCard key={item.id} item={item} onViewDetails={setSelectedItem} />
            ))}
            {filteredItems.length === 0 && (
              <div className="col-span-2 text-center py-20 opacity-40">
                <i className="fa-solid fa-ghost text-4xl mb-4"></i>
                <p className="text-sm font-black uppercase">Nenhum item encontrado.</p>
              </div>
            )}
          </div>
        ) : (
          <div className="w-full h-full pb-20">
             <MapView items={filteredItems} onViewDetails={setSelectedItem} />
          </div>
        )}
      </div>
    </div>
  );

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={setActiveTab} 
      notificationCount={unreadNotificationsCount}
      onToggleNotifications={() => setShowNotifications(!showNotifications)}
      isOnline={isOnline}
    >
      {showNotifications && (
        <NotificationDrawer 
          notifications={notifications} 
          onClose={() => setShowNotifications(false)}
          onNotificationClick={handleNotificationClick}
          onClear={() => setNotifications([])}
        />
      )}

      {activeChat ? (
        <ChatView 
          item={activeChat} 
          messages={messages.filter(m => m.itemId === activeChat.id)}
          onSendMessage={handleSendMessage}
          onBack={() => setActiveChat(null)}
          notificationCount={unreadNotificationsCount}
        />
      ) : selectedItem ? (
        <ItemDetails 
          item={selectedItem} 
          allContextItems={items}
          onBack={() => setSelectedItem(null)} 
          onStartChat={(item) => setActiveChat(item)}
          onViewItem={(item) => setSelectedItem(item)}
        />
      ) : (
        <>
          {activeTab === 'feed' && renderFeed()}
          {activeTab === 'post' && (
            <div className="p-6 pb-24 overflow-y-auto h-full no-scrollbar">
              <h2 className="text-2xl font-black mb-6 text-gray-900 border-l-8 border-[#fce100] pl-4 uppercase">Novo Registo</h2>
              <form onSubmit={handlePostSubmit} className="space-y-5">
                <div>
                  <label className="block text-xs font-black text-gray-500 uppercase mb-2">Estado</label>
                  <div className="grid grid-cols-2 gap-3">
                    <button type="button" onClick={() => setNewItem({...newItem, status: ItemStatus.LOST})} className={`p-4 rounded-2xl border-2 font-black transition-all ${newItem.status === ItemStatus.LOST ? 'border-[#d21034] bg-[#d21034] text-white shadow-lg' : 'border-gray-100 bg-gray-50 text-gray-400'}`}>PERDI</button>
                    <button type="button" onClick={() => setNewItem({...newItem, status: ItemStatus.FOUND})} className={`p-4 rounded-2xl border-2 font-black transition-all ${newItem.status === ItemStatus.FOUND ? 'border-[#009739] bg-[#009739] text-white shadow-lg' : 'border-gray-100 bg-gray-50 text-gray-400'}`}>ACHEI</button>
                  </div>
                </div>
                <div className="bg-gray-50 p-6 rounded-3xl space-y-4 border border-gray-100">
                  <input required className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 outline-none font-semibold shadow-sm" placeholder="Título do Item..." value={newItem.title || ''} onChange={e => setNewItem({...newItem, title: e.target.value})} />
                  <select className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 text-sm font-bold shadow-sm" value={newItem.category} onChange={e => setNewItem({...newItem, category: e.target.value as Category})}>
                    {Object.values(Category).map(cat => <option key={cat} value={cat}>{cat}</option>)}
                  </select>
                  <select className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 text-sm font-bold shadow-sm" value={newItem.province} onChange={e => setNewItem({...newItem, province: e.target.value})}>
                    {MOZAMBIQUE_PROVINCES.map(p => <option key={p} value={p}>{p}</option>)}
                  </select>
                  <input className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 outline-none font-semibold shadow-sm" placeholder="Localização (Rua, Bairro...)" value={newItem.location || ''} onChange={e => setNewItem({...newItem, location: e.target.value})} />
                  <textarea className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 h-24 resize-none font-medium shadow-sm" placeholder="Descrição Detalhada..." value={newItem.description || ''} onChange={e => setNewItem({...newItem, description: e.target.value})}></textarea>
                </div>
                <button disabled={isSubmitting} className="w-full bg-black text-[#fce100] py-5 rounded-2xl font-black shadow-xl uppercase tracking-widest disabled:opacity-50">
                  {isSubmitting ? 'Publicando...' : 'Publicar Agora'}
                </button>
              </form>
            </div>
          )}
          {activeTab === 'profile' && (
            <div className="p-6 text-center pb-24 h-full overflow-y-auto no-scrollbar">
              <div className="w-28 h-28 bg-gradient-to-tr from-[#009739] to-[#fce100] rounded-full mx-auto mb-6 p-1">
                <div className="bg-white rounded-full w-full h-full flex items-center justify-center text-[#d21034] text-4xl font-black overflow-hidden border-4 border-white">
                  <img src="https://api.dicebear.com/7.x/avataaars/svg?seed=Moz" alt="Profile" />
                </div>
              </div>
              <h2 className="text-2xl font-black text-gray-900 uppercase">Utilizador Moz</h2>
              <p className="text-gray-400 font-bold text-xs mb-8 uppercase tracking-widest">Maputo, Moçambique</p>

              <div className="grid grid-cols-2 gap-4 mb-8">
                <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100">
                  <div className="text-2xl font-black text-[#009739]">{items.filter(i => i.userId === 'currentUser').length}</div>
                  <div className="text-[8px] font-black text-gray-400 uppercase">Publicações</div>
                </div>
                <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100">
                  <div className="text-2xl font-black text-[#d21034]">2</div>
                  <div className="text-[8px] font-black text-gray-400 uppercase">Resgates</div>
                </div>
              </div>

              <div className="space-y-3">
                <button className="w-full bg-white border-2 border-gray-50 p-4 rounded-2xl flex items-center gap-4 hover:border-[#fce100] transition-colors group text-left">
                  <div className="bg-emerald-100 text-[#009739] p-3 rounded-xl group-hover:bg-[#009739] group-hover:text-white transition-colors"><i className="fa-solid fa-briefcase"></i></div>
                  <span className="font-black text-gray-700 uppercase text-xs">Meus Registos</span>
                </button>
                <button className="w-full bg-white border-2 border-gray-50 p-4 rounded-2xl flex items-center gap-4 hover:border-[#fce100] transition-colors group text-left">
                  <div className="bg-red-100 text-[#d21034] p-3 rounded-xl group-hover:bg-[#d21034] group-hover:text-white transition-colors"><i className="fa-solid fa-shield-halved"></i></div>
                  <span className="font-black text-gray-700 uppercase text-xs">Privacidade e Segurança</span>
                </button>
                <button className="w-full bg-white border-2 border-gray-50 p-4 rounded-2xl flex items-center gap-4 hover:border-red-100 transition-colors group text-left">
                  <div className="bg-gray-100 text-gray-400 p-3 rounded-xl group-hover:bg-red-500 group-hover:text-white transition-colors"><i className="fa-solid fa-right-from-bracket"></i></div>
                  <span className="font-black text-gray-700 uppercase text-xs">Sair da Conta</span>
                </button>
              </div>
            </div>
          )}
        </>
      )}
    </Layout>
  );
};

export default App;

import React, { useState } from 'react';
import { Item, ItemStatus } from '../types';
import { analyzeItemMatch } from '../services/geminiService';

interface ItemDetailsProps {
  item: Item;
  allContextItems: Item[];
  onBack: () => void;
  onStartChat: (item: Item) => void;
  onViewItem: (item: Item) => void;
}

const ItemDetails: React.FC<ItemDetailsProps> = ({ item, allContextItems, onBack, onStartChat, onViewItem }) => {
  const [analyzing, setAnalyzing] = useState(false);
  const [matchResult, setMatchResult] = useState<{item: Item, result: any} | null>(null);
  const [currentImgIndex, setCurrentImgIndex] = useState(0);

  // Estados para o Modal de Denúncia
  const [isReportModalOpen, setIsReportModalOpen] = useState(false);
  const [reportReason, setReportReason] = useState('');
  const [reportDetails, setReportDetails] = useState('');
  const [isSubmittingReport, setIsSubmittingReport] = useState(false);

  const images = item.imageUrls && item.imageUrls.length > 0 
    ? item.imageUrls 
    : [item.imageUrl || 'https://picsum.photos/seed/placeholder/400/300'];

  const nextImage = () => {
    setCurrentImgIndex((prev) => (prev + 1) % images.length);
  };

  const prevImage = () => {
    setCurrentImgIndex((prev) => (prev - 1 + images.length) % images.length);
  };

  const handleCheckMatch = async () => {
    setAnalyzing(true);
    const candidates = allContextItems.filter(i => 
      i.id !== item.id && 
      i.status !== item.status && 
      i.category === item.category
    );

    if (candidates.length === 0) {
      alert("Nenhum item similar encontrado no sistema ainda.");
      setAnalyzing(false);
      return;
    }

    const topCandidate = candidates[0];
    const res = await analyzeItemMatch(
      item.status === ItemStatus.LOST ? item : topCandidate,
      item.status === ItemStatus.FOUND ? item : topCandidate
    );

    setMatchResult({ item: topCandidate, result: res });
    setAnalyzing(false);
  };

  const handleSendReport = (e: React.FormEvent) => {
    e.preventDefault();
    if (!reportReason) {
      alert("Por favor, selecione um motivo.");
      return;
    }
    setIsSubmittingReport(true);

    // Simulação de envio de denúncia
    setTimeout(() => {
      alert("Denúncia enviada com sucesso! Nossa equipe irá analisar o conteúdo.");
      setIsSubmittingReport(false);
      setIsReportModalOpen(false);
      setReportReason('');
      setReportDetails('');
    }, 1500);
  };

  const suggestions = allContextItems
    .filter(i => i.id !== item.id && i.category === item.category)
    .slice(0, 3);

  return (
    <div className="p-4 bg-white min-h-full pb-10 relative">
      <button 
        onClick={onBack} 
        className="flex items-center text-[#009739] mb-4 gap-2 font-black uppercase text-xs hover:translate-x-[-4px] transition-transform"
      >
        <i className="fa-solid fa-arrow-left"></i> Voltar à Explorar
      </button>

      {/* Image Carousel */}
      <div className="relative group mb-6 overflow-hidden rounded-3xl shadow-2xl bg-gray-100 aspect-video">
        <div 
          className="flex transition-transform duration-500 ease-out h-full"
          style={{ transform: `translateX(-${currentImgIndex * 100}%)` }}
        >
          {images.map((img, idx) => (
            <img 
              key={idx}
              src={img} 
              alt={`${item.title} - ${idx + 1}`} 
              className="w-full h-full object-cover flex-shrink-0"
            />
          ))}
        </div>

        {images.length > 1 && (
          <>
            <button 
              onClick={prevImage}
              className="absolute left-4 top-1/2 -translate-y-1/2 bg-white/80 hover:bg-white text-black p-3 rounded-full shadow-lg opacity-0 group-hover:opacity-100 transition-opacity z-10"
            >
              <i className="fa-solid fa-chevron-left"></i>
            </button>
            <button 
              onClick={nextImage}
              className="absolute right-4 top-1/2 -translate-y-1/2 bg-white/80 hover:bg-white text-black p-3 rounded-full shadow-lg opacity-0 group-hover:opacity-100 transition-opacity z-10"
            >
              <i className="fa-solid fa-chevron-right"></i>
            </button>

            <div className="absolute bottom-4 left-1/2 -translate-x-1/2 flex gap-2 z-10">
              {images.map((_, idx) => (
                <button
                  key={idx}
                  onClick={() => setCurrentImgIndex(idx)}
                  className={`h-2 rounded-full transition-all ${
                    idx === currentImgIndex 
                      ? 'w-6 bg-[#fce100]' 
                      : 'w-2 bg-white/50'
                  }`}
                />
              ))}
            </div>
          </>
        )}

        <div className={`absolute top-4 right-4 px-4 py-1.5 rounded-full text-[10px] font-black uppercase shadow-lg z-10 ${
          item.status === ItemStatus.LOST ? 'bg-[#d21034] text-white' : 'bg-[#009739] text-white'
        }`}>
          {item.status === ItemStatus.LOST ? 'Perdido' : 'Achado'}
        </div>
      </div>

      <div className="space-y-6">
        <div className="flex justify-between items-start">
          <div className="flex-1">
            <div className="text-[10px] text-[#009739] font-black uppercase tracking-[0.2em] mb-1">{item.category}</div>
            <h2 className="text-3xl font-black text-gray-900 leading-tight uppercase tracking-tight">{item.title}</h2>
          </div>
          <button 
            onClick={() => setIsReportModalOpen(true)}
            className="text-gray-300 hover:text-[#d21034] transition-colors p-2"
            title="Denunciar este item"
          >
            <i className="fa-solid fa-flag text-xl"></i>
          </button>
        </div>

        <div className="flex flex-wrap gap-4 text-sm font-bold">
          <div className="flex items-center gap-2 bg-gray-50 px-4 py-2 rounded-2xl border border-gray-100">
            <i className="fa-solid fa-location-dot text-[#d21034]"></i>
            <span>{item.location}, {item.province}</span>
          </div>
          <div className="flex items-center gap-2 bg-gray-50 px-4 py-2 rounded-2xl border border-gray-100">
            <i className="fa-solid fa-calendar text-[#009739]"></i>
            <span>{new Date(item.date).toLocaleDateString('pt-MZ', { day: '2-digit', month: 'long', year: 'numeric' })}</span>
          </div>
        </div>

        <div className="bg-gray-50 p-6 rounded-3xl border border-gray-100">
          <h3 className="text-[10px] font-black text-gray-400 uppercase mb-3 tracking-widest">Descrição</h3>
          <p className="text-gray-700 leading-relaxed font-medium">{item.description}</p>
        </div>

        {item.reward && (
          <div className="bg-[#fce100]/20 p-6 rounded-3xl border-2 border-[#fce100] flex items-center justify-between">
            <div>
              <h3 className="text-[10px] font-black text-[#8a7b00] uppercase mb-1 tracking-widest">Recompensa Oferecida</h3>
              <p className="text-2xl font-black text-black">{item.reward.toLocaleString()} MT</p>
            </div>
            <div className="bg-[#fce100] p-4 rounded-2xl shadow-lg">
              <i className="fa-solid fa-coins text-2xl text-black"></i>
            </div>
          </div>
        )}

        <div className="grid grid-cols-2 gap-4 pt-4">
          <button 
            onClick={() => onStartChat(item)}
            className="bg-black text-[#fce100] py-5 rounded-2xl font-black uppercase tracking-widest shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3"
          >
            <i className="fa-solid fa-message"></i> Entrar em Contacto
          </button>

          <button 
            onClick={handleCheckMatch}
            disabled={analyzing}
            className={`py-5 rounded-2xl font-black uppercase tracking-widest border-2 transition-all flex items-center justify-center gap-3 active:scale-95 shadow-lg ${
              analyzing ? 'bg-gray-100 border-gray-200 text-gray-400' : 'bg-white border-black text-black hover:bg-gray-50'
            }`}
          >
            {analyzing ? (
              <i className="fa-solid fa-spinner animate-spin"></i>
            ) : (
              <i className="fa-solid fa-wand-magic-sparkles"></i>
            )}
            {analyzing ? 'Analisando...' : 'Verificar Match IA'}
          </button>
        </div>

        {matchResult && (
          <div className="bg-gradient-to-br from-indigo-600 to-purple-700 p-6 rounded-3xl text-white shadow-2xl animate-in zoom-in-95 duration-500">
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center gap-3">
                <div className="bg-white/20 p-2 rounded-xl">
                  <i className="fa-solid fa-robot"></i>
                </div>
                <h3 className="font-black text-xs uppercase tracking-widest">Resultado da IA</h3>
              </div>
              <div className="bg-white/20 px-3 py-1 rounded-full font-black text-[10px] uppercase">
                {matchResult.result.similarity}% de Match
              </div>
            </div>
            <p className="text-sm font-bold mb-6 bg-white/10 p-4 rounded-2xl border border-white/10 italic">"{matchResult.result.reasoning}"</p>
            <div className="bg-white rounded-2xl p-4 flex items-center gap-4 text-black cursor-pointer hover:bg-gray-50 transition-colors" onClick={() => onViewItem(matchResult.item)}>
              <img src={matchResult.item.imageUrl} className="w-12 h-12 rounded-xl object-cover shadow-sm" alt="" />
              <div className="flex-1 min-w-0">
                <div className="text-[8px] font-black text-indigo-600 uppercase mb-0.5">{matchResult.item.category}</div>
                <div className="font-black text-xs truncate uppercase">{matchResult.item.title}</div>
              </div>
              <i className="fa-solid fa-chevron-right text-gray-300"></i>
            </div>
          </div>
        )}

        {suggestions.length > 0 && (
          <div className="space-y-4 pt-6">
            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">Itens Sugeridos</h3>
            <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar">
              {suggestions.map(s => (
                <div 
                  key={s.id} 
                  onClick={() => onViewItem(s)}
                  className="min-w-[140px] bg-white rounded-2xl border border-gray-100 overflow-hidden shadow-sm active:scale-95 transition-transform"
                >
                  <img src={s.imageUrl} className="w-full h-24 object-cover" alt="" />
                  <div className="p-3">
                    <h4 className="font-black text-[10px] line-clamp-1 uppercase leading-tight">{s.title}</h4>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Modal de Denúncia */}
      {isReportModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setIsReportModalOpen(false)}></div>
          <div className="relative bg-white w-full max-w-sm rounded-[2.5rem] p-8 shadow-2xl animate-in zoom-in-95 duration-300">
            <div className="text-center mb-6">
              <div className="w-16 h-16 bg-red-50 text-[#d21034] rounded-full flex items-center justify-center mx-auto mb-4 text-2xl border-4 border-white shadow-lg">
                <i className="fa-solid fa-triangle-exclamation"></i>
              </div>
              <h2 className="text-xl font-black text-gray-900 uppercase">Denunciar Item</h2>
              <p className="text-xs font-bold text-gray-400 mt-1">Ajude-nos a manter a comunidade segura.</p>
            </div>

            <form onSubmit={handleSendReport} className="space-y-4">
              <div>
                <label className="block text-[10px] font-black text-gray-400 uppercase mb-2 ml-1">Motivo da Denúncia</label>
                <div className="space-y-2">
                  {[
                    { id: 'wrong', label: 'Item Incorreto/Trocado' },
                    { id: 'fake', label: 'Informação Falsa' },
                    { id: 'spam', label: 'Spam ou Publicidade' },
                    { id: 'other', label: 'Outro Motivo' }
                  ].map((option) => (
                    <button
                      key={option.id}
                      type="button"
                      onClick={() => setReportReason(option.id)}
                      className={`w-full p-4 rounded-2xl text-left text-xs font-bold border-2 transition-all flex items-center justify-between ${
                        reportReason === option.id 
                          ? 'border-[#d21034] bg-red-50 text-[#d21034]' 
                          : 'border-gray-50 bg-gray-50 text-gray-500 hover:border-gray-100'
                      }`}
                    >
                      {option.label}
                      {reportReason === option.id && <i className="fa-solid fa-circle-check"></i>}
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="block text-[10px] font-black text-gray-400 uppercase mb-2 ml-1">Detalhes Adicionais (Opcional)</label>
                <textarea
                  className="w-full bg-gray-50 border-2 border-transparent focus:border-[#d21034] rounded-2xl p-4 text-xs font-bold outline-none transition-all h-24 resize-none shadow-inner"
                  placeholder="Explique o que há de errado..."
                  value={reportDetails}
                  onChange={(e) => setReportDetails(e.target.value)}
                ></textarea>
              </div>

              <div className="flex gap-3 pt-4">
                <button
                  type="button"
                  onClick={() => setIsReportModalOpen(false)}
                  className="flex-1 py-4 rounded-2xl font-black uppercase text-xs text-gray-400 hover:bg-gray-100 transition-colors"
                >
                  Cancelar
                </button>
                <button
                  type="submit"
                  disabled={isSubmittingReport || !reportReason}
                  className="flex-[2] bg-[#d21034] text-white py-4 rounded-2xl font-black uppercase text-xs shadow-lg shadow-red-200 active:scale-95 transition-all disabled:opacity-50 disabled:grayscale"
                >
                  {isSubmittingReport ? (
                    <i className="fa-solid fa-circle-notch animate-spin mr-2"></i>
                  ) : (
                    <i className="fa-solid fa-paper-plane mr-2"></i>
                  )}
                  {isSubmittingReport ? 'Enviando...' : 'Enviar Denúncia'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ItemDetails;

export enum ItemStatus {
  LOST = 'LOST',
  FOUND = 'FOUND',
  REUNITED = 'REUNITED',
  IN_TRANSIT = 'IN_TRANSIT'
}

export enum Category {
  DOCUMENTS = 'Documentos',
  ELECTRONICS = 'Eletrónicos',
  PETS = 'Animais',
  WALLETS = 'Carteiras/Bolsas',
  KEYS = 'Chaves',
  OTHERS = 'Outros'
}

export interface User {
  id: string;
  name: string;
  phone: string;
  email: string;
}

export interface Item {
  id: string;
  title: string;
  description: string;
  category: Category;
  status: ItemStatus;
  location: string;
  province: string;
  reward?: number;
  date: string;
  imageUrl?: string;
  imageUrls?: string[];
  userId: string;
  createdAt: string;
  latitude?: number;
  longitude?: number;
  // Propriedades para rastreamento
  transitLatitude?: number;
  transitLongitude?: number;
  isTrackingActive?: boolean;
}

export interface Message {
  id: string;
  itemId: string;
  senderId: string;
  receiverId: string;
  text: string;
  timestamp: string;
}

export interface Notification {
  id: string;
  type: 'MATCH' | 'MESSAGE' | 'REWARD' | 'DELIVERY';
  title: string;
  description: string;
  itemId: string;
  timestamp: string;
  isRead: boolean;
}

export interface MatchResult {
  similarity: number;
  reasoning: string;
  isMatch: boolean;
}

import React, { useState, useMemo, useEffect, useRef } from 'react';
import Layout from './components/Layout';
import ItemCard from './components/ItemCard';
import ItemDetails from './components/ItemDetails';
import ChatView from './components/ChatView';
import MapView from './components/MapView';
import DeliveryTrackingView from './components/DeliveryTrackingView';
import NotificationDrawer from './components/NotificationDrawer';
import { Item, ItemStatus, Category, Message, Notification } from './types';
import { INITIAL_ITEMS, MOZAMBIQUE_PROVINCES } from './constants';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'feed' | 'post' | 'profile'>('feed');
  const [viewMode, setViewMode] = useState<'list' | 'map'>('list');
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [trackingItemId, setTrackingItemId] = useState<string | null>(null);
  const watchIdRef = useRef<number | null>(null);

  // Inicialização de estado
  const [items, setItems] = useState<Item[]>(() => {
    const saved = localStorage.getItem('achei_items');
    return saved ? JSON.parse(saved) : INITIAL_ITEMS;
  });

  const [messages, setMessages] = useState<Message[]>(() => {
    const saved = localStorage.getItem('achei_messages');
    return saved ? JSON.parse(saved) : [];
  });

  const [notifications, setNotifications] = useState<Notification[]>(() => {
    const saved = localStorage.getItem('achei_notifications');
    return saved ? JSON.parse(saved) : [];
  });

  const [selectedItem, setSelectedItem] = useState<Item | null>(null);
  const [activeChat, setActiveChat] = useState<Item | null>(null);
  const [showFilters, setShowFilters] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [isViewingDelivery, setIsViewingDelivery] = useState(false);

  const [filters, setFilters] = useState({
    status: 'ALL' as ItemStatus | 'ALL',
    category: 'ALL' as Category | 'ALL',
    province: 'ALL' as string | 'ALL',
    date: '' as string,
    searchQuery: ''
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [newItem, setNewItem] = useState<Partial<Item>>({
    status: ItemStatus.LOST,
    category: Category.DOCUMENTS,
    province: 'Maputo Cidade',
    date: new Date().toISOString().split('T')[0]
  });

  // Monitorar status de rede
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Persistência
  useEffect(() => {
    localStorage.setItem('achei_items', JSON.stringify(items));
  }, [items]);
  useEffect(() => {
    localStorage.setItem('achei_messages', JSON.stringify(messages));
  }, [messages]);
  useEffect(() => {
    localStorage.setItem('achei_notifications', JSON.stringify(notifications));
  }, [notifications]);

  // Lógica de Rastreamento em Tempo Real
  const startTracking = (itemId: string) => {
    if (!("geolocation" in navigator)) {
      alert("Geolocalização não disponível.");
      return;
    }

    setTrackingItemId(itemId);
    setItems(prev => prev.map(i => i.id === itemId ? { ...i, isTrackingActive: true, status: ItemStatus.IN_TRANSIT } : i));

    watchIdRef.current = navigator.geolocation.watchPosition(
      (position) => {
        const { latitude, longitude } = position.coords;
        setItems(prev => prev.map(i => i.id === itemId ? { 
          ...i, 
          transitLatitude: latitude, 
          transitLongitude: longitude 
        } : i));
      },
      (error) => {
        console.error("Erro no rastreamento:", error);
        stopTracking(itemId);
      },
      { enableHighAccuracy: true, maximumAge: 0 }
    );

    // Notificar outro usuário (simulado)
    const deliveryNotif: Notification = {
      id: Math.random().toString(36).substr(2, 5),
      type: 'DELIVERY',
      title: 'Entrega Iniciada!',
      description: 'O transportador iniciou o percurso. Acompanhe no mapa em tempo real.',
      itemId: itemId,
      timestamp: new Date().toISOString(),
      isRead: false
    };
    setNotifications(prev => [deliveryNotif, ...prev]);
  };

  const stopTracking = (itemId: string) => {
    if (watchIdRef.current !== null) {
      navigator.geolocation.clearWatch(watchIdRef.current);
      watchIdRef.current = null;
    }
    setTrackingItemId(null);
    setItems(prev => prev.map(i => i.id === itemId ? { ...i, isTrackingActive: false } : i));
    alert("Rastreamento encerrado.");
  };

  const activeFiltersCount = useMemo(() => {
    let count = 0;
    if (filters.status !== 'ALL') count++;
    if (filters.category !== 'ALL') count++;
    if (filters.province !== 'ALL') count++;
    if (filters.date !== '') count++;
    return count;
  }, [filters]);

  const unreadNotificationsCount = useMemo(() => {
    return notifications.filter(n => !n.isRead).length;
  }, [notifications]);

  const filteredItems = useMemo(() => {
    return items.filter(item => {
      const statusMatch = filters.status === 'ALL' || item.status === filters.status;
      const categoryMatch = filters.category === 'ALL' || item.category === filters.category;
      const provinceMatch = filters.province === 'ALL' || item.province === filters.province;
      const dateMatch = !filters.date || item.date === filters.date;
      const searchMatch = !filters.searchQuery || 
                          item.title.toLowerCase().includes(filters.searchQuery.toLowerCase()) || 
                          item.description.toLowerCase().includes(filters.searchQuery.toLowerCase());

      return statusMatch && categoryMatch && provinceMatch && dateMatch && searchMatch;
    }).sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  }, [items, filters]);

  const handlePostSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    const id = Math.random().toString(36).substr(2, 9);
    const lat = -25.9692 + (Math.random() - 0.5) * 0.05;
    const lng = 32.5732 + (Math.random() - 0.5) * 0.05;

    const item: Item = {
      id,
      title: newItem.title || 'Sem Título',
      description: newItem.description || '',
      category: newItem.category as Category,
      status: newItem.status as ItemStatus,
      location: newItem.location || 'N/A',
      province: newItem.province || 'Maputo Cidade',
      date: newItem.date || new Date().toISOString(),
      reward: newItem.reward,
      imageUrl: `https://picsum.photos/seed/${id}/400/300`,
      imageUrls: [`https://picsum.photos/seed/${id}/400/300`],
      userId: 'currentUser',
      createdAt: new Date().toISOString(),
      latitude: lat,
      longitude: lng
    };
    setItems(prev => [item, ...prev]);
    setIsSubmitting(false);
    setActiveTab('feed');
  };

  const handleSendMessage = (text: string) => {
    if (!activeChat) return;
    const msg: Message = {
      id: Math.random().toString(36).substr(2, 9),
      itemId: activeChat.id,
      senderId: 'currentUser',
      receiverId: activeChat.userId,
      text,
      timestamp: new Date().toISOString()
    };
    setMessages(prev => [...prev, msg]);
  };

  const handleNotificationClick = (notif: Notification) => {
    const item = items.find(i => i.id === notif.itemId);
    if (item) {
      if (notif.type === 'DELIVERY') {
        setSelectedItem(item);
        setIsViewingDelivery(true);
      } else {
        setSelectedItem(item);
      }
      setNotifications(prev => prev.map(n => n.id === notif.id ? { ...n, isRead: true } : n));
      setShowNotifications(false);
    }
  };

  const renderFeed = () => (
    <div className="h-full flex flex-col">
      <div className="p-4 space-y-4 bg-white border-b shadow-sm z-10">
        <div className="flex items-center justify-between">
          <h2 className="text-xl font-black text-gray-900 border-l-4 border-[#d21034] pl-3 uppercase">
            Radar Moçambique
          </h2>
          <div className="flex bg-gray-100 p-1 rounded-xl">
            <button onClick={() => setViewMode('list')} className={`p-2 px-4 rounded-lg text-[10px] font-black uppercase transition-all ${viewMode === 'list' ? 'bg-white shadow-sm text-[#009739]' : 'text-gray-400'}`}>
              <i className="fa-solid fa-list mr-2"></i> Lista
            </button>
            <button onClick={() => setViewMode('map')} className={`p-2 px-4 rounded-lg text-[10px] font-black uppercase transition-all ${viewMode === 'map' ? 'bg-white shadow-sm text-[#009739]' : 'text-gray-400'}`}>
              <i className="fa-solid fa-map-location-dot mr-2"></i> Mapa
            </button>
          </div>
        </div>

        <div className="flex gap-2">
          <div className="relative flex-1">
            <i className="fa-solid fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"></i>
            <input 
              type="text" 
              placeholder="Ex: BI, Chaves, Cão..." 
              className="w-full bg-gray-50 border-2 border-transparent focus:border-[#009739] rounded-xl py-3 pl-10 pr-4 outline-none transition-all text-sm"
              value={filters.searchQuery}
              onChange={(e) => setFilters({ ...filters, searchQuery: e.target.value })}
            />
          </div>
          <button onClick={() => setShowFilters(!showFilters)} className={`px-4 rounded-xl border-2 transition-all flex items-center gap-2 ${showFilters || activeFiltersCount > 0 ? 'bg-[#fce100] border-[#fce100] text-black' : 'bg-white border-gray-100 text-gray-400'}`}>
            <i className="fa-solid fa-sliders"></i>
            {activeFiltersCount > 0 && <span className="bg-black text-white text-[10px] rounded-full w-4 h-4 flex items-center justify-center font-bold">{activeFiltersCount}</span>}
          </button>
        </div>

        {showFilters && (
          <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100 grid grid-cols-2 gap-3 animate-in fade-in slide-in-from-top-2 duration-300">
            <div className="col-span-2">
              <label className="text-[10px] font-black text-gray-400 uppercase mb-1 block">Estado</label>
              <div className="flex gap-2">
                {['ALL', ItemStatus.LOST, ItemStatus.FOUND].map((s) => (
                  <button key={s} onClick={() => setFilters({...filters, status: s as any})} className={`flex-1 py-2 rounded-lg text-xs font-bold border-2 transition-all ${filters.status === s ? 'bg-black border-black text-white' : 'bg-white border-gray-200 text-gray-400'}`}>
                    {s === 'ALL' ? 'Todos' : s === ItemStatus.LOST ? 'Perdido' : 'Achado'}
                  </button>
                ))}
              </div>
            </div>
            <div>
              <label className="text-[10px] font-black text-gray-400 uppercase mb-1 block">Província</label>
              <select className="w-full bg-white border-2 border-gray-200 rounded-lg p-2 text-xs font-semibold outline-none" value={filters.province} onChange={e => setFilters({...filters, province: e.target.value})}>
                <option value="ALL">Todas</option>
                {MOZAMBIQUE_PROVINCES.map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>
            <div>
              <label className="text-[10px] font-black text-gray-400 uppercase mb-1 block">Data</label>
              <input type="date" className="w-full bg-white border-2 border-gray-200 rounded-lg p-2 text-xs font-semibold outline-none" value={filters.date} onChange={e => setFilters({...filters, date: e.target.value})} />
            </div>
          </div>
        )}
      </div>

      <div className="flex-1 overflow-hidden">
        {viewMode === 'list' ? (
          <div className="p-4 grid grid-cols-2 gap-4 overflow-y-auto h-full pb-24 no-scrollbar">
            {filteredItems.map(item => (
              <ItemCard key={item.id} item={item} onViewDetails={setSelectedItem} />
            ))}
          </div>
        ) : (
          <div className="w-full h-full pb-20">
             <MapView items={filteredItems} onViewDetails={setSelectedItem} />
          </div>
        )}
      </div>
    </div>
  );

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={setActiveTab} 
      notificationCount={unreadNotificationsCount}
      onToggleNotifications={() => setShowNotifications(!showNotifications)}
      isOnline={isOnline}
    >
      {showNotifications && (
        <NotificationDrawer 
          notifications={notifications} 
          onClose={() => setShowNotifications(false)}
          onNotificationClick={handleNotificationClick}
          onClear={() => setNotifications([])}
        />
      )}

      {isViewingDelivery && selectedItem ? (
        <DeliveryTrackingView 
          item={items.find(i => i.id === selectedItem.id) || selectedItem} 
          onBack={() => setIsViewingDelivery(false)} 
        />
      ) : activeChat ? (
        <ChatView 
          item={activeChat} 
          messages={messages.filter(m => m.itemId === activeChat.id)}
          onSendMessage={handleSendMessage}
          onBack={() => setActiveChat(null)}
          notificationCount={unreadNotificationsCount}
          isTracking={activeChat.isTrackingActive}
          onStartTracking={() => startTracking(activeChat.id)}
          onStopTracking={() => stopTracking(activeChat.id)}
          onViewTracking={() => setIsViewingDelivery(true)}
        />
      ) : selectedItem ? (
        <ItemDetails 
          item={selectedItem} 
          allContextItems={items}
          onBack={() => setSelectedItem(null)} 
          onStartChat={(item) => setActiveChat(item)}
          onViewItem={(item) => setSelectedItem(item)}
        />
      ) : (
        <>
          {activeTab === 'feed' && renderFeed()}
          {activeTab === 'post' && (
             <div className="p-6 pb-24 overflow-y-auto h-full no-scrollbar">
                <h2 className="text-2xl font-black mb-6 text-gray-900 border-l-8 border-[#fce100] pl-4 uppercase">Novo Registo</h2>
                <form onSubmit={handlePostSubmit} className="space-y-5">
                  <div>
                    <label className="block text-xs font-black text-gray-500 uppercase mb-2">Estado</label>
                    <div className="grid grid-cols-2 gap-3">
                      <button type="button" onClick={() => setNewItem({...newItem, status: ItemStatus.LOST})} className={`p-4 rounded-2xl border-2 font-black transition-all ${newItem.status === ItemStatus.LOST ? 'border-[#d21034] bg-[#d21034] text-white shadow-lg' : 'border-gray-100 bg-gray-50 text-gray-400'}`}>PERDI</button>
                      <button type="button" onClick={() => setNewItem({...newItem, status: ItemStatus.FOUND})} className={`p-4 rounded-2xl border-2 font-black transition-all ${newItem.status === ItemStatus.FOUND ? 'border-[#009739] bg-[#009739] text-white shadow-lg' : 'border-gray-100 bg-gray-50 text-gray-400'}`}>ACHEI</button>
                    </div>
                  </div>
                  <div className="bg-gray-50 p-6 rounded-3xl space-y-4 border border-gray-100">
                    <input required className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 outline-none font-semibold shadow-sm" placeholder="Título do Item..." value={newItem.title || ''} onChange={e => setNewItem({...newItem, title: e.target.value})} />
                    <select className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 text-sm font-bold shadow-sm" value={newItem.category} onChange={e => setNewItem({...newItem, category: e.target.value as Category})}>
                      {Object.values(Category).map(cat => <option key={cat} value={cat}>{cat}</option>)}
                    </select>
                    <select className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 text-sm font-bold shadow-sm" value={newItem.province} onChange={e => setNewItem({...newItem, province: e.target.value})}>
                      {MOZAMBIQUE_PROVINCES.map(p => <option key={p} value={p}>{p}</option>)}
                    </select>
                  </div>
                  <button disabled={isSubmitting} className="w-full bg-black text-[#fce100] py-5 rounded-2xl font-black shadow-xl uppercase tracking-widest disabled:opacity-50">
                    {isSubmitting ? 'Publicando...' : 'Publicar Agora'}
                  </button>
                </form>
              </div>
          )}
          {activeTab === 'profile' && (
             <div className="p-6 text-center pb-24 h-full overflow-y-auto no-scrollbar">
                <div className="w-28 h-28 bg-gradient-to-tr from-[#009739] to-[#fce100] rounded-full mx-auto mb-6 p-1">
                  <div className="bg-white rounded-full w-full h-full flex items-center justify-center text-[#d21034] text-4xl font-black overflow-hidden border-4 border-white">
                    <img src="https://api.dicebear.com/7.x/avataaars/svg?seed=Moz" alt="Profile" />
                  </div>
                </div>
                <h2 className="text-2xl font-black text-gray-900 uppercase">Utilizador Moz</h2>
                <p className="text-gray-400 font-bold text-xs mb-8 uppercase tracking-widest">Maputo, Moçambique</p>

                <div className="grid grid-cols-2 gap-4 mb-8">
                  <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100">
                    <div className="text-2xl font-black text-[#009739]">{items.filter(i => i.userId === 'currentUser').length}</div>
                    <div className="text-[8px] font-black text-gray-400 uppercase">Publicações</div>
                  </div>
                  <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100">
                    <div className="text-2xl font-black text-[#d21034]">2</div>
                    <div className="text-[8px] font-black text-gray-400 uppercase">Resgates</div>
                  </div>
                </div>
              </div>
          )}
        </>
      )}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Item, Message } from '../types';

interface ChatViewProps {
  item: Item;
  messages: Message[];
  onSendMessage: (text: string) => void;
  onBack: () => void;
  notificationCount: number;
  isTracking?: boolean;
  onStartTracking?: () => void;
  onStopTracking?: () => void;
  onViewTracking?: () => void;
}

const ChatView: React.FC<ChatViewProps> = ({ 
  item, 
  messages, 
  onSendMessage, 
  onBack, 
  notificationCount,
  isTracking,
  onStartTracking,
  onStopTracking,
  onViewTracking
}) => {
  const [inputText, setInputText] = useState('');
  const scrollRef = useRef<HTMLDivElement>(null);
  const [isTyping, setIsTyping] = useState(false);

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
    if (messages.length > 0) {
      setIsTyping(true);
      const timer = setTimeout(() => setIsTyping(false), 2000);
      return () => clearTimeout(timer);
    }
  }, [messages]);

  const handleSend = (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputText.trim()) return;
    onSendMessage(inputText);
    setInputText('');
  };

  return (
    <div className="flex flex-col h-full bg-[#f9f9f9]">
      {/* Chat Header */}
      <div className="bg-white p-4 border-b flex items-center gap-3 sticky top-0 z-20 shadow-sm">
        <button onClick={onBack} className="text-[#009739] p-2 relative active:scale-90 transition-transform">
          <i className="fa-solid fa-arrow-left"></i>
          {notificationCount > 0 && (
            <span className="absolute top-0 right-0 bg-[#d21034] text-white text-[7px] font-black w-3.5 h-3.5 flex items-center justify-center rounded-full border border-white shadow-sm animate-bounce">
              {notificationCount}
            </span>
          )}
        </button>

        <div className="w-10 h-10 rounded-full overflow-hidden border-2 border-gray-100 shadow-sm">
          <img src={item.imageUrl} className="w-full h-full object-cover" alt="" />
        </div>

        <div className="flex-1 overflow-hidden">
          <div className="font-black text-xs uppercase truncate text-gray-900">{item.title}</div>
          <div className="flex items-center gap-1.5">
            <div className={`w-1.5 h-1.5 rounded-full ${isTracking ? 'bg-[#009739] animate-pulse' : 'bg-gray-300'}`}></div>
            <div className="text-[9px] text-gray-400 font-black uppercase tracking-wider">
              {isTracking ? 'Rastreamento Ativo' : 'Chat de Resgate'}
            </div>
          </div>
        </div>
      </div>

      {/* Rastreamento Bar (Se ativo) */}
      {isTracking && (
        <div className="bg-[#009739] text-white px-4 py-2 flex justify-between items-center animate-in slide-in-from-top duration-300">
          <div className="flex items-center gap-2">
            <div className="w-2 h-2 bg-white rounded-full animate-ping"></div>
            <span className="text-[10px] font-black uppercase tracking-widest">Entrega em curso...</span>
          </div>
          <div className="flex gap-2">
             <button onClick={onViewTracking} className="bg-white/20 hover:bg-white/30 px-3 py-1 rounded-lg text-[9px] font-black uppercase">
               Ver Mapa
             </button>
             <button onClick={onStopTracking} className="bg-red-500/80 hover:bg-red-500 px-3 py-1 rounded-lg text-[9px] font-black uppercase">
               Parar
             </button>
          </div>
        </div>
      )}

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4 no-scrollbar">
        {messages.length === 0 && (
          <div className="text-center py-16 px-10">
            <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mx-auto mb-4 shadow-sm text-[#009739]">
               <i className="fa-solid fa-shield-halved text-2xl"></i>
            </div>
            <h3 className="text-[10px] font-black uppercase text-gray-400 mb-1">Conversa Segura</h3>
            <p className="text-[11px] text-gray-500 font-bold leading-relaxed">
              Combine a entrega aqui. Lembre-se: locais públicos são mais seguros.
            </p>
          </div>
        )}

        {messages.map((msg, index) => {
          const isMe = msg.senderId === 'currentUser';
          return (
            <div key={msg.id} className={`flex flex-col ${isMe ? 'items-end' : 'items-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}>
              <div className={`max-w-[85%] p-3.5 rounded-2xl shadow-sm text-[13px] font-bold leading-snug ${
                isMe 
                  ? 'bg-black text-[#fce100] rounded-tr-none' 
                  : 'bg-white text-gray-800 rounded-tl-none border border-gray-100'
              }`}>
                {msg.text}
              </div>
            </div>
          );
        })}
        <div ref={scrollRef} />
      </div>

      {/* Input & Quick Actions */}
      <div className="p-4 bg-white border-t border-gray-100 shadow-[0_-4px_10px_rgba(0,0,0,0.02)]">
        {!isTracking && (
          <div className="flex gap-2 mb-3">
             <button 
               onClick={onStartTracking}
               className="flex-1 bg-gray-50 border-2 border-gray-100 hover:border-[#009739] text-gray-500 hover:text-[#009739] py-2 rounded-xl text-[10px] font-black uppercase transition-all flex items-center justify-center gap-2"
             >
               <i className="fa-solid fa-truck-fast"></i> Iniciar Entrega (Live)
             </button>
             <button className="flex-1 bg-gray-50 border-2 border-gray-100 text-gray-500 py-2 rounded-xl text-[10px] font-black uppercase flex items-center justify-center gap-2">
               <i className="fa-solid fa-handshake"></i> Concluído
             </button>
          </div>
        )}

        <form onSubmit={handleSend} className="flex gap-2 items-center">
          <input 
            type="text"
            placeholder="Escreva sua mensagem..."
            className="w-full bg-gray-50 border-2 border-transparent focus:border-[#009739] rounded-2xl px-5 py-3.5 text-sm font-bold outline-none transition-all"
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
          />
          <button 
            type="submit"
            disabled={!inputText.trim()}
            className="bg-[#009739] text-white w-12 h-12 rounded-2xl flex items-center justify-center shadow-lg active:scale-95 transition-all disabled:opacity-30"
          >
            <i className="fa-solid fa-paper-plane"></i>
          </button>
        </form>
      </div>
    </div>
  );
};

export default ChatView;

import React, { useEffect, useRef } from 'react';
import L from 'leaflet';
import { Item } from '../types';

interface DeliveryTrackingViewProps {
  item: Item;
  onBack: () => void;
}

const DeliveryTrackingView: React.FC<DeliveryTrackingViewProps> = ({ item, onBack }) => {
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<L.Map | null>(null);
  const transitMarkerRef = useRef<L.Marker | null>(null);
  const destinationMarkerRef = useRef<L.Marker | null>(null);

  useEffect(() => {
    if (!mapContainerRef.current || mapRef.current) return;

    const map = L.map(mapContainerRef.current).setView([item.latitude || -25.9692, item.longitude || 32.5732], 15);
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png').addTo(map);
    mapRef.current = map;

    // Marcador de destino
    if (item.latitude && item.longitude) {
      const destIcon = L.divIcon({
        className: 'dest-icon',
        html: `<div class="bg-black text-[#fce100] w-8 h-8 rounded-full flex items-center justify-center border-4 border-white shadow-xl"><i class="fa-solid fa-flag-checkered"></i></div>`,
        iconSize: [32, 32],
        iconAnchor: [16, 16]
      });
      destinationMarkerRef.current = L.marker([item.latitude, item.longitude], { icon: destIcon }).addTo(map).bindPopup("Local do Resgate");
    }

    return () => {
      if (mapRef.current) {
        mapRef.current.remove();
        mapRef.current = null;
      }
    };
  }, [item]);

  useEffect(() => {
    if (!mapRef.current) return;

    const lat = item.transitLatitude || item.latitude || -25.9692;
    const lng = item.transitLongitude || item.longitude || 32.5732;

    const transitIcon = L.divIcon({
      className: 'transit-icon',
      html: `
        <div class="relative">
          <div class="absolute inset-0 bg-[#009739] rounded-full animate-ping opacity-30"></div>
          <div class="relative bg-[#009739] text-white w-10 h-10 rounded-full flex items-center justify-center border-4 border-white shadow-2xl scale-110">
            <i class="fa-solid fa-motorcycle"></i>
          </div>
        </div>
      `,
      iconSize: [40, 40],
      iconAnchor: [20, 20]
    });

    if (transitMarkerRef.current) {
      transitMarkerRef.current.setLatLng([lat, lng]);
    } else {
      transitMarkerRef.current = L.marker([lat, lng], { icon: transitIcon }).addTo(mapRef.current);
    }

    mapRef.current.panTo([lat, lng]);

  }, [item.transitLatitude, item.transitLongitude]);

  return (
    <div className="h-full flex flex-col bg-white">
      <div className="p-4 border-b flex items-center justify-between z-10 bg-white">
        <div className="flex items-center gap-3">
          <button onClick={onBack} className="text-gray-400 p-2"><i className="fa-solid fa-arrow-left"></i></button>
          <div>
            <h2 className="font-black text-xs uppercase tracking-widest text-gray-400">Entrega ao Vivo</h2>
            <div className="font-black text-sm uppercase truncate max-w-[200px]">{item.title}</div>
          </div>
        </div>
        <div className="bg-emerald-100 text-[#009739] px-3 py-1 rounded-full flex items-center gap-2">
           <div className="w-1.5 h-1.5 bg-[#009739] rounded-full animate-pulse"></div>
           <span className="text-[10px] font-black uppercase">Live</span>
        </div>
      </div>

      <div className="flex-1 relative">
        <div ref={mapContainerRef} className="w-full h-full" />

        {/* Info Card Overlay */}
        <div className="absolute bottom-6 left-6 right-6 bg-white rounded-[2rem] p-6 shadow-2xl border-2 border-gray-50 flex items-center gap-5 z-[500] animate-in slide-in-from-bottom duration-500">
           <div className="w-14 h-14 bg-gray-100 rounded-2xl overflow-hidden shadow-sm">
             <img src={item.imageUrl} className="w-full h-full object-cover" alt="" />
           </div>
           <div className="flex-1">
              <div className="text-[8px] font-black text-gray-400 uppercase mb-1">Status da Entrega</div>
              <div className="font-black text-sm uppercase text-[#009739]">Item em Movimento</div>
              <div className="text-[10px] font-bold text-gray-500">Aproximando-se do destino...</div>
           </div>
           <div className="text-center">
              <div className="text-xl font-black text-black leading-none">5</div>
              <div className="text-[8px] font-black text-gray-400 uppercase">min</div>
           </div>
        </div>
      </div>

      <div className="p-4 bg-gray-50 text-center">
        <p className="text-[9px] font-black text-gray-300 uppercase tracking-[0.3em]">Mantenha-se em segurança</p>
      </div>
    </div>
  );
};

export default DeliveryTrackingView;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import Layout from './components/Layout';
import ItemCard from './components/ItemCard';
import ItemDetails from './components/ItemDetails';
import ChatView from './components/ChatView';
import MapView from './components/MapView';
import DeliveryTrackingView from './components/DeliveryTrackingView';
import NotificationDrawer from './components/NotificationDrawer';
import { Item, ItemStatus, Category, Message, Notification } from './types';
import { INITIAL_ITEMS, MOZAMBIQUE_PROVINCES } from './constants';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'feed' | 'post' | 'profile'>('feed');
  const [viewMode, setViewMode] = useState<'list' | 'map'>('list');
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [trackingItemId, setTrackingItemId] = useState<string | null>(null);
  const watchIdRef = useRef<number | null>(null);

  // Estados de navegação e edição no Perfil
  const [profileView, setProfileView] = useState<'main' | 'my-posts'>('main');
  const [editingItem, setEditingItem] = useState<Item | null>(null);

  // Inicialização de estado
  const [items, setItems] = useState<Item[]>(() => {
    const saved = localStorage.getItem('achei_items');
    return saved ? JSON.parse(saved) : INITIAL_ITEMS;
  });

  const [messages, setMessages] = useState<Message[]>(() => {
    const saved = localStorage.getItem('achei_messages');
    return saved ? JSON.parse(saved) : [];
  });

  const [notifications, setNotifications] = useState<Notification[]>(() => {
    const saved = localStorage.getItem('achei_notifications');
    return saved ? JSON.parse(saved) : [];
  });

  const [selectedItem, setSelectedItem] = useState<Item | null>(null);
  const [activeChat, setActiveChat] = useState<Item | null>(null);
  const [showFilters, setShowFilters] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [isViewingDelivery, setIsViewingDelivery] = useState(false);

  const [filters, setFilters] = useState({
    status: 'ALL' as ItemStatus | 'ALL',
    category: 'ALL' as Category | 'ALL',
    province: 'ALL' as string | 'ALL',
    date: '' as string,
    searchQuery: ''
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [newItem, setNewItem] = useState<Partial<Item>>({
    status: ItemStatus.LOST,
    category: Category.DOCUMENTS,
    province: 'Maputo Cidade',
    date: new Date().toISOString().split('T')[0]
  });

  // Monitorar status de rede
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Persistência
  useEffect(() => {
    localStorage.setItem('achei_items', JSON.stringify(items));
  }, [items]);
  useEffect(() => {
    localStorage.setItem('achei_messages', JSON.stringify(messages));
  }, [messages]);
  useEffect(() => {
    localStorage.setItem('achei_notifications', JSON.stringify(notifications));
  }, [notifications]);

  // Lógica de Rastreamento em Tempo Real
  const startTracking = (itemId: string) => {
    if (!("geolocation" in navigator)) {
      alert("Geolocalização não disponível.");
      return;
    }

    setTrackingItemId(itemId);
    setItems(prev => prev.map(i => i.id === itemId ? { ...i, isTrackingActive: true, status: ItemStatus.IN_TRANSIT } : i));

    watchIdRef.current = navigator.geolocation.watchPosition(
      (position) => {
        const { latitude, longitude } = position.coords;
        setItems(prev => prev.map(i => i.id === itemId ? { 
          ...i, 
          transitLatitude: latitude, 
          transitLongitude: longitude 
        } : i));
      },
      (error) => {
        console.error("Erro no rastreamento:", error);
        stopTracking(itemId);
      },
      { enableHighAccuracy: true, maximumAge: 0 }
    );

    const deliveryNotif: Notification = {
      id: Math.random().toString(36).substr(2, 5),
      type: 'DELIVERY',
      title: 'Entrega Iniciada!',
      description: 'O transportador iniciou o percurso. Acompanhe no mapa em tempo real.',
      itemId: itemId,
      timestamp: new Date().toISOString(),
      isRead: false
    };
    setNotifications(prev => [deliveryNotif, ...prev]);
  };

  const stopTracking = (itemId: string) => {
    if (watchIdRef.current !== null) {
      navigator.geolocation.clearWatch(watchIdRef.current);
      watchIdRef.current = null;
    }
    setTrackingItemId(null);
    setItems(prev => prev.map(i => i.id === itemId ? { ...i, isTrackingActive: false } : i));
    alert("Rastreamento encerrado.");
  };

  const activeFiltersCount = useMemo(() => {
    let count = 0;
    if (filters.status !== 'ALL') count++;
    if (filters.category !== 'ALL') count++;
    if (filters.province !== 'ALL') count++;
    if (filters.date !== '') count++;
    return count;
  }, [filters]);

  const unreadNotificationsCount = useMemo(() => {
    return notifications.filter(n => !n.isRead).length;
  }, [notifications]);

  const filteredItems = useMemo(() => {
    return items.filter(item => {
      const statusMatch = filters.status === 'ALL' || item.status === filters.status;
      const categoryMatch = filters.category === 'ALL' || item.category === filters.category;
      const provinceMatch = filters.province === 'ALL' || item.province === filters.province;
      const dateMatch = !filters.date || item.date === filters.date;
      const searchMatch = !filters.searchQuery || 
                          item.title.toLowerCase().includes(filters.searchQuery.toLowerCase()) || 
                          item.description.toLowerCase().includes(filters.searchQuery.toLowerCase());

      return statusMatch && categoryMatch && provinceMatch && dateMatch && searchMatch;
    }).sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  }, [items, filters]);

  const handlePostSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    const id = Math.random().toString(36).substr(2, 9);
    const lat = -25.9692 + (Math.random() - 0.5) * 0.05;
    const lng = 32.5732 + (Math.random() - 0.5) * 0.05;

    const item: Item = {
      id,
      title: newItem.title || 'Sem Título',
      description: newItem.description || '',
      category: newItem.category as Category,
      status: newItem.status as ItemStatus,
      location: newItem.location || 'N/A',
      province: newItem.province || 'Maputo Cidade',
      date: newItem.date || new Date().toISOString(),
      reward: newItem.reward,
      imageUrl: `https://picsum.photos/seed/${id}/400/300`,
      imageUrls: [`https://picsum.photos/seed/${id}/400/300`],
      userId: 'currentUser',
      createdAt: new Date().toISOString(),
      latitude: lat,
      longitude: lng
    };
    setItems(prev => [item, ...prev]);
    setIsSubmitting(false);
    setActiveTab('feed');
  };

  const handleEditSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingItem) return;

    setItems(prev => prev.map(i => i.id === editingItem.id ? editingItem : i));
    setEditingItem(null);
    alert("Item atualizado com sucesso!");
  };

  const handleSendMessage = (text: string) => {
    if (!activeChat) return;
    const msg: Message = {
      id: Math.random().toString(36).substr(2, 9),
      itemId: activeChat.id,
      senderId: 'currentUser',
      receiverId: activeChat.userId,
      text,
      timestamp: new Date().toISOString()
    };
    setMessages(prev => [...prev, msg]);
  };

  const handleNotificationClick = (notif: Notification) => {
    const item = items.find(i => i.id === notif.itemId);
    if (item) {
      if (notif.type === 'DELIVERY') {
        setSelectedItem(item);
        setIsViewingDelivery(true);
      } else {
        setSelectedItem(item);
      }
      setNotifications(prev => prev.map(n => n.id === notif.id ? { ...n, isRead: true } : n));
      setShowNotifications(false);
    }
  };

  const myItems = useMemo(() => items.filter(i => i.userId === 'currentUser'), [items]);

  const renderFeed = () => (
    <div className="h-full flex flex-col">
      <div className="p-4 space-y-4 bg-white border-b shadow-sm z-10">
        <div className="flex items-center justify-between">
          <h2 className="text-xl font-black text-gray-900 border-l-4 border-[#d21034] pl-3 uppercase">
            Radar Moçambique
          </h2>
          <div className="flex bg-gray-100 p-1 rounded-xl">
            <button onClick={() => setViewMode('list')} className={`p-2 px-4 rounded-lg text-[10px] font-black uppercase transition-all ${viewMode === 'list' ? 'bg-white shadow-sm text-[#009739]' : 'text-gray-400'}`}>
              <i className="fa-solid fa-list mr-2"></i> Lista
            </button>
            <button onClick={() => setViewMode('map')} className={`p-2 px-4 rounded-lg text-[10px] font-black uppercase transition-all ${viewMode === 'map' ? 'bg-white shadow-sm text-[#009739]' : 'text-gray-400'}`}>
              <i className="fa-solid fa-map-location-dot mr-2"></i> Mapa
            </button>
          </div>
        </div>

        <div className="flex gap-2">
          <div className="relative flex-1">
            <i className="fa-solid fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"></i>
            <input 
              type="text" 
              placeholder="Ex: BI, Chaves, Cão..." 
              className="w-full bg-gray-50 border-2 border-transparent focus:border-[#009739] rounded-xl py-3 pl-10 pr-4 outline-none transition-all text-sm"
              value={filters.searchQuery}
              onChange={(e) => setFilters({ ...filters, searchQuery: e.target.value })}
            />
          </div>
          <button onClick={() => setShowFilters(!showFilters)} className={`px-4 rounded-xl border-2 transition-all flex items-center gap-2 ${showFilters || activeFiltersCount > 0 ? 'bg-[#fce100] border-[#fce100] text-black' : 'bg-white border-gray-100 text-gray-400'}`}>
            <i className="fa-solid fa-sliders"></i>
            {activeFiltersCount > 0 && <span className="bg-black text-white text-[10px] rounded-full w-4 h-4 flex items-center justify-center font-bold">{activeFiltersCount}</span>}
          </button>
        </div>

        {showFilters && (
          <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100 grid grid-cols-2 gap-3 animate-in fade-in slide-in-from-top-2 duration-300">
            <div className="col-span-2">
              <label className="text-[10px] font-black text-gray-400 uppercase mb-1 block">Estado</label>
              <div className="flex gap-2">
                {['ALL', ItemStatus.LOST, ItemStatus.FOUND].map((s) => (
                  <button key={s} onClick={() => setFilters({...filters, status: s as any})} className={`flex-1 py-2 rounded-lg text-xs font-bold border-2 transition-all ${filters.status === s ? 'bg-black border-black text-white' : 'bg-white border-gray-200 text-gray-400'}`}>
                    {s === 'ALL' ? 'Todos' : s === ItemStatus.LOST ? 'Perdido' : 'Achado'}
                  </button>
                ))}
              </div>
            </div>
            <div>
              <label className="text-[10px] font-black text-gray-400 uppercase mb-1 block">Província</label>
              <select className="w-full bg-white border-2 border-gray-200 rounded-lg p-2 text-xs font-semibold outline-none" value={filters.province} onChange={e => setFilters({...filters, province: e.target.value})}>
                <option value="ALL">Todas</option>
                {MOZAMBIQUE_PROVINCES.map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>
          </div>
        )}
      </div>

      <div className="flex-1 overflow-hidden">
        {viewMode === 'list' ? (
          <div className="p-4 grid grid-cols-2 gap-4 overflow-y-auto h-full pb-24 no-scrollbar">
            {filteredItems.map(item => (
              <ItemCard key={item.id} item={item} onViewDetails={setSelectedItem} />
            ))}
          </div>
        ) : (
          <div className="w-full h-full pb-20">
             <MapView items={filteredItems} onViewDetails={setSelectedItem} />
          </div>
        )}
      </div>
    </div>
  );

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={setActiveTab} 
      notificationCount={unreadNotificationsCount}
      onToggleNotifications={() => setShowNotifications(!showNotifications)}
      isOnline={isOnline}
    >
      {showNotifications && (
        <NotificationDrawer 
          notifications={notifications} 
          onClose={() => setShowNotifications(false)}
          onNotificationClick={handleNotificationClick}
          onClear={() => setNotifications([])}
        />
      )}

      {isViewingDelivery && selectedItem ? (
        <DeliveryTrackingView 
          item={items.find(i => i.id === selectedItem.id) || selectedItem} 
          onBack={() => setIsViewingDelivery(false)} 
        />
      ) : activeChat ? (
        <ChatView 
          item={activeChat} 
          messages={messages.filter(m => m.itemId === activeChat.id)}
          onSendMessage={handleSendMessage}
          onBack={() => setActiveChat(null)}
          notificationCount={unreadNotificationsCount}
          isTracking={activeChat.isTrackingActive}
          onStartTracking={() => startTracking(activeChat.id)}
          onStopTracking={() => stopTracking(activeChat.id)}
          onViewTracking={() => setIsViewingDelivery(true)}
        />
      ) : selectedItem ? (
        <ItemDetails 
          item={selectedItem} 
          allContextItems={items}
          onBack={() => setSelectedItem(null)} 
          onStartChat={(item) => setActiveChat(item)}
          onViewItem={(item) => setSelectedItem(item)}
        />
      ) : (
        <>
          {activeTab === 'feed' && renderFeed()}
          {activeTab === 'post' && (
             <div className="p-6 pb-24 overflow-y-auto h-full no-scrollbar">
                <h2 className="text-2xl font-black mb-6 text-gray-900 border-l-8 border-[#fce100] pl-4 uppercase">Novo Registo</h2>
                <form onSubmit={handlePostSubmit} className="space-y-5">
                  <div>
                    <label className="block text-xs font-black text-gray-500 uppercase mb-2">Estado</label>
                    <div className="grid grid-cols-2 gap-3">
                      <button type="button" onClick={() => setNewItem({...newItem, status: ItemStatus.LOST})} className={`p-4 rounded-2xl border-2 font-black transition-all ${newItem.status === ItemStatus.LOST ? 'border-[#d21034] bg-[#d21034] text-white shadow-lg' : 'border-gray-100 bg-gray-50 text-gray-400'}`}>PERDI</button>
                      <button type="button" onClick={() => setNewItem({...newItem, status: ItemStatus.FOUND})} className={`p-4 rounded-2xl border-2 font-black transition-all ${newItem.status === ItemStatus.FOUND ? 'border-[#009739] bg-[#009739] text-white shadow-lg' : 'border-gray-100 bg-gray-50 text-gray-400'}`}>ACHEI</button>
                    </div>
                  </div>
                  <div className="bg-gray-50 p-6 rounded-3xl space-y-4 border border-gray-100">
                    <input required className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 outline-none font-semibold shadow-sm" placeholder="Título do Item..." value={newItem.title || ''} onChange={e => setNewItem({...newItem, title: e.target.value})} />
                    <select className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 text-sm font-bold shadow-sm" value={newItem.category} onChange={e => setNewItem({...newItem, category: e.target.value as Category})}>
                      {Object.values(Category).map(cat => <option key={cat} value={cat}>{cat}</option>)}
                    </select>
                    <select className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 text-sm font-bold shadow-sm" value={newItem.province} onChange={e => setNewItem({...newItem, province: e.target.value})}>
                      {MOZAMBIQUE_PROVINCES.map(p => <option key={p} value={p}>{p}</option>)}
                    </select>
                    <input className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 outline-none font-semibold shadow-sm" placeholder="Localização..." value={newItem.location || ''} onChange={e => setNewItem({...newItem, location: e.target.value})} />
                    <textarea className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 h-24 resize-none font-medium shadow-sm" placeholder="Descrição..." value={newItem.description || ''} onChange={e => setNewItem({...newItem, description: e.target.value})}></textarea>
                  </div>
                  <button disabled={isSubmitting} className="w-full bg-black text-[#fce100] py-5 rounded-2xl font-black shadow-xl uppercase tracking-widest disabled:opacity-50">
                    {isSubmitting ? 'Publicando...' : 'Publicar Agora'}
                  </button>
                </form>
              </div>
          )}
          {activeTab === 'profile' && (
             <div className="p-6 text-center pb-24 h-full overflow-y-auto no-scrollbar relative">
                {editingItem ? (
                  <div className="animate-in slide-in-from-bottom duration-300">
                    <button onClick={() => setEditingItem(null)} className="flex items-center text-[#009739] mb-4 gap-2 font-black uppercase text-xs">
                      <i className="fa-solid fa-arrow-left"></i> Cancelar Edição
                    </button>
                    <h2 className="text-xl font-black mb-6 text-left border-l-8 border-[#009739] pl-4 uppercase">Editar Item</h2>
                    <form onSubmit={handleEditSubmit} className="space-y-4 text-left">
                       <div className="bg-gray-50 p-6 rounded-3xl space-y-4 border border-gray-100">
                          <label className="block text-[10px] font-black text-gray-400 uppercase ml-1">Título</label>
                          <input required className="w-full bg-white border-2 border-gray-100 focus:border-[#009739] rounded-xl p-3 outline-none font-semibold" value={editingItem.title} onChange={e => setEditingItem({...editingItem, title: e.target.value})} />

                          <label className="block text-[10px] font-black text-gray-400 uppercase ml-1">Descrição</label>
                          <textarea className="w-full bg-white border-2 border-gray-100 focus:border-[#009739] rounded-xl p-3 h-24 resize-none font-medium" value={editingItem.description} onChange={e => setEditingItem({...editingItem, description: e.target.value})}></textarea>

                          <div className="grid grid-cols-2 gap-3">
                            <div>
                              <label className="block text-[10px] font-black text-gray-400 uppercase mb-1 ml-1">Categoria</label>
                              <select className="w-full bg-white border-2 border-gray-100 rounded-xl p-2 text-xs font-bold" value={editingItem.category} onChange={e => setEditingItem({...editingItem, category: e.target.value as Category})}>
                                {Object.values(Category).map(cat => <option key={cat} value={cat}>{cat}</option>)}
                              </select>
                            </div>
                            <div>
                              <label className="block text-[10px] font-black text-gray-400 uppercase mb-1 ml-1">Província</label>
                              <select className="w-full bg-white border-2 border-gray-100 rounded-xl p-2 text-xs font-bold" value={editingItem.province} onChange={e => setEditingItem({...editingItem, province: e.target.value})}>
                                {MOZAMBIQUE_PROVINCES.map(p => <option key={p} value={p}>{p}</option>)}
                              </select>
                            </div>
                          </div>

                          <label className="block text-[10px] font-black text-gray-400 uppercase ml-1">Recompensa (MT)</label>
                          <input type="number" className="w-full bg-white border-2 border-gray-100 focus:border-[#009739] rounded-xl p-3 outline-none font-semibold" value={editingItem.reward || ''} onChange={e => setEditingItem({...editingItem, reward: parseInt(e.target.value) || 0})} />
                       </div>
                       <button type="submit" className="w-full bg-[#009739] text-white py-5 rounded-2xl font-black shadow-xl uppercase tracking-widest active:scale-95 transition-all">
                         Guardar Alterações
                       </button>
                    </form>
                  </div>
                ) : profileView === 'my-posts' ? (
                  <div className="animate-in slide-in-from-right duration-300">
                    <button onClick={() => setProfileView('main')} className="flex items-center text-[#009739] mb-6 gap-2 font-black uppercase text-xs">
                      <i className="fa-solid fa-arrow-left"></i> Voltar ao Perfil
                    </button>
                    <h2 className="text-xl font-black mb-6 text-left border-l-8 border-[#d21034] pl-4 uppercase">Meus Registos</h2>
                    {myItems.length === 0 ? (
                      <div className="py-20 opacity-30">
                        <i className="fa-solid fa-box-open text-5xl mb-4"></i>
                        <p className="font-black uppercase text-sm">Nada publicado ainda</p>
                      </div>
                    ) : (
                      <div className="space-y-4">
                        {myItems.map(item => (
                          <div key={item.id} className="bg-white border-2 border-gray-50 rounded-[2rem] p-4 flex gap-4 items-center shadow-sm">
                            <img src={item.imageUrl} className="w-16 h-16 rounded-2xl object-cover shadow-inner" alt="" />
                            <div className="flex-1 text-left min-w-0">
                               <div className="text-[8px] font-black text-[#009739] uppercase mb-0.5">{item.category}</div>
                               <h3 className="font-black text-xs uppercase truncate leading-tight">{item.title}</h3>
                               <div className="text-[10px] font-bold text-gray-400">{item.status === ItemStatus.LOST ? 'Perdido' : 'Achado'}</div>
                            </div>
                            <button 
                              onClick={() => setEditingItem(item)}
                              className="w-10 h-10 bg-gray-50 text-gray-400 hover:bg-[#fce100] hover:text-black rounded-xl flex items-center justify-center transition-colors"
                            >
                              <i className="fa-solid fa-pen-to-square"></i>
                            </button>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                ) : (
                  <div className="animate-in fade-in duration-500">
                    <div className="w-28 h-28 bg-gradient-to-tr from-[#009739] to-[#fce100] rounded-full mx-auto mb-6 p-1">
                      <div className="bg-white rounded-full w-full h-full flex items-center justify-center text-[#d21034] text-4xl font-black overflow-hidden border-4 border-white">
                        <img src="https://api.dicebear.com/7.x/avataaars/svg?seed=Moz" alt="Profile" />
                      </div>
                    </div>
                    <h2 className="text-2xl font-black text-gray-900 uppercase">Utilizador Moz</h2>
                    <p className="text-gray-400 font-bold text-xs mb-8 uppercase tracking-widest">Maputo, Moçambique</p>

                    <div className="grid grid-cols-2 gap-4 mb-8">
                      <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100">
                        <div className="text-2xl font-black text-[#009739]">{myItems.length}</div>
                        <div className="text-[8px] font-black text-gray-400 uppercase">Publicações</div>
                      </div>
                      <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100">
                        <div className="text-2xl font-black text-[#d21034]">2</div>
                        <div className="text-[8px] font-black text-gray-400 uppercase">Resgates</div>
                      </div>
                    </div>

                    <div className="space-y-3">
                      <button 
                        onClick={() => setProfileView('my-posts')}
                        className="w-full bg-white border-2 border-gray-50 p-4 rounded-2xl flex items-center gap-4 hover:border-[#fce100] transition-colors group text-left"
                      >
                        <div className="bg-emerald-100 text-[#009739] p-3 rounded-xl group-hover:bg-[#009739] group-hover:text-white transition-colors"><i className="fa-solid fa-briefcase"></i></div>
                        <span className="font-black text-gray-700 uppercase text-xs">Meus Registos</span>
                      </button>
                      <button className="w-full bg-white border-2 border-gray-50 p-4 rounded-2xl flex items-center gap-4 hover:border-[#fce100] transition-colors group text-left">
                        <div className="bg-red-100 text-[#d21034] p-3 rounded-xl group-hover:bg-[#d21034] group-hover:text-white transition-colors"><i className="fa-solid fa-shield-halved"></i></div>
                        <span className="font-black text-gray-700 uppercase text-xs">Privacidade e Segurança</span>
                      </button>
                      <button className="w-full bg-white border-2 border-gray-50 p-4 rounded-2xl flex items-center gap-4 hover:border-red-100 transition-colors group text-left">
                        <div className="bg-gray-100 text-gray-400 p-3 rounded-xl group-hover:bg-red-500 group-hover:text-white transition-colors"><i className="fa-solid fa-right-from-bracket"></i></div>
                        <span className="font-black text-gray-700 uppercase text-xs">Sair da Conta</span>
                      </button>
                    </div>
                  </div>
                )}
              </div>
          )}
        </>
      )}
    </Layout>
  );
};

