import React, { useState } from 'react';
import { Item, ItemStatus } from '../types';
import { analyzeItemMatch } from '../services/geminiService';

interface ItemDetailsProps {
  item: Item;
  allContextItems: Item[];
  onBack: () => void;
  onStartChat: (item: Item) => void;
  onViewItem: (item: Item) => void;
}

const ItemDetails: React.FC<ItemDetailsProps> = ({ item, allContextItems, onBack, onStartChat, onViewItem }) => {
  const [analyzing, setAnalyzing] = useState(false);
  const [matchResult, setMatchResult] = useState<{item: Item, result: any} | null>(null);
  const [currentImgIndex, setCurrentImgIndex] = useState(0);

  // Estados para o Modal de Denúncia
  const [isReportModalOpen, setIsReportModalOpen] = useState(false);
  const [reportReason, setReportReason] = useState('');
  const [reportDetails, setReportDetails] = useState('');
  const [isSubmittingReport, setIsSubmittingReport] = useState(false);

  const images = item.imageUrls && item.imageUrls.length > 0 
    ? item.imageUrls 
    : [item.imageUrl || 'https://picsum.photos/seed/placeholder/400/300'];

  const nextImage = () => {
    setCurrentImgIndex((prev) => (prev + 1) % images.length);
  };

  const prevImage = () => {
    setCurrentImgIndex((prev) => (prev - 1 + images.length) % images.length);
  };

  const handleCheckMatch = async () => {
    setAnalyzing(true);
    const candidates = allContextItems.filter(i => 
      i.id !== item.id && 
      i.status !== item.status && 
      i.category === item.category
    );

    if (candidates.length === 0) {
      alert("Nenhum item similar encontrado no sistema ainda.");
      setAnalyzing(false);
      return;
    }

    const topCandidate = candidates[0];
    const res = await analyzeItemMatch(
      item.status === ItemStatus.LOST ? item : topCandidate,
      item.status === ItemStatus.FOUND ? item : topCandidate
    );

    setMatchResult({ item: topCandidate, result: res });
    setAnalyzing(false);
  };

  const handleCall = () => {
    if (item.ownerPhone) {
      window.location.href = `tel:${item.ownerPhone}`;
    } else {
      alert("Número de telefone não disponível para este utilizador.");
    }
  };

  const handleSendReport = (e: React.FormEvent) => {
    e.preventDefault();
    if (!reportReason) {
      alert("Por favor, selecione um motivo.");
      return;
    }
    setIsSubmittingReport(true);

    // Simulação de envio de denúncia
    setTimeout(() => {
      alert("Denúncia enviada com sucesso! Nossa equipe irá analisar o conteúdo.");
      setIsSubmittingReport(false);
      setIsReportModalOpen(false);
      setReportReason('');
      setReportDetails('');
    }, 1500);
  };

  const suggestions = allContextItems
    .filter(i => i.id !== item.id && i.category === item.category)
    .slice(0, 3);

  return (
    <div className="p-4 bg-white min-h-full pb-10 relative">
      <button 
        onClick={onBack} 
        className="flex items-center text-[#009739] mb-4 gap-2 font-black uppercase text-xs hover:translate-x-[-4px] transition-transform"
      >
        <i className="fa-solid fa-arrow-left"></i> Voltar à Explorar
      </button>

      {/* Image Carousel */}
      <div className="relative group mb-6 overflow-hidden rounded-3xl shadow-2xl bg-gray-100 aspect-video">
        <div 
          className="flex transition-transform duration-500 ease-out h-full"
          style={{ transform: `translateX(-${currentImgIndex * 100}%)` }}
        >
          {images.map((img, idx) => (
            <img 
              key={idx}
              src={img} 
              alt={`${item.title} - ${idx + 1}`} 
              className="w-full h-full object-cover flex-shrink-0"
            />
          ))}
        </div>

        {images.length > 1 && (
          <>
            <button 
              onClick={prevImage}
              className="absolute left-4 top-1/2 -translate-y-1/2 bg-white/80 hover:bg-white text-black p-3 rounded-full shadow-lg opacity-0 group-hover:opacity-100 transition-opacity z-10"
            >
              <i className="fa-solid fa-chevron-left"></i>
            </button>
            <button 
              onClick={nextImage}
              className="absolute right-4 top-1/2 -translate-y-1/2 bg-white/80 hover:bg-white text-black p-3 rounded-full shadow-lg opacity-0 group-hover:opacity-100 transition-opacity z-10"
            >
              <i className="fa-solid fa-chevron-right"></i>
            </button>

            <div className="absolute bottom-4 left-1/2 -translate-x-1/2 flex gap-2 z-10">
              {images.map((_, idx) => (
                <button
                  key={idx}
                  onClick={() => setCurrentImgIndex(idx)}
                  className={`h-2 rounded-full transition-all ${
                    idx === currentImgIndex 
                      ? 'w-6 bg-[#fce100]' 
                      : 'w-2 bg-white/50'
                  }`}
                />
              ))}
            </div>
          </>
        )}

        <div className={`absolute top-4 right-4 px-4 py-1.5 rounded-full text-[10px] font-black uppercase shadow-lg z-10 ${
          item.status === ItemStatus.LOST ? 'bg-[#d21034] text-white' : 'bg-[#009739] text-white'
        }`}>
          {item.status === ItemStatus.LOST ? 'Perdido' : 'Achado'}
        </div>
      </div>

      <div className="space-y-6">
        <div className="flex justify-between items-start">
          <div className="flex-1">
            <div className="text-[10px] text-[#009739] font-black uppercase tracking-[0.2em] mb-1">{item.category}</div>
            <h2 className="text-3xl font-black text-gray-900 leading-tight uppercase tracking-tight">{item.title}</h2>
          </div>
          <button 
            onClick={() => setIsReportModalOpen(true)}
            className="text-gray-300 hover:text-[#d21034] transition-colors p-2"
            title="Denunciar este item"
          >
            <i className="fa-solid fa-flag text-xl"></i>
          </button>
        </div>

        <div className="flex flex-wrap gap-4 text-sm font-bold">
          <div className="flex items-center gap-2 bg-gray-50 px-4 py-2 rounded-2xl border border-gray-100">
            <i className="fa-solid fa-location-dot text-[#d21034]"></i>
            <span>{item.location}, {item.province}</span>
          </div>
          <div className="flex items-center gap-2 bg-gray-50 px-4 py-2 rounded-2xl border border-gray-100">
            <i className="fa-solid fa-calendar text-[#009739]"></i>
            <span>{new Date(item.date).toLocaleDateString('pt-MZ', { day: '2-digit', month: 'long', year: 'numeric' })}</span>
          </div>
        </div>

        <div className="bg-gray-50 p-6 rounded-3xl border border-gray-100">
          <h3 className="text-[10px] font-black text-gray-400 uppercase mb-3 tracking-widest">Descrição</h3>
          <p className="text-gray-700 leading-relaxed font-medium">{item.description}</p>
        </div>

        {item.reward && (
          <div className="bg-[#fce100]/20 p-6 rounded-3xl border-2 border-[#fce100] flex items-center justify-between">
            <div>
              <h3 className="text-[10px] font-black text-[#8a7b00] uppercase mb-1 tracking-widest">Recompensa Oferecida</h3>
              <p className="text-2xl font-black text-black">{item.reward.toLocaleString()} MT</p>
            </div>
            <div className="bg-[#fce100] p-4 rounded-2xl shadow-lg">
              <i className="fa-solid fa-coins text-2xl text-black"></i>
            </div>
          </div>
        )}

        <div className="space-y-4 pt-4">
          <div className="grid grid-cols-2 gap-4">
            <button 
              onClick={() => onStartChat(item)}
              className="bg-black text-[#fce100] py-5 rounded-2xl font-black uppercase tracking-widest shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3"
            >
              <i className="fa-solid fa-message"></i> Mensagem
            </button>

            <button 
              onClick={handleCall}
              className="bg-[#fce100] text-black py-5 rounded-2xl font-black uppercase tracking-widest shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3"
            >
              <i className="fa-solid fa-phone"></i> Ligar
            </button>
          </div>

          <button 
            onClick={handleCheckMatch}
            disabled={analyzing}
            className={`w-full py-5 rounded-2xl font-black uppercase tracking-widest border-2 transition-all flex items-center justify-center gap-3 active:scale-95 shadow-lg ${
              analyzing ? 'bg-gray-100 border-gray-200 text-gray-400' : 'bg-white border-black text-black hover:bg-gray-50'
            }`}
          >
            {analyzing ? (
              <i className="fa-solid fa-spinner animate-spin"></i>
            ) : (
              <i className="fa-solid fa-wand-magic-sparkles"></i>
            )}
            {analyzing ? 'Analisando...' : 'Verificar Match IA'}
          </button>
        </div>

        {matchResult && (
          <div className="bg-gradient-to-br from-indigo-600 to-purple-700 p-6 rounded-3xl text-white shadow-2xl animate-in zoom-in-95 duration-500">
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center gap-3">
                <div className="bg-white/20 p-2 rounded-xl">
                  <i className="fa-solid fa-robot"></i>
                </div>
                <h3 className="font-black text-xs uppercase tracking-widest">Resultado da IA</h3>
              </div>
              <div className="bg-white/20 px-3 py-1 rounded-full font-black text-[10px] uppercase">
                {matchResult.result.similarity}% de Match
              </div>
            </div>
            <p className="text-sm font-bold mb-6 bg-white/10 p-4 rounded-2xl border border-white/10 italic">"{matchResult.result.reasoning}"</p>
            <div className="bg-white rounded-2xl p-4 flex items-center gap-4 text-black cursor-pointer hover:bg-gray-50 transition-colors" onClick={() => onViewItem(matchResult.item)}>
              <img src={matchResult.item.imageUrl} className="w-12 h-12 rounded-xl object-cover shadow-sm" alt="" />
              <div className="flex-1 min-w-0">
                <div className="text-[8px] font-black text-indigo-600 uppercase mb-0.5">{matchResult.item.category}</div>
                <div className="font-black text-xs truncate uppercase">{matchResult.item.title}</div>
              </div>
              <i className="fa-solid fa-chevron-right text-gray-300"></i>
            </div>
          </div>
        )}

        {suggestions.length > 0 && (
          <div className="space-y-4 pt-6">
            <h3 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">Itens Sugeridos</h3>
            <div className="flex gap-4 overflow-x-auto pb-4 no-scrollbar">
              {suggestions.map(s => (
                <div 
                  key={s.id} 
                  onClick={() => onViewItem(s)}
                  className="min-w-[140px] bg-white rounded-2xl border border-gray-100 overflow-hidden shadow-sm active:scale-95 transition-transform"
                >
                  <img src={s.imageUrl} className="w-full h-24 object-cover" alt="" />
                  <div className="p-3">
                    <h4 className="font-black text-[10px] line-clamp-1 uppercase leading-tight">{s.title}</h4>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Modal de Denúncia */}
      {isReportModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm animate-in fade-in duration-300" onClick={() => setIsReportModalOpen(false)}></div>
          <div className="relative bg-white w-full max-w-sm rounded-[2.5rem] p-8 shadow-2xl animate-in zoom-in-95 duration-300">
            <div className="text-center mb-6">
              <div className="w-16 h-16 bg-red-50 text-[#d21034] rounded-full flex items-center justify-center mx-auto mb-4 text-2xl border-4 border-white shadow-lg">
                <i className="fa-solid fa-triangle-exclamation"></i>
              </div>
              <h2 className="text-xl font-black text-gray-900 uppercase">Denunciar Item</h2>
              <p className="text-xs font-bold text-gray-400 mt-1">Ajude-nos a manter a comunidade segura.</p>
            </div>

            <form onSubmit={handleSendReport} className="space-y-4">
              <div>
                <label className="block text-[10px] font-black text-gray-400 uppercase mb-2 ml-1">Motivo da Denúncia</label>
                <div className="space-y-2">
                  {[
                    { id: 'wrong', label: 'Item Incorreto/Trocado' },
                    { id: 'fake', label: 'Informação Falsa' },
                    { id: 'spam', label: 'Spam ou Publicidade' },
                    { id: 'other', label: 'Outro Motivo' }
                  ].map((option) => (
                    <button
                      key={option.id}
                      type="button"
                      onClick={() => setReportReason(option.id)}
                      className={`w-full p-4 rounded-2xl text-left text-xs font-bold border-2 transition-all flex items-center justify-between ${
                        reportReason === option.id 
                          ? 'border-[#d21034] bg-red-50 text-[#d21034]' 
                          : 'border-gray-50 bg-gray-50 text-gray-500 hover:border-gray-100'
                      }`}
                    >
                      {option.label}
                      {reportReason === option.id && <i className="fa-solid fa-circle-check"></i>}
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="block text-[10px] font-black text-gray-400 uppercase mb-2 ml-1">Detalhes Adicionais (Opcional)</label>
                <textarea
                  className="w-full bg-gray-50 border-2 border-transparent focus:border-[#d21034] rounded-2xl p-4 text-xs font-bold outline-none transition-all h-24 resize-none shadow-inner"
                  placeholder="Explique o que há de errado..."
                  value={reportDetails}
                  onChange={(e) => setReportDetails(e.target.value)}
                ></textarea>
              </div>

              <div className="flex gap-3 pt-4">
                <button
                  type="button"
                  onClick={() => setIsReportModalOpen(false)}
                  className="flex-1 py-4 rounded-2xl font-black uppercase text-xs text-gray-400 hover:bg-gray-100 transition-colors"
                >
                  Cancelar
                </button>
                <button
                  type="submit"
                  disabled={isSubmittingReport || !reportReason}
                  className="flex-[2] bg-[#d21034] text-white py-4 rounded-2xl font-black uppercase text-xs shadow-lg shadow-red-200 active:scale-95 transition-all disabled:opacity-50 disabled:grayscale"
                >
                  {isSubmittingReport ? (
                    <i className="fa-solid fa-circle-notch animate-spin mr-2"></i>
                  ) : (
                    <i className="fa-solid fa-paper-plane mr-2"></i>
                  )}
                  {isSubmittingReport ? 'Enviando...' : 'Enviar Denúncia'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

