                <label className="block text-[10px] font-black text-gray-400 uppercase mb-2 ml-1">Motivo da Denúncia</label>
                <div className="space-y-2">
                  {[
                    { id: 'wrong', label: 'Item Incorreto/Trocado' },
                    { id: 'fake', label: 'Informação Falsa' },
                    { id: 'spam', label: 'Spam ou Publicidade' },
                    { id: 'other', label: 'Outro Motivo' }
                  ].map((option) => (
                    <button
                      key={option.id}
                      type="button"
                      onClick={() => setReportReason(option.id)}
                      className={`w-full p-4 rounded-2xl text-left text-xs font-bold border-2 transition-all flex items-center justify-between ${
                        reportReason === option.id 
                          ? 'border-[#d21034] bg-red-50 text-[#d21034]' 
                          : 'border-gray-50 bg-gray-50 text-gray-500 hover:border-gray-100'
                      }`}
                    >
                      {option.label}
                      {reportReason === option.id && <i className="fa-solid fa-circle-check"></i>}
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="block text-[10px] font-black text-gray-400 uppercase mb-2 ml-1">Detalhes Adicionais (Opcional)</label>
                <textarea
                  className="w-full bg-gray-50 border-2 border-transparent focus:border-[#d21034] rounded-2xl p-4 text-xs font-bold outline-none transition-all h-24 resize-none shadow-inner"
                  placeholder="Explique o que há de errado..."
                  value={reportDetails}
                  onChange={(e) => setReportDetails(e.target.value)}
                ></textarea>
              </div>

              <div className="flex gap-3 pt-4">
                <button
                  type="button"
                  onClick={() => setIsReportModalOpen(false)}
                  className="flex-1 py-4 rounded-2xl font-black uppercase text-xs text-gray-400 hover:bg-gray-100 transition-colors"
                >
                  Cancelar
                </button>
                <button
                  type="submit"
                  disabled={isSubmittingReport || !reportReason}
                  className="flex-[2] bg-[#d21034] text-white py-4 rounded-2xl font-black uppercase text-xs shadow-lg shadow-red-200 active:scale-95 transition-all disabled:opacity-50 disabled:grayscale"
                >
                  {isSubmittingReport ? (
                    <i className="fa-solid fa-circle-notch animate-spin mr-2"></i>
                  ) : (
                    <i className="fa-solid fa-paper-plane mr-2"></i>
                  )}
                  {isSubmittingReport ? 'Enviando...' : 'Enviar Denúncia'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ItemDetails;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import Layout from './components/Layout';
import ItemCard from './components/ItemCard';
import ItemDetails from './components/ItemDetails';
import ChatView from './components/ChatView';
import MapView from './components/MapView';
import DeliveryTrackingView from './components/DeliveryTrackingView';
import NotificationDrawer from './components/NotificationDrawer';
import { Item, ItemStatus, Category, Message, Notification } from './types';
import { INITIAL_ITEMS, MOZAMBIQUE_PROVINCES } from './constants';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'feed' | 'post' | 'profile'>('feed');
  const [viewMode, setViewMode] = useState<'list' | 'map'>('list');
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [trackingItemId, setTrackingItemId] = useState<string | null>(null);
  const watchIdRef = useRef<number | null>(null);

  // Estados de navegação e edição no Perfil
  const [profileView, setProfileView] = useState<'main' | 'my-posts'>('main');
  const [editingItem, setEditingItem] = useState<Item | null>(null);

  // Inicialização de estado
  const [items, setItems] = useState<Item[]>(() => {
    const saved = localStorage.getItem('achei_items');
    return saved ? JSON.parse(saved) : INITIAL_ITEMS;
  });

  const [messages, setMessages] = useState<Message[]>(() => {
    const saved = localStorage.getItem('achei_messages');
    return saved ? JSON.parse(saved) : [];
  });

  const [notifications, setNotifications] = useState<Notification[]>(() => {
    const saved = localStorage.getItem('achei_notifications');
    return saved ? JSON.parse(saved) : [];
  });

  const [selectedItem, setSelectedItem] = useState<Item | null>(null);
  const [activeChat, setActiveChat] = useState<Item | null>(null);
  const [showFilters, setShowFilters] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [isViewingDelivery, setIsViewingDelivery] = useState(false);

  const [filters, setFilters] = useState({
    status: 'ALL' as ItemStatus | 'ALL',
    category: 'ALL' as Category | 'ALL',
    province: 'ALL' as string | 'ALL',
    date: '' as string,
    searchQuery: ''
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [newItem, setNewItem] = useState<Partial<Item>>({
    status: ItemStatus.LOST,
    category: Category.DOCUMENTS,
    province: 'Maputo Cidade',
    date: new Date().toISOString().split('T')[0]
  });

  // Monitorar status de rede
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Persistência
  useEffect(() => {
    localStorage.setItem('achei_items', JSON.stringify(items));
  }, [items]);
  useEffect(() => {
    localStorage.setItem('achei_messages', JSON.stringify(messages));
  }, [messages]);
  useEffect(() => {
    localStorage.setItem('achei_notifications', JSON.stringify(notifications));
  }, [notifications]);

  // Lógica de Rastreamento em Tempo Real
  const startTracking = (itemId: string) => {
    if (!("geolocation" in navigator)) {
      alert("Geolocalização não disponível.");
      return;
    }

    setTrackingItemId(itemId);
    setItems(prev => prev.map(i => i.id === itemId ? { ...i, isTrackingActive: true, status: ItemStatus.IN_TRANSIT } : i));

    watchIdRef.current = navigator.geolocation.watchPosition(
      (position) => {
        const { latitude, longitude } = position.coords;
        setItems(prev => prev.map(i => i.id === itemId ? { 
          ...i, 
          transitLatitude: latitude, 
          transitLongitude: longitude 
        } : i));
      },
      (error) => {
        console.error("Erro no rastreamento:", error);
        stopTracking(itemId);
      },
      { enableHighAccuracy: true, maximumAge: 0 }
    );

    const deliveryNotif: Notification = {
      id: Math.random().toString(36).substr(2, 5),
      type: 'DELIVERY',
      title: 'Entrega Iniciada!',
      description: 'O transportador iniciou o percurso. Acompanhe no mapa em tempo real.',
      itemId: itemId,
      timestamp: new Date().toISOString(),
      isRead: false
    };
    setNotifications(prev => [deliveryNotif, ...prev]);
  };

  const stopTracking = (itemId: string) => {
    if (watchIdRef.current !== null) {
      navigator.geolocation.clearWatch(watchIdRef.current);
      watchIdRef.current = null;
    }
    setTrackingItemId(null);
    setItems(prev => prev.map(i => i.id === itemId ? { ...i, isTrackingActive: false } : i));
  };

  const handleFinishDelivery = (itemId: string) => {
    stopTracking(itemId);

    // Atualizar status do item para reunido
    setItems(prev => prev.map(i => i.id === itemId ? { 
      ...i, 
      status: ItemStatus.REUNITED,
      isTrackingActive: false 
    } : i));

    // Adicionar notificação de conclusão
    const completionNotif: Notification = {
      id: Math.random().toString(36).substr(2, 5),
      type: 'DELIVERY',
      title: 'Entrega Concluída!',
      description: 'O item foi entregue com sucesso ao proprietário. Obrigado por usar o Achei! MZ.',
      itemId: itemId,
      timestamp: new Date().toISOString(),
      isRead: false
    };
    setNotifications(prev => [completionNotif, ...prev]);

    // Enviar mensagem automática no chat
    handleSendMessage("O item foi entregue com sucesso! 🎉");

    alert("Entrega finalizada com sucesso!");
  };

  const activeFiltersCount = useMemo(() => {
    let count = 0;
    if (filters.status !== 'ALL') count++;
    if (filters.category !== 'ALL') count++;
    if (filters.province !== 'ALL') count++;
    if (filters.date !== '') count++;
    return count;
  }, [filters]);

  const unreadNotificationsCount = useMemo(() => {
    return notifications.filter(n => !n.isRead).length;
  }, [notifications]);

  const filteredItems = useMemo(() => {
    return items.filter(item => {
      const statusMatch = filters.status === 'ALL' || item.status === filters.status;
      const categoryMatch = filters.category === 'ALL' || item.category === filters.category;
      const provinceMatch = filters.province === 'ALL' || item.province === filters.province;
      const dateMatch = !filters.date || item.date === filters.date;
      const searchMatch = !filters.searchQuery || 
                          item.title.toLowerCase().includes(filters.searchQuery.toLowerCase()) || 
                          item.description.toLowerCase().includes(filters.searchQuery.toLowerCase());

      return statusMatch && categoryMatch && provinceMatch && dateMatch && searchMatch;
    }).sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  }, [items, filters]);

  const handlePostSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    const id = Math.random().toString(36).substr(2, 9);
    const lat = -25.9692 + (Math.random() - 0.5) * 0.05;
    const lng = 32.5732 + (Math.random() - 0.5) * 0.05;

    const item: Item = {
      id,
      title: newItem.title || 'Sem Título',
      description: newItem.description || '',
      category: newItem.category as Category,
      status: newItem.status as ItemStatus,
      location: newItem.location || 'N/A',
      province: newItem.province || 'Maputo Cidade',
      date: newItem.date || new Date().toISOString(),
      reward: newItem.reward,
      imageUrl: `https://picsum.photos/seed/${id}/400/300`,
      imageUrls: [`https://picsum.photos/seed/${id}/400/300`],
      userId: 'currentUser',
      createdAt: new Date().toISOString(),
      latitude: lat,
      longitude: lng
    };
    setItems(prev => [item, ...prev]);
    setIsSubmitting(false);
    setActiveTab('feed');
  };

  const handleEditSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingItem) return;

    setItems(prev => prev.map(i => i.id === editingItem.id ? editingItem : i));
    setEditingItem(null);
    alert("Item atualizado com sucesso!");
  };

  const handleSendMessage = (text: string) => {
    if (!activeChat) return;
    const msg: Message = {
      id: Math.random().toString(36).substr(2, 9),
      itemId: activeChat.id,
      senderId: 'currentUser',
      receiverId: activeChat.userId,
      text,
      timestamp: new Date().toISOString()
    };
    setMessages(prev => [...prev, msg]);
  };

  const handleNotificationClick = (notif: Notification) => {
    const item = items.find(i => i.id === notif.itemId);
    if (item) {
      if (notif.type === 'DELIVERY') {
        setSelectedItem(item);
        setIsViewingDelivery(true);
      } else {
        setSelectedItem(item);
      }
      setNotifications(prev => prev.map(n => n.id === notif.id ? { ...n, isRead: true } : n));
      setShowNotifications(false);
    }
  };

  const myItems = useMemo(() => items.filter(i => i.userId === 'currentUser'), [items]);

  const renderFeed = () => (
    <div className="h-full flex flex-col">
      <div className="p-4 space-y-4 bg-white border-b shadow-sm z-10">
        <div className="flex items-center justify-between">
          <h2 className="text-xl font-black text-gray-900 border-l-4 border-[#d21034] pl-3 uppercase">
            Radar Moçambique
          </h2>
          <div className="flex bg-gray-100 p-1 rounded-xl">
            <button onClick={() => setViewMode('list')} className={`p-2 px-4 rounded-lg text-[10px] font-black uppercase transition-all ${viewMode === 'list' ? 'bg-white shadow-sm text-[#009739]' : 'text-gray-400'}`}>
              <i className="fa-solid fa-list mr-2"></i> Lista
            </button>
            <button onClick={() => setViewMode('map')} className={`p-2 px-4 rounded-lg text-[10px] font-black uppercase transition-all ${viewMode === 'map' ? 'bg-white shadow-sm text-[#009739]' : 'text-gray-400'}`}>
              <i className="fa-solid fa-map-location-dot mr-2"></i> Mapa
            </button>
          </div>
        </div>

        <div className="flex gap-2">
          <div className="relative flex-1">
            <i className="fa-solid fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"></i>
            <input 
              type="text" 
              placeholder="Ex: BI, Chaves, Cão..." 
              className="w-full bg-gray-50 border-2 border-transparent focus:border-[#009739] rounded-xl py-3 pl-10 pr-4 outline-none transition-all text-sm"
              value={filters.searchQuery}
              onChange={(e) => setFilters({ ...filters, searchQuery: e.target.value })}
            />
          </div>
