import React, { useState, useEffect, useRef } from 'react';
import { Item, Message } from '../types';

interface ChatViewProps {
  item: Item;
  messages: Message[];
  onSendMessage: (text: string) => void;
  onBack: () => void;
  notificationCount: number;
  isTracking?: boolean;
  onStartTracking?: () => void;
  onStopTracking?: () => void;
  onFinishDelivery?: () => void;
  onViewTracking?: () => void;
}

const ChatView: React.FC<ChatViewProps> = ({ 
  item, 
  messages, 
  onSendMessage, 
  onBack, 
  notificationCount,
  isTracking,
  onStartTracking,
  onStopTracking,
  onFinishDelivery,
  onViewTracking
}) => {
  const [inputText, setInputText] = useState('');
  const scrollRef = useRef<HTMLDivElement>(null);
  const [isTyping, setIsTyping] = useState(false);

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
    if (messages.length > 0) {
      setIsTyping(true);
      const timer = setTimeout(() => setIsTyping(false), 2000);
      return () => clearTimeout(timer);
    }
  }, [messages]);

  const handleSend = (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputText.trim()) return;
    onSendMessage(inputText);
    setInputText('');
  };

  return (
    <div className="flex flex-col h-full bg-[#f9f9f9]">
      {/* Chat Header */}
      <div className="bg-white p-4 border-b flex items-center gap-3 sticky top-0 z-20 shadow-sm">
        <button onClick={onBack} className="text-[#009739] p-2 relative active:scale-90 transition-transform">
          <i className="fa-solid fa-arrow-left"></i>
          {notificationCount > 0 && (
            <span className="absolute top-0 right-0 bg-[#d21034] text-white text-[7px] font-black w-3.5 h-3.5 flex items-center justify-center rounded-full border border-white shadow-sm animate-bounce">
              {notificationCount}
            </span>
          )}
        </button>

        <div className="w-10 h-10 rounded-full overflow-hidden border-2 border-gray-100 shadow-sm">
          <img src={item.imageUrl} className="w-full h-full object-cover" alt="" />
        </div>

        <div className="flex-1 overflow-hidden">
          <div className="font-black text-xs uppercase truncate text-gray-900">{item.title}</div>
          <div className="flex items-center gap-1.5">
            <div className={`w-1.5 h-1.5 rounded-full ${isTracking ? 'bg-[#009739] animate-pulse' : 'bg-gray-300'}`}></div>
            <div className="text-[9px] text-gray-400 font-black uppercase tracking-wider">
              {isTracking ? 'Rastreamento Ativo' : 'Chat de Resgate'}
            </div>
          </div>
        </div>
      </div>

      {/* Rastreamento Bar (Se ativo) */}
      {isTracking && (
        <div className="bg-[#009739] text-white px-4 py-2 flex justify-between items-center animate-in slide-in-from-top duration-300">
          <div className="flex items-center gap-2">
            <div className="w-2 h-2 bg-white rounded-full animate-ping"></div>
            <span className="text-[10px] font-black uppercase tracking-widest">Entrega em curso...</span>
          </div>
          <div className="flex gap-2">
             <button onClick={onViewTracking} className="bg-white/20 hover:bg-white/30 px-3 py-1 rounded-lg text-[9px] font-black uppercase">
               Ver Mapa
             </button>
             <button onClick={onFinishDelivery} className="bg-[#fce100] text-black hover:bg-white px-3 py-1 rounded-lg text-[9px] font-black uppercase transition-colors">
               Concluir
             </button>
             <button onClick={onStopTracking} className="bg-red-500/80 hover:bg-red-500 px-3 py-1 rounded-lg text-[9px] font-black uppercase">
               Parar
             </button>
          </div>
        </div>
      )}

      {/* Messages */}
      <div className="flex-1 overflow-y-auto p-4 space-y-4 no-scrollbar">
        {messages.length === 0 && (
          <div className="text-center py-16 px-10">
            <div className="w-16 h-16 bg-white rounded-full flex items-center justify-center mx-auto mb-4 shadow-sm text-[#009739]">
               <i className="fa-solid fa-shield-halved text-2xl"></i>
            </div>
            <h3 className="text-[10px] font-black uppercase text-gray-400 mb-1">Conversa Segura</h3>
            <p className="text-[11px] text-gray-500 font-bold leading-relaxed">
              Combine a entrega aqui. Lembre-se: locais públicos são mais seguros.
            </p>
          </div>
        )}

        {messages.map((msg, index) => {
          const isMe = msg.senderId === 'currentUser';
          return (
            <div key={msg.id} className={`flex flex-col ${isMe ? 'items-end' : 'items-start'} animate-in fade-in slide-in-from-bottom-2 duration-300`}>
              <div className={`max-w-[85%] p-3.5 rounded-2xl shadow-sm text-[13px] font-bold leading-snug ${
                isMe 
                  ? 'bg-black text-[#fce100] rounded-tr-none' 
                  : 'bg-white text-gray-800 rounded-tl-none border border-gray-100'
              }`}>
                {msg.text}
              </div>
            </div>
          );
        })}
        <div ref={scrollRef} />
      </div>

      {/* Input & Quick Actions */}
      <div className="p-4 bg-white border-t border-gray-100 shadow-[0_-4px_10px_rgba(0,0,0,0.02)]">
        {!isTracking && (
          <div className="flex gap-2 mb-3">
             <button 
               onClick={onStartTracking}
               className="flex-1 bg-gray-50 border-2 border-gray-100 hover:border-[#009739] text-gray-500 hover:text-[#009739] py-2 rounded-xl text-[10px] font-black uppercase transition-all flex items-center justify-center gap-2"
             >
               <i className="fa-solid fa-truck-fast"></i> Iniciar Entrega (Live)
             </button>
             <button 
               onClick={onFinishDelivery}
               className="flex-1 bg-gray-50 border-2 border-gray-100 text-gray-500 py-2 rounded-xl text-[10px] font-black uppercase flex items-center justify-center gap-2 hover:bg-[#009739] hover:text-white transition-all"
             >
               <i className="fa-solid fa-handshake"></i> Concluir Resgate
             </button>
          </div>
        )}

        <form onSubmit={handleSend} className="flex gap-2 items-center">
          <input 
            type="text"
            placeholder="Escreva sua mensagem..."
            className="w-full bg-gray-50 border-2 border-transparent focus:border-[#009739] rounded-2xl px-5 py-3.5 text-sm font-bold outline-none transition-all"
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
          />
          <button 
            type="submit"
            disabled={!inputText.trim()}
            className="bg-[#009739] text-white w-12 h-12 rounded-2xl flex items-center justify-center shadow-lg active:scale-95 transition-all disabled:opacity-30"
          >
            <i className="fa-solid fa-paper-plane"></i>
          </button>
        </form>
      </div>
    </div>
  );
};

