                Por segurança, combine encontros em locais públicos.
              </p>
            </div>
          </div>
        </div>
      )}

      {/* Modal de Denúncia */}
      {isReportModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
