          <div className="relative bg-white w-full max-w-sm rounded-[2.5rem] p-8 shadow-2xl animate-in zoom-in-95 duration-300">
            <div className="text-center mb-6">
              <div className="w-16 h-16 bg-red-50 text-[#d21034] rounded-full flex items-center justify-center mx-auto mb-4 text-2xl border-4 border-white shadow-lg">
                <i className="fa-solid fa-triangle-exclamation"></i>
              </div>
              <h2 className="text-xl font-black text-gray-900 uppercase">Denunciar Item</h2>
              <p className="text-xs font-bold text-gray-400 mt-1">Ajude-nos a manter a comunidade segura.</p>
            </div>

            <form onSubmit={handleSendReport} className="space-y-4">
              <div>
                <label className="block text-[10px] font-black text-gray-400 uppercase mb-2 ml-1">Motivo da Denúncia</label>
                <div className="space-y-2">
                  {[
                    { id: 'wrong', label: 'Item Incorreto/Trocado' },
                    { id: 'fake', label: 'Informação Falsa' },
                    { id: 'spam', label: 'Spam ou Publicidade' },
                    { id: 'other', label: 'Outro Motivo' }
                  ].map((option) => (
                    <button
                      key={option.id}
                      type="button"
                      onClick={() => setReportReason(option.id)}
                      className={`w-full p-4 rounded-2xl text-left text-xs font-bold border-2 transition-all flex items-center justify-between ${
                        reportReason === option.id 
                          ? 'border-[#d21034] bg-red-50 text-[#d21034]' 
                          : 'border-gray-50 bg-gray-50 text-gray-500 hover:border-gray-100'
                      }`}
                    >
                      {option.label}
                      {reportReason === option.id && <i className="fa-solid fa-circle-check"></i>}
                    </button>
                  ))}
                </div>
              </div>

              <div>
                <label className="block text-[10px] font-black text-gray-400 uppercase mb-2 ml-1">Detalhes Adicionais (Opcional)</label>
                <textarea
                  className="w-full bg-gray-50 border-2 border-transparent focus:border-[#d21034] rounded-2xl p-4 text-xs font-bold outline-none transition-all h-24 resize-none shadow-inner"
                  placeholder="Explique o que há de errado..."
                  value={reportDetails}
                  onChange={(e) => setReportDetails(e.target.value)}
                ></textarea>
              </div>

              <div className="flex gap-3 pt-4">
                <button
                  type="button"
                  onClick={() => setIsReportModalOpen(false)}
                  className="flex-1 py-4 rounded-2xl font-black uppercase text-xs text-gray-400 hover:bg-gray-100 transition-colors"
                >
                  Cancelar
                </button>
                <button
                  type="submit"
                  disabled={isSubmittingReport || !reportReason}
                  className="flex-[2] bg-[#d21034] text-white py-4 rounded-2xl font-black uppercase text-xs shadow-lg shadow-red-200 active:scale-95 transition-all disabled:opacity-50 disabled:grayscale"
                >
                  {isSubmittingReport ? (
                    <i className="fa-solid fa-circle-notch animate-spin mr-2"></i>
                  ) : (
                    <i className="fa-solid fa-paper-plane mr-2"></i>
                  )}
                  {isSubmittingReport ? 'Enviando...' : 'Enviar Denúncia'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ItemDetails;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import Layout from './components/Layout';
import ItemCard from './components/ItemCard';
import ItemDetails from './components/ItemDetails';
import ChatView from './components/ChatView';
import MapView from './components/MapView';
import DeliveryTrackingView from './components/DeliveryTrackingView';
import NotificationDrawer from './components/NotificationDrawer';
import { Item, ItemStatus, Category, Message, Notification } from './types';
import { INITIAL_ITEMS, MOZAMBIQUE_PROVINCES, SYSTEM_FEE_PERCENT } from './constants';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'feed' | 'post' | 'profile'>('feed');
  const [viewMode, setViewMode] = useState<'list' | 'map'>('list');
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [trackingItemId, setTrackingItemId] = useState<string | null>(null);
  const watchIdRef = useRef<number | null>(null);

  // Estados de navegação e edição no Perfil
  const [profileView, setProfileView] = useState<'main' | 'my-posts'>('main');
  const [editingItem, setEditingItem] = useState<Item | null>(null);

  // Inicialização de estado
  const [items, setItems] = useState<Item[]>(() => {
    const saved = localStorage.getItem('achei_items');
    return saved ? JSON.parse(saved) : INITIAL_ITEMS;
  });

  const [messages, setMessages] = useState<Message[]>(() => {
    const saved = localStorage.getItem('achei_messages');
    return saved ? JSON.parse(saved) : [];
  });

  const [notifications, setNotifications] = useState<Notification[]>(() => {
    const saved = localStorage.getItem('achei_notifications');
    return saved ? JSON.parse(saved) : [];
  });

  const [selectedItem, setSelectedItem] = useState<Item | null>(null);
  const [activeChat, setActiveChat] = useState<Item | null>(null);
  const [showFilters, setShowFilters] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [isViewingDelivery, setIsViewingDelivery] = useState(false);

  const [filters, setFilters] = useState({
    status: 'ALL' as ItemStatus | 'ALL',
    category: 'ALL' as Category | 'ALL',
    province: 'ALL' as string | 'ALL',
    date: '' as string,
    searchQuery: ''
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [newItem, setNewItem] = useState<Partial<Item>>({
    status: ItemStatus.LOST,
    category: Category.DOCUMENTS,
    province: 'Maputo Cidade',
    date: new Date().toISOString().split('T')[0]
  });

  // Monitorar status de rede
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Persistência
  useEffect(() => {
    localStorage.setItem('achei_items', JSON.stringify(items));
  }, [items]);
  useEffect(() => {
    localStorage.setItem('achei_messages', JSON.stringify(messages));
  }, [messages]);
  useEffect(() => {
    localStorage.setItem('achei_notifications', JSON.stringify(notifications));
  }, [notifications]);

  // Lógica de Rastreamento em Tempo Real
  const startTracking = (itemId: string) => {
    if (!("geolocation" in navigator)) {
      alert("Geolocalização não disponível.");
      return;
    }

    setTrackingItemId(itemId);
    setItems(prev => prev.map(i => i.id === itemId ? { ...i, isTrackingActive: true, status: ItemStatus.IN_TRANSIT } : i));

    watchIdRef.current = navigator.geolocation.watchPosition(
      (position) => {
        const { latitude, longitude } = position.coords;
        setItems(prev => prev.map(i => i.id === itemId ? { 
          ...i, 
          transitLatitude: latitude, 
          transitLongitude: longitude 
        } : i));
      },
      (error) => {
        console.error("Erro no rastreamento:", error);
        stopTracking(itemId);
      },
      { enableHighAccuracy: true, maximumAge: 0 }
    );

    const deliveryNotif: Notification = {
      id: Math.random().toString(36).substr(2, 5),
      type: 'DELIVERY',
      title: 'Entrega Iniciada!',
      description: 'O transportador iniciou o percurso. Acompanhe no mapa em tempo real.',
      itemId: itemId,
      timestamp: new Date().toISOString(),
      isRead: false
    };
    setNotifications(prev => [deliveryNotif, ...prev]);
  };

  const stopTracking = (itemId: string) => {
    if (watchIdRef.current !== null) {
      navigator.geolocation.clearWatch(watchIdRef.current);
      watchIdRef.current = null;
    }
    setTrackingItemId(null);
    setItems(prev => prev.map(i => i.id === itemId ? { ...i, isTrackingActive: false } : i));
  };

  const handleFinishDelivery = (itemId: string) => {
    stopTracking(itemId);

    // Atualizar status do item para reunido
    setItems(prev => prev.map(i => i.id === itemId ? { 
      ...i, 
      status: ItemStatus.REUNITED,
      isTrackingActive: false 
    } : i));

    // Adicionar notificação de conclusão
    const completionNotif: Notification = {
      id: Math.random().toString(36).substr(2, 5),
      type: 'DELIVERY',
      title: 'Entrega Concluída!',
      description: 'O item foi entregue com sucesso ao proprietário. Obrigado por usar o Achei! MZ.',
      itemId: itemId,
      timestamp: new Date().toISOString(),
      isRead: false
    };
    setNotifications(prev => [completionNotif, ...prev]);

    // Enviar mensagem automática no chat
    handleSendMessage("O item foi entregue com sucesso! 🎉");

    alert("Entrega finalizada com sucesso!");
  };

  const activeFiltersCount = useMemo(() => {
    let count = 0;
    if (filters.status !== 'ALL') count++;
    if (filters.category !== 'ALL') count++;
    if (filters.province !== 'ALL') count++;
    if (filters.date !== '') count++;
    return count;
  }, [filters]);

  const unreadNotificationsCount = useMemo(() => {
    return notifications.filter(n => !n.isRead).length;
  }, [notifications]);

  const filteredItems = useMemo(() => {
    return items.filter(item => {
      const statusMatch = filters.status === 'ALL' || item.status === filters.status;
      const categoryMatch = filters.category === 'ALL' || item.category === filters.category;
      const provinceMatch = filters.province === 'ALL' || item.province === filters.province;
      const dateMatch = !filters.date || item.date === filters.date;
      const searchMatch = !filters.searchQuery || 
                          item.title.toLowerCase().includes(filters.searchQuery.toLowerCase()) || 
                          item.description.toLowerCase().includes(filters.searchQuery.toLowerCase());

      return statusMatch && categoryMatch && provinceMatch && dateMatch && searchMatch;
    }).sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  }, [items, filters]);

  const handlePostSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    const id = Math.random().toString(36).substr(2, 9);
    const lat = -25.9692 + (Math.random() - 0.5) * 0.05;
    const lng = 32.5732 + (Math.random() - 0.5) * 0.05;

    const item: Item = {
      id,
      title: newItem.title || 'Sem Título',
      description: newItem.description || '',
      category: newItem.category as Category,
      status: newItem.status as ItemStatus,
      location: newItem.location || 'N/A',
      province: newItem.province || 'Maputo Cidade',
      date: newItem.date || new Date().toISOString(),
      reward: newItem.reward,
      imageUrl: `https://picsum.photos/seed/${id}/400/300`,
      imageUrls: [`https://picsum.photos/seed/${id}/400/300`],
      userId: 'currentUser',
      ownerName: 'Utilizador Moz',
      ownerPhone: '+258840000000',
      createdAt: new Date().toISOString(),
      latitude: lat,
      longitude: lng
    };
    setItems(prev => [item, ...prev]);
    setIsSubmitting(false);
    setActiveTab('feed');
  };

  const handleEditSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingItem) return;

    setItems(prev => prev.map(i => i.id === editingItem.id ? editingItem : i));
    setEditingItem(null);
    alert("Item atualizado com sucesso!");
  };

  const handleSendMessage = (text: string) => {
    if (!activeChat) return;
    const msg: Message = {
      id: Math.random().toString(36).substr(2, 9),
      itemId: activeChat.id,
      senderId: 'currentUser',
      receiverId: activeChat.userId,
      text,
      timestamp: new Date().toISOString()
    };
    setMessages(prev => [...prev, msg]);
  };

  const handleNotificationClick = (notif: Notification) => {
    const item = items.find(i => i.id === notif.itemId);
    if (item) {
      if (notif.type === 'DELIVERY') {
        setSelectedItem(item);
        setIsViewingDelivery(true);
      } else {
        setSelectedItem(item);
      }
      setNotifications(prev => prev.map(n => n.id === notif.id ? { ...n, isRead: true } : n));
      setShowNotifications(false);
    }
  };

  const myItems = useMemo(() => items.filter(i => i.userId === 'currentUser'), [items]);

  const renderFeed = () => (
    <div className="h-full flex flex-col">
      <div className="p-4 space-y-4 bg-white border-b shadow-sm z-10">
        <div className="flex items-center justify-between">
          <h2 className="text-xl font-black text-gray-900 border-l-4 border-[#d21034] pl-3 uppercase">
            Radar Moçambique
          </h2>
          <div className="flex bg-gray-100 p-1 rounded-xl">
            <button onClick={() => setViewMode('list')} className={`p-2 px-4 rounded-lg text-[10px] font-black uppercase transition-all ${viewMode === 'list' ? 'bg-white shadow-sm text-[#009739]' : 'text-gray-400'}`}>
              <i className="fa-solid fa-list mr-2"></i> Lista
            </button>
            <button onClick={() => setViewMode('map')} className={`p-2 px-4 rounded-lg text-[10px] font-black uppercase transition-all ${viewMode === 'map' ? 'bg-white shadow-sm text-[#009739]' : 'text-gray-400'}`}>
              <i className="fa-solid fa-map-location-dot mr-2"></i> Mapa
            </button>
          </div>
        </div>

        <div className="flex gap-2">
          <div className="relative flex-1">
            <i className="fa-solid fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"></i>
            <input 
              type="text" 
              placeholder="Ex: BI, Chaves, Cão..." 
              className="w-full bg-gray-50 border-2 border-transparent focus:border-[#009739] rounded-xl py-3 pl-10 pr-4 outline-none transition-all text-sm"
              value={filters.searchQuery}
              onChange={(e) => setFilters({ ...filters, searchQuery: e.target.value })}
            />
          </div>
          <button onClick={() => setShowFilters(!showFilters)} className={`px-4 rounded-xl border-2 transition-all flex items-center gap-2 ${showFilters || activeFiltersCount > 0 ? 'bg-[#fce100] border-[#fce100] text-black' : 'bg-white border-gray-100 text-gray-400'}`}>
            <i className="fa-solid fa-sliders"></i>
            {activeFiltersCount > 0 && <span className="bg-black text-white text-[10px] rounded-full w-4 h-4 flex items-center justify-center font-bold">{activeFiltersCount}</span>}
          </button>
        </div>

        {showFilters && (
          <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100 grid grid-cols-2 gap-3 animate-in fade-in slide-in-from-top-2 duration-300">
            <div className="col-span-2">
              <label className="text-[10px] font-black text-gray-400 uppercase mb-1 block">Estado</label>
              <div className="flex gap-2">
                {['ALL', ItemStatus.LOST, ItemStatus.FOUND].map((s) => (
                  <button key={s} onClick={() => setFilters({...filters, status: s as any})} className={`flex-1 py-2 rounded-lg text-xs font-bold border-2 transition-all ${filters.status === s ? 'bg-black border-black text-white' : 'bg-white border-gray-200 text-gray-400'}`}>
                    {s === 'ALL' ? 'Todos' : s === ItemStatus.LOST ? 'Perdido' : 'Achado'}
                  </button>
                ))}
              </div>
            </div>
            <div>
              <label className="text-[10px] font-black text-gray-400 uppercase mb-1 block">Província</label>
              <select className="w-full bg-white border-2 border-gray-200 rounded-lg p-2 text-xs font-semibold outline-none" value={filters.province} onChange={e => setFilters({...filters, province: e.target.value})}>
                <option value="ALL">Todas</option>
                {MOZAMBIQUE_PROVINCES.map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>
          </div>
        )}
      </div>

      <div className="flex-1 overflow-hidden">
        {viewMode === 'list' ? (
          <div className="p-4 grid grid-cols-2 gap-4 overflow-y-auto h-full pb-24 no-scrollbar">
            {filteredItems.map(item => (
              <ItemCard key={item.id} item={item} onViewDetails={setSelectedItem} />
            ))}
          </div>
        ) : (
          <div className="w-full h-full pb-20">
             <MapView items={filteredItems} onViewDetails={setSelectedItem} />
          </div>
        )}
      </div>
    </div>
  );

  const previewNewReward = newItem.reward ? newItem.reward * (1 - SYSTEM_FEE_PERCENT) : 0;
  const previewEditReward = editingItem?.reward ? editingItem.reward * (1 - SYSTEM_FEE_PERCENT) : 0;

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={setActiveTab} 
      notificationCount={unreadNotificationsCount}
      onToggleNotifications={() => setShowNotifications(!showNotifications)}
      isOnline={isOnline}
    >
      {showNotifications && (
        <NotificationDrawer 
          notifications={notifications} 
          onClose={() => setShowNotifications(false)}
          onNotificationClick={handleNotificationClick}
          onClear={() => setNotifications([])}
        />
      )}

      {isViewingDelivery && selectedItem ? (
        <DeliveryTrackingView 
          item={items.find(i => i.id === selectedItem.id) || selectedItem} 
          onBack={() => setIsViewingDelivery(false)} 
        />
      ) : activeChat ? (
        <ChatView 
          item={items.find(i => i.id === activeChat.id) || activeChat} 
          messages={messages.filter(m => m.itemId === activeChat.id)}
          onSendMessage={handleSendMessage}
          onBack={() => setActiveChat(null)}
          notificationCount={unreadNotificationsCount}
          isTracking={activeChat.isTrackingActive}
          onStartTracking={() => startTracking(activeChat.id)}
          onStopTracking={() => stopTracking(activeChat.id)}
          onFinishDelivery={() => handleFinishDelivery(activeChat.id)}
          onViewTracking={() => setIsViewingDelivery(true)}
        />
      ) : selectedItem ? (
        <ItemDetails 
          item={selectedItem} 
          allContextItems={items}
          onBack={() => setSelectedItem(null)} 
          onStartChat={(item) => setActiveChat(item)}
          onViewItem={(item) => setSelectedItem(item)}
        />
      ) : (
        <>
          {activeTab === 'feed' && renderFeed()}
          {activeTab === 'post' && (
             <div className="p-6 pb-24 overflow-y-auto h-full no-scrollbar">
                <h2 className="text-2xl font-black mb-6 text-gray-900 border-l-8 border-[#fce100] pl-4 uppercase">Novo Registo</h2>
                <form onSubmit={handlePostSubmit} className="space-y-5">
                  <div>
                    <label className="block text-xs font-black text-gray-500 uppercase mb-2">Estado</label>
                    <div className="grid grid-cols-2 gap-3">
                      <button type="button" onClick={() => setNewItem({...newItem, status: ItemStatus.LOST})} className={`p-4 rounded-2xl border-2 font-black transition-all ${newItem.status === ItemStatus.LOST ? 'border-[#d21034] bg-[#d21034] text-white shadow-lg' : 'border-gray-100 bg-gray-50 text-gray-400'}`}>PERDI</button>
                      <button type="button" onClick={() => setNewItem({...newItem, status: ItemStatus.FOUND})} className={`p-4 rounded-2xl border-2 font-black transition-all ${newItem.status === ItemStatus.FOUND ? 'border-[#009739] bg-[#009739] text-white shadow-lg' : 'border-gray-100 bg-gray-50 text-gray-400'}`}>ACHEI</button>
                    </div>
                  </div>
                  <div className="bg-gray-50 p-6 rounded-3xl space-y-4 border border-gray-100">
                    <input required className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 outline-none font-semibold shadow-sm" placeholder="Título do Item..." value={newItem.title || ''} onChange={e => setNewItem({...newItem, title: e.target.value})} />
                    <select className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 text-sm font-bold shadow-sm" value={newItem.category} onChange={e => setNewItem({...newItem, category: e.target.value as Category})}>
                      {Object.values(Category).map(cat => <option key={cat} value={cat}>{cat}</option>)}
                    </select>
                    <select className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 text-sm font-bold shadow-sm" value={newItem.province} onChange={e => setNewItem({...newItem, province: e.target.value})}>
                      {MOZAMBIQUE_PROVINCES.map(p => <option key={p} value={p}>{p}</option>)}
                    </select>
                    <input className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 outline-none font-semibold shadow-sm" placeholder="Localização..." value={newItem.location || ''} onChange={e => setNewItem({...newItem, location: e.target.value})} />
                    <div className="space-y-2">
                       <input type="number" className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 outline-none font-semibold shadow-sm" placeholder="Recompensa (Opcional - MT)" value={newItem.reward || ''} onChange={e => setNewItem({...newItem, reward: parseInt(e.target.value) || 0})} />
                       {newItem.reward ? (
                         <div className="bg-yellow-100/50 p-3 rounded-xl border border-yellow-200">
                            <div className="text-[9px] font-black text-gray-500 uppercase">Recebimento Estimado (93%)</div>
                            <div className="text-xs font-black text-[#009739]">{previewNewReward.toLocaleString()} MT</div>
                            <p className="text-[8px] font-bold text-gray-400 mt-1 uppercase italic">* Taxa de 7% retida para manutenção e desenvolvimento.</p>
                         </div>
                       ) : null}
                    </div>
                    <textarea className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 h-24 resize-none font-medium shadow-sm" placeholder="Descrição..." value={newItem.description || ''} onChange={e => setNewItem({...newItem, description: e.target.value})}></textarea>
                  </div>
                  <button disabled={isSubmitting} className="w-full bg-black text-[#fce100] py-5 rounded-2xl font-black shadow-xl uppercase tracking-widest disabled:opacity-50">
                    {isSubmitting ? 'Publicando...' : 'Publicar Agora'}
                  </button>
                </form>
              </div>
          )}
          {activeTab === 'profile' && (
             <div className="p-6 text-center pb-24 h-full overflow-y-auto no-scrollbar relative">
                {editingItem ? (
                  <div className="animate-in slide-in-from-bottom duration-300">
                    <button onClick={() => setEditingItem(null)} className="flex items-center text-[#009739] mb-4 gap-2 font-black uppercase text-xs">
                      <i className="fa-solid fa-arrow-left"></i> Cancelar Edição
                    </button>
                    <h2 className="text-xl font-black mb-6 text-left border-l-8 border-[#009739] pl-4 uppercase">Editar Item</h2>
                    <form onSubmit={handleEditSubmit} className="space-y-4 text-left">
                       <div className="bg-gray-50 p-6 rounded-3xl space-y-4 border border-gray-100">
                          <label className="block text-[10px] font-black text-gray-400 uppercase ml-1">Título</label>
                          <input required className="w-full bg-white border-2 border-gray-100 focus:border-[#009739] rounded-xl p-3 outline-none font-semibold" value={editingItem.title} onChange={e => setEditingItem({...editingItem, title: e.target.value})} />

                          <label className="block text-[10px] font-black text-gray-400 uppercase ml-1">Descrição</label>
                          <textarea className="w-full bg-white border-2 border-gray-100 focus:border-[#009739] rounded-xl p-3 h-24 resize-none font-medium" value={editingItem.description} onChange={e => setEditingItem({...editingItem, description: e.target.value})}></textarea>

                          <div className="grid grid-cols-2 gap-3">
                            <div>
                              <label className="block text-[10px] font-black text-gray-400 uppercase mb-1 ml-1">Categoria</label>
                              <select className="w-full bg-white border-2 border-gray-100 rounded-xl p-2 text-xs font-bold" value={editingItem.category} onChange={e => setEditingItem({...editingItem, category: e.target.value as Category})}>
                                {Object.values(Category).map(cat => <option key={cat} value={cat}>{cat}</option>)}
                              </select>
                            </div>
                            <div>
                              <label className="block text-[10px] font-black text-gray-400 uppercase mb-1 ml-1">Província</label>
                              <select className="w-full bg-white border-2 border-gray-100 rounded-xl p-2 text-xs font-bold" value={editingItem.province} onChange={e => setEditingItem({...editingItem, province: e.target.value})}>
                                {MOZAMBIQUE_PROVINCES.map(p => <option key={p} value={p}>{p}</option>)}
                              </select>
                            </div>
                          </div>

                          <label className="block text-[10px] font-black text-gray-400 uppercase ml-1">Recompensa (MT)</label>
                          <input type="number" className="w-full bg-white border-2 border-gray-100 focus:border-[#009739] rounded-xl p-3 outline-none font-semibold" value={editingItem.reward || ''} onChange={e => setEditingItem({...editingItem, reward: parseInt(e.target.value) || 0})} />
                          {editingItem.reward ? (
                             <div className="bg-[#fce100]/20 p-3 rounded-xl border border-[#fce100]/30">
                                <div className="text-[8px] font-black text-gray-500 uppercase">Recebimento Estimado (Líquido)</div>
                                <div className="text-xs font-black text-[#009739]">{previewEditReward.toLocaleString()} MT</div>
                                <div className="text-[7px] font-bold text-gray-400 mt-1 uppercase">Taxa de 7% aplicada sobre o total recebido.</div>
                             </div>
                          ) : null}
                       </div>
                       <button type="submit" className="w-full bg-[#009739] text-white py-5 rounded-2xl font-black shadow-xl uppercase tracking-widest active:scale-95 transition-all">
                         Guardar Alterações
                       </button>
                    </form>
                  </div>
                ) : profileView === 'my-posts' ? (
                  <div className="animate-in slide-in-from-right duration-300">
                    <button onClick={() => setProfileView('main')} className="flex items-center text-[#009739] mb-6 gap-2 font-black uppercase text-xs">
                      <i className="fa-solid fa-arrow-left"></i> Voltar ao Perfil
                    </button>
                    <h2 className="text-xl font-black mb-6 text-left border-l-8 border-[#d21034] pl-4 uppercase">Meus Registos</h2>
                    {myItems.length === 0 ? (
                      <div className="py-20 opacity-30">
                        <i className="fa-solid fa-box-open text-5xl mb-4"></i>
                        <p className="font-black uppercase text-sm">Nada publicado ainda</p>
                      </div>
                    ) : (
                      <div className="space-y-4">
                        {myItems.map(item => (
                          <div key={item.id} className="bg-white border-2 border-gray-50 rounded-[2rem] p-4 flex gap-4 items-center shadow-sm">
                            <img src={item.imageUrl} className="w-16 h-16 rounded-2xl object-cover shadow-inner" alt="" />
                            <div className="flex-1 text-left min-w-0">
                               <div className="text-[8px] font-black text-[#009739] uppercase mb-0.5">{item.category}</div>
                               <h3 className="font-black text-xs uppercase truncate leading-tight">{item.title}</h3>
                               <div className="text-[10px] font-bold text-gray-400">{item.status === ItemStatus.LOST ? 'Perdido' : 'Achado'}</div>
                            </div>
                            <button 
                              onClick={() => setEditingItem(item)}
                              className="w-10 h-10 bg-gray-50 text-gray-400 hover:bg-[#fce100] hover:text-black rounded-xl flex items-center justify-center transition-colors"
                            >
                              <i className="fa-solid fa-pen-to-square"></i>
                            </button>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                ) : (
                  <div className="animate-in fade-in duration-500">
                    <div className="w-28 h-28 bg-gradient-to-tr from-[#009739] to-[#fce100] rounded-full mx-auto mb-6 p-1">
                      <div className="bg-white rounded-full w-full h-full flex items-center justify-center text-[#d21034] text-4xl font-black overflow-hidden border-4 border-white">
                        <img src="https://api.dicebear.com/7.x/avataaars/svg?seed=Moz" alt="Profile" />
                      </div>
                    </div>
                    <h2 className="text-2xl font-black text-gray-900 uppercase">Utilizador Moz</h2>
                    <p className="text-gray-400 font-bold text-xs mb-8 uppercase tracking-widest">Maputo, Moçambique</p>

                    <div className="grid grid-cols-2 gap-4 mb-8">
                      <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100">
                        <div className="text-2xl font-black text-[#009739]">{myItems.length}</div>
                        <div className="text-[8px] font-black text-gray-400 uppercase">Publicações</div>
                      </div>
                      <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100">
                        <div className="text-2xl font-black text-[#d21034]">2</div>
                        <div className="text-[8px] font-black text-gray-400 uppercase">Resgates</div>
                      </div>
                    </div>

                    <div className="space-y-3">
                      <button 
                        onClick={() => setProfileView('my-posts')}
                        className="w-full bg-white border-2 border-gray-50 p-4 rounded-2xl flex items-center gap-4 hover:border-[#fce100] transition-colors group text-left"
                      >
                        <div className="bg-emerald-100 text-[#009739] p-3 rounded-xl group-hover:bg-[#009739] group-hover:text-white transition-colors"><i className="fa-solid fa-briefcase"></i></div>
                        <span className="font-black text-gray-700 uppercase text-xs">Meus Registos</span>
                      </button>
                      <button className="w-full bg-white border-2 border-gray-50 p-4 rounded-2xl flex items-center gap-4 hover:border-[#fce100] transition-colors group text-left">
                        <div className="bg-red-100 text-[#d21034] p-3 rounded-xl group-hover:bg-[#d21034] group-hover:text-white transition-colors"><i className="fa-solid fa-shield-halved"></i></div>
                        <span className="font-black text-gray-700 uppercase text-xs">Privacidade e Segurança</span>
                      </button>
                      <button className="w-full bg-white border-2 border-gray-50 p-4 rounded-2xl flex items-center gap-4 hover:border-red-100 transition-colors group text-left">
                        <div className="bg-gray-100 text-gray-400 p-3 rounded-xl group-hover:bg-red-500 group-hover:text-white transition-colors"><i className="fa-solid fa-right-from-bracket"></i></div>
                        <span className="font-black text-gray-700 uppercase text-xs">Sair da Conta</span>
                      </button>
                    </div>
                  </div>
                )}
              </div>
          )}
        </>
      )}
    </Layout>
  );
};

export default App;

export enum ItemStatus {
  LOST = 'LOST',
  FOUND = 'FOUND',
  REUNITED = 'REUNITED',
  IN_TRANSIT = 'IN_TRANSIT'
}

export enum Category {
  DOCUMENTS = 'Documentos',
  ELECTRONICS = 'Eletrónicos',
  PETS = 'Animais',
  WALLETS = 'Carteiras/Bolsas',
  KEYS = 'Chaves',
  OTHERS = 'Outros'
}

export interface User {
  id: string;
  name: string;
  phone: string;
  email: string;
}

export interface Item {
  id: string;
  title: string;
  description: string;
  category: Category;
  status: ItemStatus;
  location: string;
  province: string;
  reward?: number;
  date: string;
  imageUrl?: string;
  imageUrls?: string[];
  userId: string;
  ownerName?: string; // Nome de quem publicou
  ownerPhone?: string; // Telefone de quem publicou
  createdAt: string;
  latitude?: number;
  longitude?: number;
  // Propriedades para rastreamento
  transitLatitude?: number;
  transitLongitude?: number;
  isTrackingActive?: boolean;
}

export interface Message {
  id: string;
  itemId: string;
  senderId: string;
  receiverId: string;
  text?: string;
  timestamp: string;
  type?: 'text' | 'image' | 'location';
  mediaUrl?: string;
  latitude?: number;
  longitude?: number;
}

export interface Notification {
  id: string;
  type: 'MATCH' | 'MESSAGE' | 'REWARD' | 'DELIVERY';
  title: string;
  description: string;
  itemId: string;
  timestamp: string;
  isRead: boolean;
}

export interface MatchResult {
  similarity: number;
  reasoning: string;
  isMatch: boolean;
}

import React, { useState, useMemo, useEffect, useRef } from 'react';
import Layout from './components/Layout';
import ItemCard from './components/ItemCard';
import ItemDetails from './components/ItemDetails';
import ChatView from './components/ChatView';
import MapView from './components/MapView';
import DeliveryTrackingView from './components/DeliveryTrackingView';
import NotificationDrawer from './components/NotificationDrawer';
import { Item, ItemStatus, Category, Message, Notification } from './types';
import { INITIAL_ITEMS, MOZAMBIQUE_PROVINCES, SYSTEM_FEE_PERCENT } from './constants';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'feed' | 'post' | 'profile'>('feed');
  const [viewMode, setViewMode] = useState<'list' | 'map'>('list');
  const [isOnline, setIsOnline] = useState(navigator.onLine);
  const [trackingItemId, setTrackingItemId] = useState<string | null>(null);
  const watchIdRef = useRef<number | null>(null);

  // Estados de navegação e edição no Perfil
  const [profileView, setProfileView] = useState<'main' | 'my-posts'>('main');
  const [editingItem, setEditingItem] = useState<Item | null>(null);

  // Inicialização de estado
  const [items, setItems] = useState<Item[]>(() => {
    const saved = localStorage.getItem('achei_items');
    return saved ? JSON.parse(saved) : INITIAL_ITEMS;
  });

  const [messages, setMessages] = useState<Message[]>(() => {
    const saved = localStorage.getItem('achei_messages');
    return saved ? JSON.parse(saved) : [];
  });

  const [notifications, setNotifications] = useState<Notification[]>(() => {
    const saved = localStorage.getItem('achei_notifications');
    return saved ? JSON.parse(saved) : [];
  });

  const [selectedItem, setSelectedItem] = useState<Item | null>(null);
  const [activeChat, setActiveChat] = useState<Item | null>(null);
  const [showFilters, setShowFilters] = useState(false);
  const [showNotifications, setShowNotifications] = useState(false);
  const [isViewingDelivery, setIsViewingDelivery] = useState(false);

  const [filters, setFilters] = useState({
    status: 'ALL' as ItemStatus | 'ALL',
    category: 'ALL' as Category | 'ALL',
    province: 'ALL' as string | 'ALL',
    date: '' as string,
    searchQuery: ''
  });

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [newItem, setNewItem] = useState<Partial<Item>>({
    status: ItemStatus.LOST,
    category: Category.DOCUMENTS,
    province: 'Maputo Cidade',
    date: new Date().toISOString().split('T')[0]
  });

  // Monitorar status de rede
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Persistência
  useEffect(() => {
    localStorage.setItem('achei_items', JSON.stringify(items));
  }, [items]);
  useEffect(() => {
    localStorage.setItem('achei_messages', JSON.stringify(messages));
  }, [messages]);
  useEffect(() => {
    localStorage.setItem('achei_notifications', JSON.stringify(notifications));
  }, [notifications]);

  // Lógica de Rastreamento em Tempo Real
  const startTracking = (itemId: string) => {
    if (!("geolocation" in navigator)) {
      alert("Geolocalização não disponível.");
      return;
    }

    setTrackingItemId(itemId);
    setItems(prev => prev.map(i => i.id === itemId ? { ...i, isTrackingActive: true, status: ItemStatus.IN_TRANSIT } : i));

    watchIdRef.current = navigator.geolocation.watchPosition(
      (position) => {
        const { latitude, longitude } = position.coords;
        setItems(prev => prev.map(i => i.id === itemId ? { 
          ...i, 
          transitLatitude: latitude, 
          transitLongitude: longitude 
        } : i));
      },
      (error) => {
        console.error("Erro no rastreamento:", error);
        stopTracking(itemId);
      },
      { enableHighAccuracy: true, maximumAge: 0 }
    );

    const deliveryNotif: Notification = {
      id: Math.random().toString(36).substr(2, 5),
      type: 'DELIVERY',
      title: 'Entrega Iniciada!',
      description: 'O transportador iniciou o percurso. Acompanhe no mapa em tempo real.',
      itemId: itemId,
      timestamp: new Date().toISOString(),
      isRead: false
    };
    setNotifications(prev => [deliveryNotif, ...prev]);
  };

  const stopTracking = (itemId: string) => {
    if (watchIdRef.current !== null) {
      navigator.geolocation.clearWatch(watchIdRef.current);
      watchIdRef.current = null;
    }
    setTrackingItemId(null);
    setItems(prev => prev.map(i => i.id === itemId ? { ...i, isTrackingActive: false } : i));
  };

  const handleFinishDelivery = (itemId: string) => {
    stopTracking(itemId);

    // Atualizar status do item para reunido
    setItems(prev => prev.map(i => i.id === itemId ? { 
      ...i, 
      status: ItemStatus.REUNITED,
      isTrackingActive: false 
    } : i));

    // Adicionar notificação de conclusão
    const completionNotif: Notification = {
      id: Math.random().toString(36).substr(2, 5),
      type: 'DELIVERY',
      title: 'Entrega Concluída!',
      description: 'O item foi entregue com sucesso ao proprietário. Obrigado por usar o Achei! MZ.',
      itemId: itemId,
      timestamp: new Date().toISOString(),
      isRead: false
    };
    setNotifications(prev => [completionNotif, ...prev]);

    // Enviar mensagem automática no chat
    handleSendMessage("O item foi entregue com sucesso! 🎉");

    alert("Entrega finalizada com sucesso!");
  };

  const activeFiltersCount = useMemo(() => {
    let count = 0;
    if (filters.status !== 'ALL') count++;
    if (filters.category !== 'ALL') count++;
    if (filters.province !== 'ALL') count++;
    if (filters.date !== '') count++;
    return count;
  }, [filters]);

  const unreadNotificationsCount = useMemo(() => {
    return notifications.filter(n => !n.isRead).length;
  }, [notifications]);

  const filteredItems = useMemo(() => {
    return items.filter(item => {
      const statusMatch = filters.status === 'ALL' || item.status === filters.status;
      const categoryMatch = filters.category === 'ALL' || item.category === filters.category;
      const provinceMatch = filters.province === 'ALL' || item.province === filters.province;
      const dateMatch = !filters.date || item.date === filters.date;
      const searchMatch = !filters.searchQuery || 
                          item.title.toLowerCase().includes(filters.searchQuery.toLowerCase()) || 
                          item.description.toLowerCase().includes(filters.searchQuery.toLowerCase());

      return statusMatch && categoryMatch && provinceMatch && dateMatch && searchMatch;
    }).sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  }, [items, filters]);

  const handlePostSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    const id = Math.random().toString(36).substr(2, 9);
    const lat = -25.9692 + (Math.random() - 0.5) * 0.05;
    const lng = 32.5732 + (Math.random() - 0.5) * 0.05;

    const item: Item = {
      id,
      title: newItem.title || 'Sem Título',
      description: newItem.description || '',
      category: newItem.category as Category,
      status: newItem.status as ItemStatus,
      location: newItem.location || 'N/A',
      province: newItem.province || 'Maputo Cidade',
      date: newItem.date || new Date().toISOString(),
      reward: newItem.reward,
      imageUrl: `https://picsum.photos/seed/${id}/400/300`,
      imageUrls: [`https://picsum.photos/seed/${id}/400/300`],
      userId: 'currentUser',
      ownerName: 'Utilizador Moz',
      ownerPhone: '+258840000000',
      createdAt: new Date().toISOString(),
      latitude: lat,
      longitude: lng
    };
    setItems(prev => [item, ...prev]);
    setIsSubmitting(false);
    setActiveTab('feed');
  };

  const handleEditSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingItem) return;

    setItems(prev => prev.map(i => i.id === editingItem.id ? editingItem : i));
    setEditingItem(null);
    alert("Item atualizado com sucesso!");
  };

  const handleSendMessage = (
    text: string, 
    type: 'text' | 'image' | 'location' = 'text', 
    mediaUrl?: string, 
    coords?: { lat: number; lng: number }
  ) => {
    if (!activeChat) return;
    const msg: Message = {
      id: Math.random().toString(36).substr(2, 9),
      itemId: activeChat.id,
      senderId: 'currentUser',
      receiverId: activeChat.userId,
      text: text,
      type: type,
      mediaUrl: mediaUrl,
      latitude: coords?.lat,
      longitude: coords?.lng,
      timestamp: new Date().toISOString()
    };
    setMessages(prev => [...prev, msg]);
  };

  const handleNotificationClick = (notif: Notification) => {
    const item = items.find(i => i.id === notif.itemId);
    if (item) {
      if (notif.type === 'DELIVERY') {
        setSelectedItem(item);
        setIsViewingDelivery(true);
      } else {
        setSelectedItem(item);
      }
      setNotifications(prev => prev.map(n => n.id === notif.id ? { ...n, isRead: true } : n));
      setShowNotifications(false);
    }
  };

  const myItems = useMemo(() => items.filter(i => i.userId === 'currentUser'), [items]);

  const renderFeed = () => (
    <div className="h-full flex flex-col">
      <div className="p-4 space-y-4 bg-white border-b shadow-sm z-10">
        <div className="flex items-center justify-between">
          <h2 className="text-xl font-black text-gray-900 border-l-4 border-[#d21034] pl-3 uppercase">
            Radar Moçambique
          </h2>
          <div className="flex bg-gray-100 p-1 rounded-xl">
            <button onClick={() => setViewMode('list')} className={`p-2 px-4 rounded-lg text-[10px] font-black uppercase transition-all ${viewMode === 'list' ? 'bg-white shadow-sm text-[#009739]' : 'text-gray-400'}`}>
              <i className="fa-solid fa-list mr-2"></i> Lista
            </button>
            <button onClick={() => setViewMode('map')} className={`p-2 px-4 rounded-lg text-[10px] font-black uppercase transition-all ${viewMode === 'map' ? 'bg-white shadow-sm text-[#009739]' : 'text-gray-400'}`}>
              <i className="fa-solid fa-map-location-dot mr-2"></i> Mapa
            </button>
          </div>
        </div>

        <div className="flex gap-2">
          <div className="relative flex-1">
            <i className="fa-solid fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-gray-400"></i>
            <input 
              type="text" 
              placeholder="Ex: BI, Chaves, Cão..." 
              className="w-full bg-gray-50 border-2 border-transparent focus:border-[#009739] rounded-xl py-3 pl-10 pr-4 outline-none transition-all text-sm"
              value={filters.searchQuery}
              onChange={(e) => setFilters({ ...filters, searchQuery: e.target.value })}
            />
          </div>
          <button onClick={() => setShowFilters(!showFilters)} className={`px-4 rounded-xl border-2 transition-all flex items-center gap-2 ${showFilters || activeFiltersCount > 0 ? 'bg-[#fce100] border-[#fce100] text-black' : 'bg-white border-gray-100 text-gray-400'}`}>
            <i className="fa-solid fa-sliders"></i>
            {activeFiltersCount > 0 && <span className="bg-black text-white text-[10px] rounded-full w-4 h-4 flex items-center justify-center font-bold">{activeFiltersCount}</span>}
          </button>
        </div>

        {showFilters && (
          <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100 grid grid-cols-2 gap-3 animate-in fade-in slide-in-from-top-2 duration-300">
            <div className="col-span-2">
              <label className="text-[10px] font-black text-gray-400 uppercase mb-1 block">Estado</label>
              <div className="flex gap-2">
                {['ALL', ItemStatus.LOST, ItemStatus.FOUND].map((s) => (
                  <button key={s} onClick={() => setFilters({...filters, status: s as any})} className={`flex-1 py-2 rounded-lg text-xs font-bold border-2 transition-all ${filters.status === s ? 'bg-black border-black text-white' : 'bg-white border-gray-200 text-gray-400'}`}>
                    {s === 'ALL' ? 'Todos' : s === ItemStatus.LOST ? 'Perdido' : 'Achado'}
                  </button>
                ))}
              </div>
            </div>
            <div>
              <label className="text-[10px] font-black text-gray-400 uppercase mb-1 block">Província</label>
              <select className="w-full bg-white border-2 border-gray-200 rounded-lg p-2 text-xs font-semibold outline-none" value={filters.province} onChange={e => setFilters({...filters, province: e.target.value})}>
                <option value="ALL">Todas</option>
                {MOZAMBIQUE_PROVINCES.map(p => <option key={p} value={p}>{p}</option>)}
              </select>
            </div>
          </div>
        )}
      </div>

      <div className="flex-1 overflow-hidden">
        {viewMode === 'list' ? (
          <div className="p-4 grid grid-cols-2 gap-4 overflow-y-auto h-full pb-24 no-scrollbar">
            {filteredItems.map(item => (
              <ItemCard key={item.id} item={item} onViewDetails={setSelectedItem} />
            ))}
          </div>
        ) : (
          <div className="w-full h-full pb-20">
             <MapView items={filteredItems} onViewDetails={setSelectedItem} />
          </div>
        )}
      </div>
    </div>
  );

  const previewNewReward = newItem.reward ? newItem.reward * (1 - SYSTEM_FEE_PERCENT) : 0;
  const previewEditReward = editingItem?.reward ? editingItem.reward * (1 - SYSTEM_FEE_PERCENT) : 0;

  return (
    <Layout 
      activeTab={activeTab} 
      setActiveTab={setActiveTab} 
      notificationCount={unreadNotificationsCount}
      onToggleNotifications={() => setShowNotifications(!showNotifications)}
      isOnline={isOnline}
    >
      {showNotifications && (
        <NotificationDrawer 
          notifications={notifications} 
          onClose={() => setShowNotifications(false)}
          onNotificationClick={handleNotificationClick}
          onClear={() => setNotifications([])}
        />
      )}

      {isViewingDelivery && selectedItem ? (
        <DeliveryTrackingView 
          item={items.find(i => i.id === selectedItem.id) || selectedItem} 
          onBack={() => setIsViewingDelivery(false)} 
        />
      ) : activeChat ? (
        <ChatView 
          item={items.find(i => i.id === activeChat.id) || activeChat} 
          messages={messages.filter(m => m.itemId === activeChat.id)}
          onSendMessage={handleSendMessage}
          onBack={() => setActiveChat(null)}
          notificationCount={unreadNotificationsCount}
          isTracking={activeChat.isTrackingActive}
          onStartTracking={() => startTracking(activeChat.id)}
          onStopTracking={() => stopTracking(activeChat.id)}
          onFinishDelivery={() => handleFinishDelivery(activeChat.id)}
          onViewTracking={() => setIsViewingDelivery(true)}
        />
      ) : selectedItem ? (
        <ItemDetails 
          item={selectedItem} 
          allContextItems={items}
          onBack={() => setSelectedItem(null)} 
          onStartChat={(item) => setActiveChat(item)}
          onViewItem={(item) => setSelectedItem(item)}
        />
      ) : (
        <>
          {activeTab === 'feed' && renderFeed()}
          {activeTab === 'post' && (
             <div className="p-6 pb-24 overflow-y-auto h-full no-scrollbar">
                <h2 className="text-2xl font-black mb-6 text-gray-900 border-l-8 border-[#fce100] pl-4 uppercase">Novo Registo</h2>
                <form onSubmit={handlePostSubmit} className="space-y-5">
                  <div>
                    <label className="block text-xs font-black text-gray-500 uppercase mb-2">Estado</label>
                    <div className="grid grid-cols-2 gap-3">
                      <button type="button" onClick={() => setNewItem({...newItem, status: ItemStatus.LOST})} className={`p-4 rounded-2xl border-2 font-black transition-all ${newItem.status === ItemStatus.LOST ? 'border-[#d21034] bg-[#d21034] text-white shadow-lg' : 'border-gray-100 bg-gray-50 text-gray-400'}`}>PERDI</button>
                      <button type="button" onClick={() => setNewItem({...newItem, status: ItemStatus.FOUND})} className={`p-4 rounded-2xl border-2 font-black transition-all ${newItem.status === ItemStatus.FOUND ? 'border-[#009739] bg-[#009739] text-white shadow-lg' : 'border-gray-100 bg-gray-50 text-gray-400'}`}>ACHEI</button>
                    </div>
                  </div>
                  <div className="bg-gray-50 p-6 rounded-3xl space-y-4 border border-gray-100">
                    <input required className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 outline-none font-semibold shadow-sm" placeholder="Título do Item..." value={newItem.title || ''} onChange={e => setNewItem({...newItem, title: e.target.value})} />
                    <select className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 text-sm font-bold shadow-sm" value={newItem.category} onChange={e => setNewItem({...newItem, category: e.target.value as Category})}>
                      {Object.values(Category).map(cat => <option key={cat} value={cat}>{cat}</option>)}
                    </select>
                    <select className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 text-sm font-bold shadow-sm" value={newItem.province} onChange={e => setNewItem({...newItem, province: e.target.value})}>
                      {MOZAMBIQUE_PROVINCES.map(p => <option key={p} value={p}>{p}</option>)}
                    </select>
                    <input className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 outline-none font-semibold shadow-sm" placeholder="Localização..." value={newItem.location || ''} onChange={e => setNewItem({...newItem, location: e.target.value})} />
                    <div className="space-y-2">
                       <input type="number" className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 outline-none font-semibold shadow-sm" placeholder="Recompensa (Opcional - MT)" value={newItem.reward || ''} onChange={e => setNewItem({...newItem, reward: parseInt(e.target.value) || 0})} />
                       {newItem.reward ? (
                         <div className="bg-yellow-100/50 p-3 rounded-xl border border-yellow-200">
                            <div className="text-[9px] font-black text-gray-500 uppercase">Recebimento Estimado (93%)</div>
                            <div className="text-xs font-black text-[#009739]">{previewNewReward.toLocaleString()} MT</div>
                            <p className="text-[8px] font-bold text-gray-400 mt-1 uppercase italic">* Taxa de 7% retida para manutenção e desenvolvimento.</p>
                         </div>
                       ) : null}
                    </div>
                    <textarea className="w-full bg-white border-2 border-transparent focus:border-[#fce100] rounded-xl p-3 h-24 resize-none font-medium shadow-sm" placeholder="Descrição..." value={newItem.description || ''} onChange={e => setNewItem({...newItem, description: e.target.value})}></textarea>
                  </div>
                  <button disabled={isSubmitting} className="w-full bg-black text-[#fce100] py-5 rounded-2xl font-black shadow-xl uppercase tracking-widest disabled:opacity-50">
                    {isSubmitting ? 'Publicando...' : 'Publicar Agora'}
                  </button>
                </form>
              </div>
          )}
          {activeTab === 'profile' && (
             <div className="p-6 text-center pb-24 h-full overflow-y-auto no-scrollbar relative">
                {editingItem ? (
                  <div className="animate-in slide-in-from-bottom duration-300">
                    <button onClick={() => setEditingItem(null)} className="flex items-center text-[#009739] mb-4 gap-2 font-black uppercase text-xs">
                      <i className="fa-solid fa-arrow-left"></i> Cancelar Edição
                    </button>
                    <h2 className="text-xl font-black mb-6 text-left border-l-8 border-[#009739] pl-4 uppercase">Editar Item</h2>
                    <form onSubmit={handleEditSubmit} className="space-y-4 text-left">
                       <div className="bg-gray-50 p-6 rounded-3xl space-y-4 border border-gray-100">
                          <label className="block text-[10px] font-black text-gray-400 uppercase ml-1">Título</label>
                          <input required className="w-full bg-white border-2 border-gray-100 focus:border-[#009739] rounded-xl p-3 outline-none font-semibold" value={editingItem.title} onChange={e => setEditingItem({...editingItem, title: e.target.value})} />

                          <label className="block text-[10px] font-black text-gray-400 uppercase ml-1">Descrição</label>
                          <textarea className="w-full bg-white border-2 border-gray-100 focus:border-[#009739] rounded-xl p-3 h-24 resize-none font-medium" value={editingItem.description} onChange={e => setEditingItem({...editingItem, description: e.target.value})}></textarea>

                          <div className="grid grid-cols-2 gap-3">
                            <div>
                              <label className="block text-[10px] font-black text-gray-400 uppercase mb-1 ml-1">Categoria</label>
                              <select className="w-full bg-white border-2 border-gray-100 rounded-xl p-2 text-xs font-bold" value={editingItem.category} onChange={e => setEditingItem({...editingItem, category: e.target.value as Category})}>
                                {Object.values(Category).map(cat => <option key={cat} value={cat}>{cat}</option>)}
                              </select>
                            </div>
                            <div>
                              <label className="block text-[10px] font-black text-gray-400 uppercase mb-1 ml-1">Província</label>
                              <select className="w-full bg-white border-2 border-gray-100 rounded-xl p-2 text-xs font-bold" value={editingItem.province} onChange={e => setEditingItem({...editingItem, province: e.target.value})}>
                                {MOZAMBIQUE_PROVINCES.map(p => <option key={p} value={p}>{p}</option>)}
                              </select>
                            </div>
                          </div>

                          <label className="block text-[10px] font-black text-gray-400 uppercase ml-1">Recompensa (MT)</label>
                          <input type="number" className="w-full bg-white border-2 border-gray-100 focus:border-[#009739] rounded-xl p-3 outline-none font-semibold" value={editingItem.reward || ''} onChange={e => setEditingItem({...editingItem, reward: parseInt(e.target.value) || 0})} />
                          {editingItem.reward ? (
                             <div className="bg-[#fce100]/20 p-3 rounded-xl border border-[#fce100]/30">
                                <div className="text-[8px] font-black text-gray-500 uppercase">Recebimento Estimado (Líquido)</div>
                                <div className="text-xs font-black text-[#009739]">{previewEditReward.toLocaleString()} MT</div>
                                <div className="text-[7px] font-bold text-gray-400 mt-1 uppercase">Taxa de 7% aplicada sobre o total recebido.</div>
                             </div>
                          ) : null}
                       </div>
                       <button type="submit" className="w-full bg-[#009739] text-white py-5 rounded-2xl font-black shadow-xl uppercase tracking-widest active:scale-95 transition-all">
                         Guardar Alterações
                       </button>
                    </form>
                  </div>
                ) : profileView === 'my-posts' ? (
                  <div className="animate-in slide-in-from-right duration-300">
                    <button onClick={() => setProfileView('main')} className="flex items-center text-[#009739] mb-6 gap-2 font-black uppercase text-xs">
                      <i className="fa-solid fa-arrow-left"></i> Voltar ao Perfil
                    </button>
                    <h2 className="text-xl font-black mb-6 text-left border-l-8 border-[#d21034] pl-4 uppercase">Meus Registos</h2>
                    {myItems.length === 0 ? (
                      <div className="py-20 opacity-30">
                        <i className="fa-solid fa-box-open text-5xl mb-4"></i>
                        <p className="font-black uppercase text-sm">Nada publicado ainda</p>
                      </div>
                    ) : (
                      <div className="space-y-4">
                        {myItems.map(item => (
                          <div key={item.id} className="bg-white border-2 border-gray-50 rounded-[2rem] p-4 flex gap-4 items-center shadow-sm">
                            <img src={item.imageUrl} className="w-16 h-16 rounded-2xl object-cover shadow-inner" alt="" />
                            <div className="flex-1 text-left min-w-0">
                               <div className="text-[8px] font-black text-[#009739] uppercase mb-0.5">{item.category}</div>
                               <h3 className="font-black text-xs uppercase truncate leading-tight">{item.title}</h3>
                               <div className="text-[10px] font-bold text-gray-400">{item.status === ItemStatus.LOST ? 'Perdido' : 'Achado'}</div>
                            </div>
                            <button 
                              onClick={() => setEditingItem(item)}
                              className="w-10 h-10 bg-gray-50 text-gray-400 hover:bg-[#fce100] hover:text-black rounded-xl flex items-center justify-center transition-colors"
                            >
                              <i className="fa-solid fa-pen-to-square"></i>
                            </button>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                ) : (
                  <div className="animate-in fade-in duration-500">
                    <div className="w-28 h-28 bg-gradient-to-tr from-[#009739] to-[#fce100] rounded-full mx-auto mb-6 p-1">
                      <div className="bg-white rounded-full w-full h-full flex items-center justify-center text-[#d21034] text-4xl font-black overflow-hidden border-4 border-white">
                        <img src="https://api.dicebear.com/7.x/avataaars/svg?seed=Moz" alt="Profile" />
                      </div>
                    </div>
                    <h2 className="text-2xl font-black text-gray-900 uppercase">Utilizador Moz</h2>
                    <p className="text-gray-400 font-bold text-xs mb-8 uppercase tracking-widest">Maputo, Moçambique</p>

                    <div className="grid grid-cols-2 gap-4 mb-8">
                      <div className="bg-gray-50 p-4 rounded-2xl border border-gray-100">
                        <div className="text-2xl font-black text-[#009739]">{myItems.length}</div>
                        <div className="text-[8px] font-black text-gray-400 uppercase">Publicações</div>
