        />
        <div className={`absolute top-3 left-3 px-3 py-1 rounded-full text-[9px] font-black uppercase shadow-lg ${
          isLost ? 'bg-[#d21034] text-white' : 'bg-[#009739] text-white'
        }`}>
          {isLost ? 'Perdido' : 'Achado'}
