      <div className="p-4 space-y-1">
        <div className="flex items-center justify-between">
          <span className="text-[9px] text-[#009739] font-black uppercase tracking-widest">{item.category}</span>
          <span className="text-[9px] text-gray-400 font-bold">{new Date(item.date).toLocaleDateString('pt-MZ', { day: '2-digit', month: 'short' })}</span>
        </div>
        <h3 className="font-black text-gray-800 line-clamp-1 text-sm uppercase leading-tight group-hover:text-[#009739] transition-colors">{item.title}</h3>

        <div className="flex flex-col gap-1 mt-2">
          <div className="flex items-center text-gray-500 text-[10px] font-bold gap-1 bg-gray-50 p-1.5 rounded-lg">
            <i className="fa-solid fa-location-dot text-[#d21034]"></i>
            <span className="truncate">{item.province}</span>
          </div>

          <div className="flex items-center text-[8px] text-gray-300 font-black uppercase pl-1.5 gap-1 italic">
            <i className="fa-solid fa-clock text-[7px]"></i>
            Registado em: {new Date(item.createdAt).toLocaleDateString('pt-MZ', { day: '2-digit', month: '2-digit', year: '2-digit' })}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ItemCard;
